CREATE OR REPLACE FUNCTION public.demo_scan_mock_stop(p_run_id uuid DEFAULT NULL::uuid, p_cleanup boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_run_id uuid;
  v_changed integer := 0;
  v_deleted jsonb := null;
begin
  select id into v_run_id
  from public.demo_scan_mock_runs
  where (p_run_id is null or id = p_run_id)
  order by case when status = 'active' then 0 else 1 end, started_at desc
  limit 1;

  if p_cleanup then
    with x as (select * from public.demo_scan_mock_cleanup(p_run_id))
    select to_jsonb(x.*) into v_deleted from x;
    return jsonb_build_object('run_id', coalesce(v_run_id::text, p_run_id::text, 'all'), 'stopped', true, 'cleanup', true, 'deleted', v_deleted);
  end if;

  if v_run_id is null then
    return jsonb_build_object('run_id', null, 'stopped', false, 'cleanup', false, 'message', 'No demo run found.');
  end if;

  update public.sessions
  set status = 'cancelled', updated_at = now()
  where client_session_id like ('demo-scan:' || v_run_id::text || ':cycle:%')
    and status = 'active';
  get diagnostics v_changed = row_count;

  update public.demo_scan_mock_runs
  set status = 'stopped', stopped_at = now(), updated_at = now()
  where id = v_run_id;

  return jsonb_build_object('run_id', v_run_id::text, 'stopped', true, 'cleanup', false, 'cancelled_open_sessions', v_changed);
end $function$

CREATE OR REPLACE FUNCTION public.device_auth_cancel_enrollment_operation(p_operation_id uuid, p_device_id uuid, p_credential_id uuid, p_token_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_now timestamptz:=clock_timestamp();
  v_operation public.device_auth_enrollment_operations%rowtype;
  v_credential public.device_auth_credentials%rowtype;
begin
  if p_operation_id is null or p_device_id is null or p_credential_id is null
     or p_token_hash is null or length(p_token_hash)<>64 then
    raise exception using errcode='22023',message='operation and credential proof are required';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('custodial-enrollment-operation:'||p_operation_id::text,0));
  select * into v_operation from public.device_auth_enrollment_operations
   where operation_id=p_operation_id for update;
  if v_operation.operation_id is null
     or v_operation.device_id<>p_device_id
     or v_operation.credential_id<>p_credential_id then
    return jsonb_build_object('ok',false,'reason','operation_not_found');
  end if;
  select * into v_credential from public.device_auth_credentials
   where credential_id=p_credential_id and device_id=p_device_id and token_hash=p_token_hash;
  if v_credential.credential_id is null then
    return jsonb_build_object('ok',false,'reason','credential_mismatch');
  end if;
  if v_operation.status='confirmed' then
    return jsonb_build_object('ok',false,'reason','operation_confirmed');
  end if;
  if v_operation.status in ('cancelled','expired') then
    return jsonb_build_object('ok',true,'replayed',true,'status',v_operation.status,'operation_id',p_operation_id,'credential_id',p_credential_id);
  end if;

  update public.device_auth_credentials
     set revoked_at=coalesce(revoked_at,v_now),
         revoked_reason=case when revoked_at is null then 'enrollment_operation_cancelled' else revoked_reason end
   where credential_id=p_credential_id;
  update public.device_auth_enrollment_operations
     set status='cancelled',cancelled_at=v_now,
         result_ciphertext=null,result_iv=null,result_auth_tag=null,updated_at=v_now
   where operation_id=p_operation_id;
  insert into public.device_auth_events(device_id,credential_id,event_type,success,reason,metadata_json)
  values (p_device_id,p_credential_id,'custodial_enrollment_operation_cancelled',true,'client_cancelled',jsonb_build_object('operation_id',p_operation_id));
  return jsonb_build_object('ok',true,'replayed',false,'status','cancelled','operation_id',p_operation_id,'credential_id',p_credential_id);
end
$function$

CREATE OR REPLACE FUNCTION public.device_auth_confirm_enrollment_operation(p_operation_id uuid, p_device_id uuid, p_credential_id uuid, p_token_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_now timestamptz:=clock_timestamp();
  v_operation public.device_auth_enrollment_operations%rowtype;
  v_credential public.device_auth_credentials%rowtype;
begin
  if p_operation_id is null or p_device_id is null or p_credential_id is null
     or p_token_hash is null or length(p_token_hash)<>64 then
    raise exception using errcode='22023',message='operation and credential proof are required';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('custodial-enrollment-operation:'||p_operation_id::text,0));
  select * into v_operation from public.device_auth_enrollment_operations
   where operation_id=p_operation_id for update;
  if v_operation.operation_id is null
     or v_operation.device_id<>p_device_id
     or v_operation.credential_id<>p_credential_id then
    return jsonb_build_object('ok',false,'reason','operation_not_found');
  end if;
  select * into v_credential from public.device_auth_credentials
   where credential_id=p_credential_id and device_id=p_device_id and token_hash=p_token_hash;
  if v_credential.credential_id is null then
    return jsonb_build_object('ok',false,'reason','credential_mismatch');
  end if;
  if v_operation.status='confirmed' then
    return jsonb_build_object(
      'ok',true,'replayed',true,'status','confirmed','operation_id',p_operation_id,
      'credential_id',p_credential_id,
      'credential_active',(v_credential.revoked_at is null and v_credential.expires_at>v_now)
    );
  end if;
  if v_operation.status<>'committed' then
    return jsonb_build_object('ok',false,'reason','operation_'||v_operation.status);
  end if;
  if v_operation.resume_expires_at<=v_now then
    update public.device_auth_credentials
       set revoked_at=coalesce(revoked_at,v_now),
           revoked_reason=case when revoked_at is null then 'enrollment_operation_unconfirmed_timeout' else revoked_reason end
     where credential_id=p_credential_id;
    update public.device_auth_enrollment_operations
       set status='expired',expired_at=coalesce(expired_at,v_now),
           result_ciphertext=null,result_iv=null,result_auth_tag=null,updated_at=v_now
     where operation_id=p_operation_id;
    return jsonb_build_object('ok',false,'reason','operation_expired');
  end if;
  if v_credential.revoked_at is not null or v_credential.expires_at<=v_now then
    update public.device_auth_enrollment_operations
       set status='cancelled',cancelled_at=coalesce(cancelled_at,v_now),
           result_ciphertext=null,result_iv=null,result_auth_tag=null,updated_at=v_now
     where operation_id=p_operation_id;
    return jsonb_build_object('ok',false,'reason','credential_unavailable');
  end if;

  update public.device_auth_credentials
     set confirmed_at=coalesce(confirmed_at,v_now),last_used_at=coalesce(last_used_at,v_now)
   where credential_id=p_credential_id;
  update public.device_auth_enrollment_operations
     set status='confirmed',confirmed_at=v_now,
         result_ciphertext=null,result_iv=null,result_auth_tag=null,updated_at=v_now
   where operation_id=p_operation_id;
  insert into public.device_auth_events(device_id,credential_id,event_type,success,metadata_json)
  values (p_device_id,p_credential_id,'custodial_enrollment_operation_confirmed',true,jsonb_build_object('operation_id',p_operation_id));
  return jsonb_build_object(
    'ok',true,'replayed',false,'status','confirmed','operation_id',p_operation_id,
    'credential_id',p_credential_id,'credential_active',true
  );
end
$function$

CREATE OR REPLACE FUNCTION public.device_auth_consume_enrollment_code(p_device_id uuid, p_code_hash text, p_credential_id uuid, p_token_hash text, p_device_label text, p_expires_at timestamp with time zone, p_user_agent_hash text DEFAULT NULL::text, p_ip_hash text DEFAULT NULL::text, p_metadata_json jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_code public.device_auth_enrollment_codes%rowtype;
  v_now timestamptz := now();
  v_credential public.device_auth_credentials%rowtype;
begin
  if p_device_id is null then raise exception 'device_id is required'; end if;
  if p_code_hash is null or length(p_code_hash) <> 64 then raise exception 'valid code_hash is required'; end if;
  if p_credential_id is null then raise exception 'credential_id is required'; end if;
  if p_token_hash is null or length(p_token_hash) <> 64 then raise exception 'valid token_hash is required'; end if;
  if p_expires_at is null or p_expires_at <= v_now then raise exception 'future expires_at is required'; end if;

  select *
    into v_code
  from public.device_auth_enrollment_codes c
  where c.device_id = p_device_id
    and c.consumed_at is null
    and c.revoked_at is null
    and c.status = 'active'
  for update;

  if not found then
    return jsonb_build_object('ok', false, 'reason', 'missing');
  end if;
  if v_code.expires_at <= v_now then
    update public.device_auth_enrollment_codes c
    set status = 'expired'
    where c.enrollment_id = v_code.enrollment_id;
    return jsonb_build_object('ok', false, 'reason', 'expired', 'enrollment_id', v_code.enrollment_id);
  end if;
  if v_code.code_hash <> p_code_hash then
    update public.device_auth_enrollment_codes c
    set failed_attempts = least(10, c.failed_attempts + 1),
        last_failed_at = v_now
    where c.enrollment_id = v_code.enrollment_id;
    return jsonb_build_object('ok', false, 'reason', 'invalid', 'enrollment_id', v_code.enrollment_id);
  end if;

  update public.device_auth_credentials dc
  set revoked_at = v_now,
      revoked_reason = 'replaced_by_new_enrollment'
  where dc.device_id = p_device_id
    and dc.revoked_at is null;

  insert into public.device_auth_credentials(
    credential_id, device_id, token_hash, device_label, user_agent_hash,
    created_ip_hash, expires_at, metadata_json
  ) values (
    p_credential_id, p_device_id, p_token_hash, nullif(left(coalesce(p_device_label,''),160),''),
    p_user_agent_hash, p_ip_hash, p_expires_at, coalesce(p_metadata_json,'{}'::jsonb)
  )
  returning * into v_credential;

  update public.device_auth_enrollment_codes c
  set consumed_at = v_now,
      consumed_by_credential_id = p_credential_id,
      use_count = 1,
      status = 'used'
  where c.enrollment_id = v_code.enrollment_id;

  return jsonb_build_object(
    'ok', true,
    'enrollment_id', v_code.enrollment_id,
    'credential_id', v_credential.credential_id,
    'expires_at', v_credential.expires_at
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.device_auth_consume_enrollment_operation(p_operation_id uuid, p_flow text, p_device_id uuid, p_code_hash text, p_request_fingerprint text, p_credential_id uuid, p_token_hash text, p_device_label text, p_expires_at timestamp with time zone, p_result_ciphertext text, p_result_iv text, p_result_auth_tag text, p_result_expires_at timestamp with time zone, p_encryption_version text, p_user_agent_hash text DEFAULT NULL::text, p_ip_hash text DEFAULT NULL::text, p_metadata_json jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_now timestamptz:=clock_timestamp();
  v_operation public.device_auth_enrollment_operations%rowtype;
  v_code public.device_auth_enrollment_codes%rowtype;
  v_credential public.device_auth_credentials%rowtype;
  v_failed_attempts integer;
begin
  if p_operation_id is null or p_device_id is null or p_credential_id is null then
    raise exception using errcode='22023',message='operation_id, device_id, and credential_id are required';
  end if;
  if p_flow not in ('enrollment','recovery') then
    raise exception using errcode='22023',message='flow must be enrollment or recovery';
  end if;
  if p_code_hash is null or length(p_code_hash)<>64
     or p_request_fingerprint is null or length(p_request_fingerprint)<>64
     or p_token_hash is null or length(p_token_hash)<>64 then
    raise exception using errcode='22023',message='valid enrollment hashes are required';
  end if;
  if p_expires_at is null or p_expires_at<=v_now then
    raise exception using errcode='22023',message='future credential expiry is required';
  end if;
  if p_result_expires_at is null
     or p_result_expires_at<=v_now
     or p_result_expires_at>v_now+interval '1 hour' then
    raise exception using errcode='22023',message='resumable result expiry must be within one hour';
  end if;
  if nullif(btrim(coalesce(p_encryption_version,'')),'') is null
     or length(coalesce(p_result_ciphertext,''))<32
     or length(coalesce(p_result_ciphertext,''))>16384
     or length(coalesce(p_result_iv,'')) not between 12 and 128
     or length(coalesce(p_result_auth_tag,'')) not between 16 and 128 then
    raise exception using errcode='22023',message='valid encrypted enrollment result is required';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('custodial-enrollment-operation:'||p_operation_id::text,0));

  select * into v_operation
  from public.device_auth_enrollment_operations
  where operation_id=p_operation_id
  for update;

  if v_operation.operation_id is not null then
    if v_operation.device_id<>p_device_id
       or v_operation.flow<>p_flow
       or v_operation.request_fingerprint<>p_request_fingerprint then
      return jsonb_build_object('ok',false,'reason','operation_conflict');
    end if;

    if v_operation.status='committed' and v_operation.resume_expires_at<=v_now then
      update public.device_auth_credentials
         set revoked_at=coalesce(revoked_at,v_now),
             revoked_reason=case when revoked_at is null then 'enrollment_operation_unconfirmed_timeout' else revoked_reason end
       where credential_id=v_operation.credential_id;
      update public.device_auth_enrollment_operations
         set status='expired',expired_at=coalesce(expired_at,v_now),
             result_ciphertext=null,result_iv=null,result_auth_tag=null,updated_at=v_now
       where operation_id=v_operation.operation_id
       returning * into v_operation;
      return jsonb_build_object('ok',false,'reason','operation_expired','operation_id',v_operation.operation_id);
    end if;

    if v_operation.status='committed' then
      select * into v_credential
      from public.device_auth_credentials
      where credential_id=v_operation.credential_id
        and device_id=v_operation.device_id
        and revoked_at is null
        and expires_at>v_now;
      if v_credential.credential_id is null then
        update public.device_auth_enrollment_operations
           set status='cancelled',cancelled_at=coalesce(cancelled_at,v_now),
               result_ciphertext=null,result_iv=null,result_auth_tag=null,updated_at=v_now
         where operation_id=v_operation.operation_id;
        return jsonb_build_object('ok',false,'reason','credential_unavailable','operation_id',v_operation.operation_id);
      end if;
      return jsonb_build_object(
        'ok',true,'replayed',true,'status',v_operation.status,
        'operation_id',v_operation.operation_id,'flow',v_operation.flow,
        'credential_id',v_operation.credential_id,
        'credential_expires_at',v_credential.expires_at,
        'resume_expires_at',v_operation.resume_expires_at,
        'encryption_version',v_operation.encryption_version,
        'result_ciphertext',v_operation.result_ciphertext,
        'result_iv',v_operation.result_iv,
        'result_auth_tag',v_operation.result_auth_tag
      );
    end if;

    return jsonb_build_object(
      'ok',false,'reason','operation_'||v_operation.status,
      'operation_id',v_operation.operation_id,'credential_id',v_operation.credential_id
    );
  end if;

  perform 1 from public.devices where id=p_device_id for update;
  if not found then
    raise exception using errcode='P0002',message='device was not found';
  end if;

  select * into v_code
  from public.device_auth_enrollment_codes
  where device_id=p_device_id and consumed_at is null and revoked_at is null
  order by created_at desc
  limit 1
  for update;

  if v_code.enrollment_id is null or v_code.expires_at<=v_now then
    if v_code.enrollment_id is not null then
      update public.device_auth_enrollment_codes
         set revoked_at=coalesce(revoked_at,v_now),
             metadata_json=metadata_json||jsonb_build_object('revoked_reason','expired')
       where enrollment_id=v_code.enrollment_id;
    end if;
    return jsonb_build_object('ok',false,'reason','invalid_or_expired');
  end if;

  if v_code.failed_attempts>=10 then
    update public.device_auth_enrollment_codes
       set revoked_at=coalesce(revoked_at,v_now),
           metadata_json=metadata_json||jsonb_build_object('revoked_reason','attempt_limit')
     where enrollment_id=v_code.enrollment_id;
    return jsonb_build_object('ok',false,'reason','invalid_or_expired');
  end if;

  if v_code.code_hash<>p_code_hash then
    v_failed_attempts:=least(v_code.failed_attempts+1,10);
    update public.device_auth_enrollment_codes
       set failed_attempts=v_failed_attempts,last_failed_at=v_now,
           revoked_at=case when v_failed_attempts>=10 then v_now else revoked_at end,
           metadata_json=case when v_failed_attempts>=10
             then metadata_json||jsonb_build_object('revoked_reason','attempt_limit')
             else metadata_json end
     where enrollment_id=v_code.enrollment_id;
    insert into public.device_auth_events(
      device_id,credential_id,event_type,success,reason,ip_hash,user_agent_hash,metadata_json
    ) values (
      p_device_id,null,'custodial_enrollment_operation_failed',false,'invalid_code',
      p_ip_hash,p_user_agent_hash,
      jsonb_build_object('operation_id',p_operation_id,'flow',p_flow,'enrollment_id',v_code.enrollment_id,'failed_attempts',v_failed_attempts)
    );
    return jsonb_build_object('ok',false,'reason','invalid_or_expired');
  end if;

  update public.device_auth_credentials
     set revoked_at=v_now,revoked_reason='re_enrolled'
   where device_id=p_device_id and revoked_at is null;

  insert into public.device_auth_credentials(
    credential_id,device_id,token_hash,device_label,
    user_agent_hash,created_ip_hash,last_user_agent_hash,last_ip_hash,
    metadata_json,confirmed_at,last_used_at,expires_at
  ) values (
    p_credential_id,p_device_id,p_token_hash,
    nullif(left(btrim(coalesce(p_device_label,'')),160),''),
    p_user_agent_hash,p_ip_hash,p_user_agent_hash,p_ip_hash,
    coalesce(p_metadata_json,'{}'::jsonb)||jsonb_build_object('enrollment_operation_id',p_operation_id,'enrollment_flow',p_flow),
    null,null,p_expires_at
  ) returning * into v_credential;

  update public.device_auth_enrollment_codes
     set consumed_at=v_now,consumed_by_credential_id=v_credential.credential_id
   where enrollment_id=v_code.enrollment_id;

  insert into public.device_auth_enrollment_operations(
    operation_id,device_id,credential_id,enrollment_id,flow,request_fingerprint,status,
    encryption_version,result_ciphertext,result_iv,result_auth_tag,resume_expires_at,metadata_json
  ) values (
    p_operation_id,p_device_id,v_credential.credential_id,v_code.enrollment_id,p_flow,p_request_fingerprint,'committed',
    left(p_encryption_version,80),p_result_ciphertext,p_result_iv,p_result_auth_tag,p_result_expires_at,
    coalesce(p_metadata_json,'{}'::jsonb)
  ) returning * into v_operation;

  insert into public.device_auth_events(
    device_id,credential_id,event_type,success,reason,ip_hash,user_agent_hash,metadata_json
  ) values (
    p_device_id,v_credential.credential_id,'custodial_enrollment_operation_committed',true,null,
    p_ip_hash,p_user_agent_hash,
    coalesce(p_metadata_json,'{}'::jsonb)||jsonb_build_object(
      'operation_id',p_operation_id,'flow',p_flow,'enrollment_id',v_code.enrollment_id,
      'resume_expires_at',p_result_expires_at
    )
  );

  return jsonb_build_object(
    'ok',true,'replayed',false,'status','committed',
    'operation_id',v_operation.operation_id,'flow',v_operation.flow,
    'credential_id',v_credential.credential_id,
    'credential_expires_at',v_credential.expires_at,
    'resume_expires_at',v_operation.resume_expires_at,
    'encryption_version',v_operation.encryption_version,
    'result_ciphertext',v_operation.result_ciphertext,
    'result_iv',v_operation.result_iv,
    'result_auth_tag',v_operation.result_auth_tag
  );
end
$function$

CREATE OR REPLACE FUNCTION public.device_auth_issue_enrollment_code(p_device_id uuid, p_code_hash text, p_created_by text, p_expires_at timestamp with time zone, p_metadata_json jsonb DEFAULT '{}'::jsonb)
 RETURNS TABLE(enrollment_id uuid, device_id uuid, expires_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_row public.device_auth_enrollment_codes%rowtype;
begin
  if p_device_id is null then raise exception 'device_id is required'; end if;
  if p_code_hash is null or length(p_code_hash) <> 64 then raise exception 'valid code_hash is required'; end if;
  if p_expires_at is null or p_expires_at <= now() then raise exception 'future expires_at is required'; end if;
  if coalesce(p_metadata_json, '{}'::jsonb) is null or jsonb_typeof(coalesce(p_metadata_json, '{}'::jsonb)) <> 'object' then
    raise exception 'metadata_json must be an object';
  end if;
  if not exists(select 1 from public.devices d where d.id = p_device_id and d.active = true) then
    raise exception 'active device not found';
  end if;

  update public.device_auth_enrollment_codes c
  set revoked_at = now(),
      status = 'revoked',
      metadata_json = c.metadata_json || jsonb_build_object('revoked_reason','replaced')
  where c.device_id = p_device_id
    and c.consumed_at is null
    and c.revoked_at is null;

  insert into public.device_auth_enrollment_codes(
    device_id, code_hash, created_by, expires_at, metadata_json,
    purpose, max_uses, use_count, status
  ) values (
    p_device_id, p_code_hash,
    coalesce(nullif(left(btrim(coalesce(p_created_by,'')),160),''),'ops_manager'),
    p_expires_at, coalesce(p_metadata_json,'{}'::jsonb),
    coalesce(nullif(left(coalesce(p_metadata_json->>'purpose',''),80),''),'employee_device_enrollment'),
    1, 0, 'active'
  )
  returning * into v_row;

  return query select v_row.enrollment_id, v_row.device_id, v_row.expires_at;
end;
$function$

CREATE OR REPLACE FUNCTION public.device_auth_remove_custodial_credential(p_operation_id uuid, p_device_id uuid, p_credential_id uuid, p_token_hash text, p_now timestamp with time zone DEFAULT now())
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_operation public.device_auth_removal_operations%rowtype;
  v_credential public.device_auth_credentials%rowtype;
  v_device_identifier text;
  v_push_registrations integer := 0;
  v_event_instances integer := 0;
  v_notification_jobs integer := 0;
  v_claimed_jobs integer := 0;
  v_result jsonb;
begin
  if p_operation_id is null or p_device_id is null or p_credential_id is null
     or p_token_hash is null or length(p_token_hash) <> 64 or p_now is null then
    raise exception using
      errcode = '22023',
      message = 'operation, device, and credential proof are required';
  end if;

  -- A stable operation lock makes concurrent response-loss retries deterministic
  -- even before the terminal operation row exists.
  perform pg_advisory_xact_lock(
    hashtextextended('custodial-device-removal:' || p_operation_id::text, 0)
  );

  select * into v_operation
  from public.device_auth_removal_operations
  where operation_id = p_operation_id
  for update;

  if v_operation.operation_id is not null then
    -- Revocation is intentionally ignored only for this exact terminal replay.
    -- The caller must still prove the original credential ID and one-way hash.
    select * into v_credential
    from public.device_auth_credentials
    where credential_id = p_credential_id
      and device_id = p_device_id
      and token_hash = p_token_hash
    for update;

    if v_credential.credential_id is null
       or v_operation.credential_id <> p_credential_id
       or v_operation.device_id <> p_device_id then
      return jsonb_build_object('ok', false, 'reason', 'operation_conflict');
    end if;

    return v_operation.result_json || jsonb_build_object(
      'ok', true,
      'replayed', true
    );
  end if;

  select * into v_credential
  from public.device_auth_credentials
  where credential_id = p_credential_id
  for update;

  if v_credential.credential_id is null
     or v_credential.device_id <> p_device_id
     or v_credential.token_hash <> p_token_hash then
    return jsonb_build_object('ok', false, 'reason', 'credential_mismatch');
  end if;
  if v_credential.revoked_at is not null then
    return jsonb_build_object('ok', false, 'reason', 'credential_revoked');
  end if;
  if v_credential.expires_at <= p_now then
    return jsonb_build_object('ok', false, 'reason', 'credential_expired');
  end if;
  if v_credential.confirmed_at is null then
    return jsonb_build_object('ok', false, 'reason', 'credential_unconfirmed');
  end if;

  select device_id into v_device_identifier
  from public.devices
  where id = p_device_id;
  if v_device_identifier is null
     or v_device_identifier !~ '^KIOSK_(0[2-9]|10)$' then
    return jsonb_build_object('ok', false, 'reason', 'device_not_eligible');
  end if;

  with changed as (
    update public.employee_push_registrations
       set active = false,
           revoked_at = coalesce(revoked_at, p_now),
           revoked_reason = 'custodial_device_removed',
           last_error = 'custodial_device_removed',
           updated_at = p_now
     where credential_id = p_credential_id
       and (active = true or revoked_at is null)
    returning registration_id
  )
  select count(*)::integer into v_push_registrations from changed;

  with changed as (
    update public.event_push_instances
       set state = 'cancelled',
           cancelled_at = coalesce(cancelled_at, p_now),
           last_error = 'custodial_device_removed',
           updated_at = p_now
     where credential_id = p_credential_id
       and state in ('pending', 'leased')
    returning instance_id
  )
  select count(*)::integer into v_event_instances from changed;

  -- Active lease proof is retained on a terminally cancelled claimed job. This
  -- lets the owning worker call finish_operational_notification_job_terminal,
  -- while every claim path rejects the now-dead row after a restart.
  with candidates as (
    select job_id, status as previous_status
    from public.operational_notification_jobs
    where job_type in ('employee_event_push', 'employee_native_push')
      and status in ('pending', 'leased')
      and payload_json->>'credential_id' = p_credential_id::text
    for update
  ), changed as (
    update public.operational_notification_jobs job
       set status = 'dead',
           completed_at = coalesce(job.completed_at, p_now),
           last_error = 'custodial_device_removed',
           updated_at = p_now
      from candidates
     where job.job_id = candidates.job_id
    returning candidates.previous_status
  )
  select count(*)::integer,
         (count(*) filter (where previous_status = 'leased'))::integer
    into v_notification_jobs, v_claimed_jobs
  from changed;

  update public.device_auth_credentials
     set revoked_at = p_now,
         revoked_reason = 'custodial_device_removed'
   where credential_id = p_credential_id;

  v_result := jsonb_build_object(
    'ok', true,
    'removed', true,
    'replayed', false,
    'status', 'removed',
    'operation_id', p_operation_id,
    'credential_id', p_credential_id,
    'device_id', v_device_identifier,
    'removed_at', p_now,
    'push_registrations_deactivated', v_push_registrations,
    'event_push_instances_cancelled', v_event_instances,
    'notification_jobs_cancelled', v_notification_jobs,
    'claimed_notification_jobs_cancelled', v_claimed_jobs
  );

  insert into public.device_auth_removal_operations(
    operation_id, device_id, credential_id, status, result_json, removed_at
  ) values (
    p_operation_id, p_device_id, p_credential_id, 'removed', v_result, p_now
  );

  insert into public.device_auth_events(
    device_id, credential_id, event_type, success, reason, presented_identifier, metadata_json
  ) values (
    p_device_id,
    p_credential_id,
    'custodial_device_removed',
    true,
    'client_requested_removal',
    null,
    jsonb_build_object(
      'operation_id', p_operation_id,
      'push_registrations_deactivated', v_push_registrations,
      'event_push_instances_cancelled', v_event_instances,
      'notification_jobs_cancelled', v_notification_jobs,
      'claimed_notification_jobs_cancelled', v_claimed_jobs
    )
  );

  return v_result;
end
$function$

CREATE OR REPLACE FUNCTION public.device_heartbeat(p_device_id text, p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
declare
  v_device_pk uuid;
  v_device_name text;
  v_now timestamptz := now();
begin
  select d.id, d.device_name
    into v_device_pk, v_device_name
  from public.devices d
  where d.device_id = p_device_id
  limit 1;

  if v_device_pk is null then
    raise exception 'Device not found: %', p_device_id;
  end if;

  update public.devices
  set
    last_seen_at = v_now,
    notes = coalesce(p_notes, notes),
    updated_at = now()
  where id = v_device_pk;

  insert into public.system_logs (
    level,
    source,
    message,
    device_id
  )
  values (
    'INFO',
    'device_heartbeat',
    'Device heartbeat received',
    v_device_pk
  );

  return jsonb_build_object(
    'device_id', p_device_id,
    'device_name', v_device_name,
    'last_seen_at', v_now,
    'ok', true
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.enforce_session_status_transition()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
                                                                                                                                                                        begin
                                                                                                                                                                          if tg_op = 'UPDATE' and old.status is distinct from new.status then
                                                                                                                                                                              if old.status = 'active' and new.status not in ('pending_submit', 'cancelled') then
                                                                                                                                                                                    raise exception 'Invalid session transition: active -> %', new.status;
                                                                                                                                                                                        end if;

                                                                                                                                                                                            if old.status = 'pending_submit' and new.status not in ('closed', 'cancelled') then
                                                                                                                                                                                                  raise exception 'Invalid session transition: pending_submit -> %', new.status;
                                                                                                                                                                                                      end if;

                                                                                                                                                                                                          if old.status = 'closed' and new.status <> 'closed' then
                                                                                                                                                                                                                raise exception 'Closed sessions cannot transition to %', new.status;
                                                                                                                                                                                                                    end if;

                                                                                                                                                                                                                        if old.status = 'cancelled' and new.status <> 'cancelled' then
                                                                                                                                                                                                                              raise exception 'Cancelled sessions cannot transition to %', new.status;
                                                                                                                                                                                                                                  end if;
                                                                                                                                                                                                                                    end if;

                                                                                                                                                                                                                                      return new;
                                                                                                                                                                                                                                      end;
                                                                                                                                                                                                                                      $function$

CREATE OR REPLACE FUNCTION public.evaluate_location_proximity(p_location_code text, p_device_identifier text, p_latitude numeric, p_longitude numeric, p_accuracy_m numeric DEFAULT NULL::numeric, p_session_uuid text DEFAULT NULL::text, p_client_event_id text DEFAULT NULL::text, p_correlation_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_session_key text:=nullif(btrim(coalesce(p_session_uuid,'')),'');
