CREATE OR REPLACE FUNCTION public.events_app_validate_scope_venue()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_scope text;
  v_zoo_venue public.event_venues%rowtype;
  v_primary public.event_venues%rowtype;
  v_bad_count integer;
begin
  v_scope := upper(replace(btrim(coalesce(new.event_scope, 'UNKNOWN')), '-', '_'));
  if v_scope in ('ZOO', 'ZOO_FOOTPRINT') then
    v_scope := 'ZOO_WIDE';
  elsif v_scope in ('SINGLE') then
    v_scope := 'SINGLE_VENUE';
  elsif v_scope in ('MULTI', 'MULTIPLE', 'MULTIPLE_VENUES') then
    v_scope := 'MULTI_VENUE';
  elsif v_scope = 'OFF_SITE' then
    v_scope := 'OFFSITE';
  end if;

  if v_scope not in ('ZOO_WIDE', 'SINGLE_VENUE', 'MULTI_VENUE', 'OFFSITE', 'UNKNOWN') then
    raise exception 'Invalid event scope %', new.event_scope using errcode = '23514';
  end if;

  new.event_scope := v_scope;
  new.event_timezone := coalesce(nullif(btrim(new.event_timezone), ''), 'America/Chicago');
  if new.event_timezone <> 'America/Chicago' then
    raise exception 'event_timezone must be America/Chicago' using errcode = '23514';
  end if;
  new.venue_ids := coalesce(new.venue_ids, '{}'::uuid[]);
  new.coverage_location_ids := coalesce(new.coverage_location_ids, '{}'::uuid[]);
  new.staffing_area_ids := coalesce(new.staffing_area_ids, '{}'::uuid[]);
  new.display_location := nullif(btrim(coalesce(new.display_location, '')), '');

  if new.parser_confidence is not null and new.parser_confidence not in ('high', 'medium', 'low') then
    raise exception 'parser_confidence must be high, medium, or low' using errcode = '23514';
  end if;

  if v_scope = 'ZOO_WIDE' then
    select * into v_zoo_venue
    from public.event_venues
    where venue_code = 'ZOO_FOOTPRINT' and active = true
    limit 1;
    if v_zoo_venue.id is null then
      raise exception 'Zoo Footprint venue is not configured' using errcode = '23514';
    end if;
    new.primary_venue_id := v_zoo_venue.id;
    new.venue_ids := array[v_zoo_venue.id]::uuid[];
    new.location_group_id := v_zoo_venue.location_group_id;
    new.display_location := 'Zoo Footprint';
    new.needs_review := false;
  elsif v_scope = 'SINGLE_VENUE' then
    if new.primary_venue_id is null then
      raise exception 'SINGLE_VENUE events require one eligible event venue' using errcode = '23514';
    end if;
    select * into v_primary
    from public.event_venues
    where id = new.primary_venue_id and active = true
    limit 1;
    if v_primary.id is null or v_primary.eligible_event_venue is not true or v_primary.event_scope = 'ZOO_WIDE' then
      raise exception 'Selected event venue is not eligible as a primary event venue' using errcode = '23514';
    end if;
    if not (new.primary_venue_id = any(new.venue_ids)) then
      new.venue_ids := array_prepend(new.primary_venue_id, new.venue_ids);
    end if;
    new.location_group_id := coalesce(v_primary.location_group_id, new.location_group_id);
    new.display_location := coalesce(new.display_location, v_primary.display_name);
    new.needs_review := false;
  elsif v_scope = 'MULTI_VENUE' then
    if coalesce(array_length(new.venue_ids, 1), 0) < 2 then
      raise exception 'MULTI_VENUE events require at least two eligible event venues' using errcode = '23514';
    end if;
    select count(*) into v_bad_count
    from unnest(new.venue_ids) as selected(venue_id)
    left join public.event_venues ev on ev.id = selected.venue_id and ev.active = true
    where ev.id is null or ev.eligible_event_venue is not true or ev.event_scope = 'ZOO_WIDE';
    if v_bad_count > 0 then
      raise exception 'MULTI_VENUE events contain an ineligible venue' using errcode = '23514';
    end if;
    if new.primary_venue_id is null or not (new.primary_venue_id = any(new.venue_ids)) then
      new.primary_venue_id := new.venue_ids[1];
    end if;
    select * into v_primary from public.event_venues where id = new.primary_venue_id limit 1;
    new.location_group_id := coalesce(v_primary.location_group_id, new.location_group_id);
    new.display_location := coalesce(
      new.display_location,
      (
        select string_agg(ev.display_name, ', ' order by ev.display_name)
        from public.event_venues ev
        where ev.id = any(new.venue_ids)
      )
    );
    new.needs_review := false;
  elsif v_scope = 'OFFSITE' then
    new.display_location := coalesce(new.display_location, 'Offsite');
    new.needs_review := false;
  else
    new.needs_review := true;
    new.display_location := coalesce(new.display_location, 'Needs Review');
  end if;

  select count(*) into v_bad_count
  from unnest(new.coverage_location_ids) as selected(location_group_id)
  left join public.location_groups lg on lg.id = selected.location_group_id
  where lg.id is null or lg.eligible_custodial_coverage is not true;
  if v_bad_count > 0 then
    raise exception 'coverage_location_ids contains an ineligible custodial coverage location' using errcode = '23514';
  end if;

  select count(*) into v_bad_count
  from unnest(new.staffing_area_ids) as selected(location_group_id)
  left join public.location_groups lg on lg.id = selected.location_group_id
  where lg.id is null or lg.eligible_staffing_assignment is not true;
  if v_bad_count > 0 then
    raise exception 'staffing_area_ids contains an ineligible staffing location' using errcode = '23514';
  end if;

  if new.event_scope <> 'UNKNOWN' and exists (
    select 1
    from public.location_groups lg
    where lg.id = new.location_group_id
      and lg.eligible_event_venue is not true
      and lg.eligible_event_scope is not true
      and (lg.public_restroom is true or lg.staff_restroom is true or lg.group_name ilike '%restroom%' or lg.group_code ilike '%RESTROOM%')
  ) then
    raise exception 'Restroom/custodial coverage locations cannot be saved as primary event venues' using errcode = '23514';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.expire_stale_open_sessions(p_now timestamp with time zone DEFAULT now())
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_timeout_minutes integer := public.get_setting_int('stale_session_timeout_minutes',120);
  v_expired_count integer := 0;
  r record;
begin
  for r in
    select s.id,s.status,s.location_id,s.device_id,s.started_at,s.ended_at
    from public.sessions s
    where (s.status='active' and s.started_at<=p_now-make_interval(mins=>v_timeout_minutes))
       or (s.status='pending_submit' and coalesce(s.ended_at,s.started_at)<=p_now-make_interval(mins=>v_timeout_minutes))
    order by s.started_at for update skip locked
  loop
    update public.sessions
       set status='cancelled',ended_at=coalesce(ended_at,p_now),
           duration_minutes=coalesce(duration_minutes,greatest(0,round(extract(epoch from (coalesce(ended_at,p_now)-started_at))/60.0))),
           duration_display=coalesce(duration_display,greatest(0,round(extract(epoch from (coalesce(ended_at,p_now)-started_at))/60.0))::text||' min'),
           completion_source=coalesce(completion_source,'system'),updated_at=p_now
     where id=r.id and status=r.status;
    if found then
      insert into public.session_events(session_id,event_type,actor_type,actor_ref,details_json)
      values(r.id,'session_auto_cancelled','system','expire_stale_open_sessions',jsonb_build_object('reason','stale_timeout','previous_status',r.status,'timeout_minutes',v_timeout_minutes,'cancelled_at',p_now));
      insert into public.system_logs(level,source,message,session_id,location_id,device_id)
      values('WARN','expire_stale_open_sessions','Stale session cancelled without fabricating completion',r.id,r.location_id,r.device_id);
      v_expired_count:=v_expired_count+1;
    end if;
  end loop;
  return v_expired_count;
end;
$function$

CREATE OR REPLACE FUNCTION public.force_close_session(p_session_uuid text, p_closed_by text, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_session_id uuid;
  v_location_id uuid;
  v_device_pk uuid;
  v_started_at timestamptz;
  v_ended_at timestamptz := now();
  v_duration_minutes integer;
  v_duration_display text;
  v_status text;
begin
  select s.id, s.location_id, s.device_id, s.started_at, s.status
    into v_session_id, v_location_id, v_device_pk, v_started_at, v_status
  from public.sessions s
  where s.session_uuid = p_session_uuid
    and s.status in ('active', 'pending_submit')
  limit 1;

  if v_session_id is null then
    raise exception 'Open session not found for session_uuid: %', p_session_uuid;
  end if;

  v_duration_minutes := greatest(0, round(extract(epoch from (v_ended_at - v_started_at)) / 60.0));
  v_duration_display := v_duration_minutes::text || ' min';

  update public.sessions
  set
    status = 'closed',
    ended_at = coalesce(ended_at, v_ended_at),
    duration_minutes = coalesce(duration_minutes, v_duration_minutes),
    duration_display = coalesce(duration_display, v_duration_display),
    completion_source = coalesce(completion_source, 'admin_force_close'),
    updated_at = now()
  where id = v_session_id;

  insert into public.session_events (
    session_id,
    event_type,
    actor_type,
    actor_ref,
    details_json
  )
  values (
    v_session_id,
    'session_force_closed',
    'admin',
    coalesce(nullif(trim(p_closed_by), ''), 'unknown'),
    jsonb_build_object(
      'reason', p_reason,
      'previous_status', v_status,
      'forced_at', v_ended_at
    )
  );

  insert into public.system_logs (
    level,
    source,
    message,
    session_id,
    location_id,
    device_id
  )
  values (
    'WARN',
    'force_close_session',
    'Session force-closed by admin',
    v_session_id,
    v_location_id,
    v_device_pk
  );

  return jsonb_build_object(
    'session_uuid', p_session_uuid,
    'status', 'closed',
    'closed_at', v_ended_at,
    'closed_by', coalesce(nullif(trim(p_closed_by), ''), 'unknown'),
    'reason', p_reason
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.gemini_console_authorize_repair(p_proposal_id uuid, p_manager_id uuid, p_credential_id uuid, p_authorization_message_id uuid, p_operation_id uuid, p_release_id text, p_backend_commit text, p_frontend_commit text, p_schema_fingerprint text, p_correlation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_proposal public.gemini_console_repair_proposals%rowtype;
  v_authorization public.gemini_console_messages%rowtype;
  v_job public.gemini_console_repair_jobs%rowtype;
  v_kind text;
begin
  select * into v_proposal from public.gemini_console_repair_proposals
  where proposal_id = p_proposal_id for update;
  if not found then raise exception 'repair proposal not found'; end if;
  if v_proposal.status <> 'proposed' or v_proposal.expires_at <= now() then raise exception 'repair proposal is no longer authorizable'; end if;

  if not exists (
    select 1 from public.ops_manager_managers m
    where m.manager_id = p_manager_id and m.active and m.revoked_at is null
      and 'CUSTODIAL_MANAGER' = any(m.roles)
  ) then raise exception 'Custodial Manager authorization is required'; end if;
  if not exists (
    select 1 from public.ops_manager_trusted_devices d
    where d.credential_id = p_credential_id and d.manager_id = p_manager_id
      and d.revoked_at is null and d.expires_at > now()
  ) then raise exception 'active approving credential is required'; end if;

  select * into v_authorization from public.gemini_console_messages
  where message_id = p_authorization_message_id and manager_id = p_manager_id
    and conversation_id = v_proposal.conversation_id and role='user' for update;
  if not found or v_authorization.metadata_json->>'source' <> 'direct_authenticated_user' then
    raise exception 'direct authenticated authorization message is required';
  end if;
  if lower(btrim(v_authorization.body)) !~ '^(go ahead and repair that|implement the plan|fix it|proceed with the repair)[.! ]*$' then
    raise exception 'authorization message is not an explicit repair instruction';
  end if;

  v_kind := case when v_proposal.repair_kind='acceptance_probe' then 'acceptance_probe' else 'controlled_worker' end;
  insert into public.gemini_console_repair_jobs(
    proposal_id, conversation_id, approving_manager_id, approving_credential_id,
    authorization_message_id, operation_id, status, execution_mode,
    affected_components, starting_backend_commit, starting_frontend_commit,
    starting_schema_fingerprint, release_id, backup_reference, metadata_json
  ) values (
    v_proposal.proposal_id, v_proposal.conversation_id, p_manager_id, p_credential_id,
    p_authorization_message_id, p_operation_id,
    case when v_kind='acceptance_probe' then 'completed' else 'authorized' end,
    v_kind, v_proposal.affected_components,
    nullif(btrim(p_backend_commit),''), nullif(btrim(p_frontend_commit),''),
    nullif(btrim(p_schema_fingerprint),''), nullif(btrim(p_release_id),''),
    'required_before_worker_claim',
    jsonb_build_object('plan_sha256',v_proposal.plan_sha256,'authorization_source','direct_authenticated_user')
  )
  on conflict (proposal_id) do update set updated_at=now()
  returning * into v_job;

  if v_kind='acceptance_probe' then
    update public.gemini_console_repair_jobs
    set started_at=coalesce(started_at,now()), finished_at=coalesce(finished_at,now()),
        test_evidence=jsonb_build_array(jsonb_build_object('kind','database_transaction','result','pass')),
        verification_evidence=jsonb_build_array(jsonb_build_object('kind','durable_job_readback','result','pass')),
        rollback_evidence=jsonb_build_array(jsonb_build_object('kind','no_production_feature_changed','result','pass')),
        updated_at=now()
    where repair_job_id=v_job.repair_job_id
    returning * into v_job;
  end if;

  update public.gemini_console_repair_proposals
  set status='authorized', authorized_at=now()
  where proposal_id=v_proposal.proposal_id;
  insert into public.gemini_console_repair_job_events(
    repair_job_id,event_type,status,correlation_id,actor_manager_id,detail_json
  ) values (
    v_job.repair_job_id,'repair_authorized',v_job.status,p_correlation_id,p_manager_id,
    jsonb_build_object('execution_mode',v_kind,'plan_sha256',v_proposal.plan_sha256)
  );
  return to_jsonb(v_job);
end
$function$

CREATE OR REPLACE FUNCTION public.gemini_console_begin_turn(p_conversation_id uuid, p_manager_id uuid, p_client_message_id uuid, p_body text, p_attachment_ids uuid[], p_correlation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_conversation public.gemini_console_conversations%rowtype;
  v_message public.gemini_console_messages%rowtype;
  v_assistant public.gemini_console_messages%rowtype;
  v_inserted boolean := false;
  v_claimed boolean := false;
  v_expected integer := coalesce(cardinality(p_attachment_ids), 0);
  v_attached integer := 0;
begin
  if p_conversation_id is null or p_manager_id is null or p_client_message_id is null or p_correlation_id is null then
    raise exception 'conversation, manager, client message, and correlation identifiers are required';
  end if;
  if nullif(btrim(coalesce(p_body, '')), '') is null then raise exception 'message body is required'; end if;
  if char_length(p_body) > 30000 then raise exception 'message body exceeds 30000 characters'; end if;

  select * into v_conversation
  from public.gemini_console_conversations
  where conversation_id = p_conversation_id
  for update;
  if not found or v_conversation.status <> 'active' then raise exception 'active conversation not found'; end if;
  if v_conversation.owner_manager_id <> p_manager_id then raise exception 'conversation access denied'; end if;
  if not exists (
    select 1 from public.ops_manager_managers m
    where m.manager_id = p_manager_id and m.active and m.revoked_at is null
  ) then raise exception 'active manager not found'; end if;

  insert into public.gemini_console_messages(
    conversation_id, manager_id, role, body, state, client_message_id,
    correlation_id, metadata_json
  ) values (
    p_conversation_id, p_manager_id, 'user', p_body, 'queued',
    p_client_message_id, p_correlation_id,
    jsonb_build_object('source', 'direct_authenticated_user')
  )
  on conflict (manager_id, client_message_id) do nothing
  returning * into v_message;
  v_inserted := found;

  if not v_inserted then
    select * into v_message
    from public.gemini_console_messages
    where manager_id = p_manager_id and client_message_id = p_client_message_id
    for update;
    if v_message.conversation_id <> p_conversation_id or v_message.role <> 'user' or v_message.body <> p_body then
      raise exception 'client message identifier conflicts with another logical message';
    end if;
  end if;

  if v_expected > 0 then
    update public.gemini_console_attachments
    set message_id = v_message.message_id,
        status = 'attached',
        attached_at = coalesce(attached_at, now())
    where attachment_id = any(p_attachment_ids)
      and conversation_id = p_conversation_id
      and manager_id = p_manager_id
      and (status = 'pending' or message_id = v_message.message_id);
    get diagnostics v_attached = row_count;
    if v_attached <> v_expected then raise exception 'one or more attachments are unavailable'; end if;
  end if;

  select * into v_assistant
  from public.gemini_console_messages
  where response_to_message_id = v_message.message_id and role = 'assistant'
  limit 1;

  if v_assistant.message_id is null and v_message.state in ('queued','failed','cancelled') then
    update public.gemini_console_messages
    set state = 'generating', error_code = null, error_message = null,
        cancelled_at = null
    where message_id = v_message.message_id
      and state in ('queued','failed','cancelled')
    returning * into v_message;
    v_claimed := found;
  end if;

  update public.gemini_console_conversations
  set last_activity_at = now(), updated_at = now(),
      title = case when title = 'New chat' then left(regexp_replace(p_body, E'[\\n\\r\\t]+', ' ', 'g'), 80) else title end
  where conversation_id = p_conversation_id;

  return jsonb_build_object(
    'inserted', v_inserted,
    'claimed', v_claimed,
    'user_message', to_jsonb(v_message),
    'assistant_message', case when v_assistant.message_id is null then null else to_jsonb(v_assistant) end
  );
end
$function$

CREATE OR REPLACE FUNCTION public.gemini_console_finish_repair_job(p_repair_job_id uuid, p_lease_token uuid, p_status text, p_branch_name text DEFAULT NULL::text, p_changed_files jsonb DEFAULT '[]'::jsonb, p_test_evidence jsonb DEFAULT '[]'::jsonb, p_migration_evidence jsonb DEFAULT '[]'::jsonb, p_deployment_evidence jsonb DEFAULT '[]'::jsonb, p_verification_evidence jsonb DEFAULT '[]'::jsonb, p_rollback_evidence jsonb DEFAULT '[]'::jsonb, p_error_code text DEFAULT NULL::text, p_error_message text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_job public.gemini_console_repair_jobs%rowtype;
begin
  if p_status not in ('completed','failed','rolled_back','blocked','cancelled') then raise exception 'invalid terminal repair status'; end if;
  if p_status='completed' and (
    jsonb_typeof(coalesce(p_test_evidence,'[]'::jsonb)) <> 'array' or jsonb_array_length(coalesce(p_test_evidence,'[]'::jsonb))=0
    or jsonb_typeof(coalesce(p_verification_evidence,'[]'::jsonb)) <> 'array' or jsonb_array_length(coalesce(p_verification_evidence,'[]'::jsonb))=0
  ) then raise exception 'completed repair requires test and verification evidence'; end if;
  update public.gemini_console_repair_jobs
  set status=p_status, branch_name=nullif(btrim(coalesce(p_branch_name,'')),''),
      changed_files=coalesce(p_changed_files,'[]'::jsonb), test_evidence=coalesce(p_test_evidence,'[]'::jsonb),
      migration_evidence=coalesce(p_migration_evidence,'[]'::jsonb), deployment_evidence=coalesce(p_deployment_evidence,'[]'::jsonb),
      verification_evidence=coalesce(p_verification_evidence,'[]'::jsonb), rollback_evidence=coalesce(p_rollback_evidence,'[]'::jsonb),
      error_code=nullif(left(coalesce(p_error_code,''),80),''), error_message=nullif(left(coalesce(p_error_message,''),1000),''),
      finished_at=clock_timestamp(), updated_at=clock_timestamp(), lease_owner=null, lease_token=null, leased_until=null
  where repair_job_id=p_repair_job_id and lease_token=p_lease_token
    and backup_reference is not null and leased_until >= clock_timestamp()
  returning * into v_job;
  if not found then raise exception 'active repair lease with completed backup is required'; end if;
  insert into public.gemini_console_repair_job_events(repair_job_id,event_type,status,correlation_id,detail_json)
  values(v_job.repair_job_id,'repair_finished',v_job.status,gen_random_uuid(),jsonb_build_object('changed_files',v_job.changed_files));
  return to_jsonb(v_job);
end
$function$

