CREATE OR REPLACE FUNCTION public.msg_memphis_pre_generate_schedule()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
  v_body text := coalesce(new.body, '');
  v_lower text := lower(coalesce(new.body, ''));
  v_start_offset integer := 0;
  v_offsets integer[] := array[0];
  v_offset integer;
  v_service_date date;
begin
  if coalesce(new.metadata_json->>'channel', '') <> 'memphis' then
    return new;
  end if;

  if coalesce(new.message_type, '') <> 'text' then
    return new;
  end if;

  if v_lower !~ '(schedule|scheduled|shift|shifts|assigned|assignment|assignments|staff|staffing|working|works|work today|work tomorrow|who cleans|cleans|cleaning|cover|coverage|open area|open areas|open segment|uncovered|unassigned|restroom|restrooms|aquarium|teton|zambezi|expo|courtyard|breezeway|bonobos|cathouse|memmex|splash pad|event center|east admin|west admin|china|primate|pavilion)' then
    return new;
  end if;

  if v_lower ~ '\mtomorrow\M' then
    v_offsets := array[1];
  elsif v_lower ~ '\myesterday\M' then
    v_offsets := array[-1];
  elsif v_lower ~ '(this week|next week|weekly|week schedule|whole week|entire week|all week)' then
    if v_lower ~ 'next week' then
      v_start_offset := 7;
    else
      v_start_offset := 0;
    end if;
    v_offsets := array[
      v_start_offset,
      v_start_offset + 1,
      v_start_offset + 2,
      v_start_offset + 3,
      v_start_offset + 4,
      v_start_offset + 5,
      v_start_offset + 6
    ];
  end if;

  foreach v_offset in array v_offsets loop
    v_service_date := public.sch_service_date(now() + make_interval(days => v_offset));
    perform public.sch_generate_daily_schedule(v_service_date, false);
  end loop;

  return new;
exception when others then
  raise warning 'msg_memphis_pre_generate_schedule failed for message %, error: %', new.id, sqlerrm;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.msg_purge_deleted_content(p_now timestamp with time zone DEFAULT now(), p_batch_limit integer DEFAULT 1000)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_message_ids uuid[] := '{}'::uuid[];
  v_affected_thread_ids uuid[] := '{}'::uuid[];
  v_thread_ids uuid[] := '{}'::uuid[];
  v_deleted_messages integer := 0;
  v_deleted_threads integer := 0;
  v_deleted_receipts integer := 0;
  v_deleted_audit integer := 0;
begin
  if p_batch_limit is null or p_batch_limit < 1 or p_batch_limit > 10000 then
    raise exception using errcode='22023', message='Purge batch limit must be between 1 and 10000';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('messenger-deleted-content-retention-v1',0));

  select
    coalesce(array_agg(candidate.id),'{}'::uuid[]),
    coalesce(array_agg(distinct candidate.thread_id),'{}'::uuid[])
  into v_message_ids,v_affected_thread_ids
  from (
    select m.id,m.thread_id
    from public.msg_messages m
    where m.is_deleted is true
      and m.deleted_at is not null
      and m.purge_after <= p_now
    order by m.purge_after,m.id
    limit p_batch_limit
    for update skip locked
  ) candidate;

  if coalesce(array_length(v_message_ids,1),0) > 0 then
    update public.events_app_notification_log
    set response_message_id=null
    where response_message_id=any(v_message_ids);

    update public.scan_alert_notification_log
    set msg_message_id=null
    where msg_message_id=any(v_message_ids);

    update public.scan_alert_notification_log
    set escalation_msg_message_id=null
    where escalation_msg_message_id=any(v_message_ids);

    delete from public.msg_message_audit where message_id=any(v_message_ids);
    get diagnostics v_deleted_audit=row_count;

    delete from public.msg_message_deletions where message_id=any(v_message_ids);

    delete from public.msg_receipts where message_id=any(v_message_ids);
    get diagnostics v_deleted_receipts=row_count;

    delete from public.msg_messages where id=any(v_message_ids);
    get diagnostics v_deleted_messages=row_count;

    update public.msg_threads t
    set last_message_at=(
          select max(m.sent_at)
          from public.msg_messages m
          where m.thread_id=t.id and m.is_deleted is false
        ),
        updated_at=p_now
    where t.id=any(v_affected_thread_ids)
      and t.deleted_at is null;
  end if;

  select coalesce(array_agg(candidate.id),'{}'::uuid[])
  into v_thread_ids
  from (
    select t.id
    from public.msg_threads t
    where t.deleted_at is not null
      and t.purge_after <= p_now
      and not exists (select 1 from public.msg_messages m where m.thread_id=t.id)
    order by t.purge_after,t.id
    limit p_batch_limit
    for update skip locked
  ) candidate;

  if coalesce(array_length(v_thread_ids,1),0) > 0 then
    update public.events_app_notification_log set thread_id=null where thread_id=any(v_thread_ids);
    update public.scan_alert_notification_log set msg_thread_id=null where msg_thread_id=any(v_thread_ids);
    update public.scan_alert_notification_log set escalation_msg_thread_id=null where escalation_msg_thread_id=any(v_thread_ids);
    delete from public.msg_broadcasts where thread_id=any(v_thread_ids);
    delete from public.msg_memphis_thread_context where thread_id=any(v_thread_ids);
    delete from public.msg_thread_visibility where thread_id=any(v_thread_ids);
    delete from public.msg_hidden_threads_by_device where thread_id=any(v_thread_ids);
    delete from public.msg_thread_participants where thread_id=any(v_thread_ids);
    delete from public.msg_threads where id=any(v_thread_ids);
    get diagnostics v_deleted_threads=row_count;
  end if;

  return jsonb_build_object(
    'ok',true,
    'retention_days',14,
    'purged_at',p_now,
    'deleted_messages',v_deleted_messages,
    'deleted_threads',v_deleted_threads,
    'deleted_receipts',v_deleted_receipts,
    'deleted_message_audit_rows',v_deleted_audit
  );
end
$function$

CREATE OR REPLACE FUNCTION public.msg_reject_retired_ops_manager_shared_message_deletion_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
  if tg_op = 'INSERT'
     and exists (select 1 from public.msg_messages m join public.msg_threads t on t.id = m.thread_id where m.id = new.message_id and t.system_key = 'ops_manager_shared_chat_v1') then
    raise exception using errcode = '23514', message = 'The retired Operations Leadership message state is immutable';
  end if;
  if tg_op = 'UPDATE'
     and (
       exists (select 1 from public.msg_messages m join public.msg_threads t on t.id = m.thread_id where m.id = old.message_id and t.system_key = 'ops_manager_shared_chat_v1')
       or exists (select 1 from public.msg_messages m join public.msg_threads t on t.id = m.thread_id where m.id = new.message_id and t.system_key = 'ops_manager_shared_chat_v1')
     ) then
    raise exception using errcode = '23514', message = 'The retired Operations Leadership message state is immutable';
  end if;
  if tg_op = 'DELETE'
     and exists (select 1 from public.msg_messages m join public.msg_threads t on t.id = m.thread_id where m.id = old.message_id and t.system_key = 'ops_manager_shared_chat_v1') then
    raise exception using errcode = '23514', message = 'The retired Operations Leadership message state cannot be deleted';
  end if;
  return case when tg_op = 'DELETE' then old else new end;
end
$function$

CREATE OR REPLACE FUNCTION public.msg_reject_retired_ops_manager_shared_thread_evidence_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_old_thread_id uuid;
  v_new_thread_id uuid;
begin
  if tg_op<>'INSERT' then v_old_thread_id:=old.thread_id; end if;
  if tg_op<>'DELETE' then v_new_thread_id:=new.thread_id; end if;
  if exists (
    select 1 from public.msg_threads t
    where t.id in (v_old_thread_id,v_new_thread_id)
      and t.system_key='ops_manager_shared_chat_v1'
  ) then
    raise exception using errcode='23514',message='The retired Operations Leadership conversation evidence is immutable';
  end if;
  return case when tg_op='DELETE' then old else new end;
end
$function$

CREATE OR REPLACE FUNCTION public.msg_send_broadcast(p_sender_user_id uuid, p_title text, p_body text)
 RETURNS TABLE(thread_id uuid, broadcast_id uuid, message_id uuid, recipient_count integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_thread public.msg_threads%rowtype;
  v_broadcast public.msg_broadcasts%rowtype;
  v_message public.msg_messages%rowtype;
  v_count integer := 0;
begin
  if p_sender_user_id is null then raise exception 'sender_user_id is required.'; end if;
  if p_body is null or btrim(p_body) = '' then raise exception 'Broadcast body is required.'; end if;
  if not exists (
    select 1 from public.msg_users mu
    where mu.id = p_sender_user_id
      and mu.is_active = true
      and mu.role in ('manager', 'admin')
  ) then
    raise exception 'Manager role required.';
  end if;

  insert into public.msg_threads(thread_type, title, created_by_user_id, is_active, last_message_at)
  values ('broadcast', coalesce(nullif(btrim(p_title), ''), 'Ops Manager Broadcast'), p_sender_user_id, true, now())
  returning * into v_thread;

  insert into public.msg_thread_participants(thread_id, user_id)
  select v_thread.id, mu.id
  from public.msg_users mu
  where mu.is_active = true and mu.role <> 'bot';

  insert into public.msg_broadcasts(thread_id, created_by_user_id, title, body, target_type, target_json)
  values (v_thread.id, p_sender_user_id, nullif(btrim(coalesce(p_title, '')), ''), btrim(p_body), 'all_hands', '{}'::jsonb)
  returning * into v_broadcast;

  v_message := public.msg_send_message(
    v_thread.id,
    p_sender_user_id,
    p_body,
    'broadcast',
    jsonb_build_object('title', p_title, 'broadcast_id', v_broadcast.id, 'target_type', 'all_hands')
  );

  insert into public.msg_broadcast_recipients(
    broadcast_id, user_id, delivered_at, displayed_at, read_at, acknowledged_at
  )
  select v_broadcast.id, mu.id, null, null, null, null
  from public.msg_users mu
  where mu.is_active = true
    and mu.role <> 'bot'
    and mu.id <> p_sender_user_id;

  select count(*)::int into v_count
  from public.msg_broadcast_recipients br
  where br.broadcast_id = v_broadcast.id;

  return query select v_thread.id, v_broadcast.id, v_message.id, v_count;
end
$function$

CREATE OR REPLACE FUNCTION public.msg_send_message(p_thread_id uuid, p_sender_user_id uuid, p_body text, p_message_type text DEFAULT 'text'::text, p_metadata_json jsonb DEFAULT '{}'::jsonb)
 RETURNS msg_messages
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_message public.msg_messages%rowtype;
  v_metadata jsonb := coalesce(p_metadata_json, '{}'::jsonb);
  v_client_message_id text := nullif(btrim(coalesce(p_metadata_json->>'client_message_id', '')), '');
  v_source text := lower(btrim(coalesce(p_metadata_json->>'source', '')));
  v_event_id text := nullif(btrim(coalesce(p_metadata_json->>'event_id', '')), '');
  v_dedupe_key text := nullif(btrim(coalesce(
    p_metadata_json->>'notification_instance_key',
    p_metadata_json->>'instance_key',
    p_metadata_json->>'notification_key',
    p_metadata_json->>'alert_key',
    p_metadata_json->>'reminder_key',
    ''
  )), '');
begin
  if p_thread_id is null then raise exception 'thread_id is required.'; end if;
  if p_sender_user_id is null then raise exception 'sender_user_id is required.'; end if;
  if p_body is null or btrim(p_body) = '' then raise exception 'Message body is required.'; end if;
  if length(p_body) > 2000 then raise exception 'Message body cannot exceed 2000 characters.'; end if;
  if v_client_message_id is not null and length(v_client_message_id) > 200 then
    raise exception 'client_message_id cannot exceed 200 characters.';
  end if;
  perform public.msg_assert_active_mutable_thread(p_thread_id);
  if not exists (
    select 1 from public.msg_thread_participants tp
    where tp.thread_id=p_thread_id and tp.user_id=p_sender_user_id and tp.left_at is null
  ) then raise exception 'Sender is not an active participant in this thread.'; end if;

  if v_dedupe_key is null and v_source='events_app' and v_event_id is not null then
    v_dedupe_key:='event:'||v_event_id;
  end if;
  if v_dedupe_key is not null then
    if length(v_dedupe_key)>500 then raise exception 'notification instance key cannot exceed 500 characters'; end if;
    perform pg_advisory_xact_lock(hashtextextended(
      'message-notification:'||p_thread_id::text||':'||p_sender_user_id::text||':'||v_dedupe_key,0
    ));
    select * into v_message from public.msg_messages m
    where m.thread_id=p_thread_id and m.sender_user_id=p_sender_user_id and m.is_deleted is false
      and (m.metadata_json->>'notification_instance_key'=v_dedupe_key
        or (v_source='events_app' and v_event_id is not null
          and coalesce(m.metadata_json->>'source','')='events_app'
          and m.metadata_json->>'event_id'=v_event_id))
    order by m.sent_at limit 1;
    if found then return v_message; end if;
    v_metadata:=v_metadata||jsonb_build_object('notification_instance_key',v_dedupe_key);
  end if;
  if v_client_message_id is not null then
    select * into v_message from public.msg_messages m
    where m.sender_user_id=p_sender_user_id and m.client_message_id=v_client_message_id limit 1;
    if found then return v_message; end if;
  end if;
  insert into public.msg_messages(thread_id,sender_user_id,message_type,body,metadata_json,client_message_id)
  values(p_thread_id,p_sender_user_id,coalesce(nullif(btrim(p_message_type),''),'text'),btrim(p_body),v_metadata,v_client_message_id)
  returning * into v_message;
  insert into public.msg_receipts(message_id,user_id,delivered_at,displayed_at,read_at,acknowledged_at)
  select v_message.id,tp.user_id,null,null,null,null from public.msg_thread_participants tp
  where tp.thread_id=p_thread_id and tp.left_at is null and tp.user_id<>p_sender_user_id
  on conflict(message_id,user_id) do nothing;
  update public.msg_threads set last_message_at=v_message.sent_at,updated_at=now() where id=p_thread_id;
  return v_message;
exception when unique_violation then
  if v_client_message_id is not null then
    select * into v_message from public.msg_messages m
    where m.sender_user_id=p_sender_user_id and m.client_message_id=v_client_message_id limit 1;
    if found then return v_message; end if;
  end if;
  if v_dedupe_key is not null then
    select * into v_message from public.msg_messages m
    where m.thread_id=p_thread_id and m.sender_user_id=p_sender_user_id
      and m.metadata_json->>'notification_instance_key'=v_dedupe_key limit 1;
    if found then return v_message; end if;
  end if;
  raise;
end
$function$

CREATE OR REPLACE FUNCTION public.msg_send_message(p_thread_id uuid, p_sender_user_id uuid, p_body text, p_message_type text, p_metadata_json jsonb, p_client_message_id text)
 RETURNS msg_messages
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare v_message public.msg_messages%rowtype;
begin
  if p_thread_id is null then raise exception 'thread_id is required.'; end if;
  if p_sender_user_id is null then raise exception 'sender_user_id is required.'; end if;
  if p_body is null or btrim(p_body)='' then raise exception 'Message body is required.'; end if;
  if length(p_body)>4000 then raise exception 'Message body cannot exceed 4000 characters.'; end if;
  perform public.msg_assert_active_mutable_thread(p_thread_id);
  if not exists(select 1 from public.msg_thread_participants tp where tp.thread_id=p_thread_id and tp.user_id=p_sender_user_id and tp.left_at is null) then
    raise exception 'Sender is not an active participant in this thread.';
  end if;
  if nullif(btrim(coalesce(p_client_message_id,'')),'') is not null then
    select * into v_message from public.msg_messages where client_message_id=btrim(p_client_message_id) limit 1;
    if found then
      if v_message.thread_id<>p_thread_id or v_message.sender_user_id<>p_sender_user_id then raise exception 'client_message_id belongs to another message.'; end if;
      return v_message;
    end if;
  end if;
  insert into public.msg_messages(thread_id,sender_user_id,message_type,body,metadata_json,client_message_id)
  values(p_thread_id,p_sender_user_id,coalesce(nullif(btrim(p_message_type),''),'text'),btrim(p_body),coalesce(p_metadata_json,'{}'::jsonb),nullif(btrim(coalesce(p_client_message_id,'')),''))
  returning * into v_message;
  insert into public.msg_receipts(message_id,user_id,queued_at,delivered_at,displayed_at,read_at)
  select v_message.id,tp.user_id,now(),null,null,null from public.msg_thread_participants tp
  where tp.thread_id=p_thread_id and tp.left_at is null and tp.user_id<>p_sender_user_id
  on conflict(message_id,user_id) do nothing;
  update public.msg_threads set last_message_at=v_message.sent_at,updated_at=now() where id=p_thread_id;
  return v_message;
end
$function$

CREATE OR REPLACE FUNCTION public.msg_send_message_as_ops_manager(p_manager_id uuid, p_thread_id uuid, p_body text, p_message_type text DEFAULT 'text'::text, p_metadata_json jsonb DEFAULT '{}'::jsonb, p_client_message_id text DEFAULT NULL::text)
 RETURNS msg_messages
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_manager public.ops_manager_managers%rowtype;
  v_user public.msg_users%rowtype;
  v_message public.msg_messages%rowtype;
begin
  select * into v_manager from public.ops_manager_managers
  where manager_id=p_manager_id and active=true and revoked_at is null and is_system_principal=false;
  if v_manager.manager_id is null then
    raise exception using errcode='42501',message='Active named leadership identity was not found';
  end if;
  v_user:=public.msg_ensure_ops_manager_user(p_manager_id);
  v_message:=public.msg_send_message(
    p_thread_id,v_user.id,p_body,p_message_type,
    (coalesce(p_metadata_json,'{}'::jsonb)-'authenticated_ops_manager_id')
      ||jsonb_build_object('authenticated_ops_manager_id',p_manager_id),
    p_client_message_id
  );
  update public.msg_message_audit
  set sender_ops_manager_id=p_manager_id,
      sender_user_id=v_user.id,
      sender_display_name=v_manager.display_name,
      sender_role='manager'
  where message_id=v_message.id;
  return v_message;
end
$function$

