CREATE OR REPLACE FUNCTION public.mz_resolve_employee_push_delivery(p_credential_id uuid, p_assignment_epoch bigint, p_now timestamp with time zone DEFAULT now())
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_registration public.employee_push_registrations%rowtype;
  v_credential public.device_auth_credentials%rowtype;
  v_device public.devices%rowtype;
  v_employee_active boolean;
  v_reason text;
begin
  if p_credential_id is null or p_assignment_epoch is null or p_assignment_epoch<1 then
    raise exception using errcode='22023',message='credential and assignment epoch are required';
  end if;

  select * into v_registration
  from public.employee_push_registrations
  where credential_id=p_credential_id and assignment_epoch=p_assignment_epoch
  order by active desc,last_seen_at desc
  limit 1
  for update;

  select * into v_credential from public.device_auth_credentials
   where credential_id=p_credential_id;
  if v_credential.credential_id is not null then
    select * into v_device from public.devices where id=v_credential.device_id;
  end if;
  if v_registration.registration_id is not null then
    select active into v_employee_active from public.employees where id=v_registration.employee_id;
  end if;

  v_reason:=case
    when v_registration.registration_id is null then 'push_registration_missing'
    when v_credential.credential_id is null then 'device_credential_missing'
    when v_credential.revoked_at is not null then 'device_credential_revoked'
    when v_credential.expires_at<=p_now then 'device_credential_expired'
    when v_credential.confirmed_at is null then 'device_credential_unconfirmed'
    when v_registration.active is not true or v_registration.revoked_at is not null then 'push_registration_revoked'
    when v_device.id is null or v_device.id<>v_registration.device_id or v_credential.device_id<>v_registration.device_id then 'device_credential_device_mismatch'
    when v_device.active is not true then 'device_inactive'
    when v_device.assigned_employee_id is null or v_device.assigned_employee_id<>v_registration.employee_id then 'employee_assignment_superseded'
    when v_device.assignment_epoch<>v_registration.assignment_epoch or v_device.assignment_epoch<>p_assignment_epoch then 'assignment_epoch_superseded'
    when v_employee_active is not true then 'employee_inactive'
    else null
  end;

  if v_reason is not null then
    if v_registration.registration_id is not null and (v_registration.active=true or v_registration.revoked_at is null) then
      update public.employee_push_registrations
         set active=false,revoked_at=coalesce(revoked_at,p_now),revoked_reason=v_reason,updated_at=p_now
       where registration_id=v_registration.registration_id;
    end if;
    update public.event_push_instances
       set state='cancelled',cancelled_at=coalesce(cancelled_at,p_now),last_error=v_reason,updated_at=p_now
     where credential_id=p_credential_id and assignment_epoch=p_assignment_epoch and state in ('pending','leased');
    update public.operational_notification_jobs
       set status='dead',completed_at=coalesce(completed_at,p_now),last_error=v_reason,updated_at=p_now
     where job_type in ('employee_event_push','employee_native_push')
       and status in ('pending','leased')
       and payload_json->>'credential_id'=p_credential_id::text
       and payload_json->>'assignment_epoch'=p_assignment_epoch::text
       and (status='pending' or leased_until<p_now);
    return jsonb_build_object('ok',false,'terminal',true,'reason',v_reason);
  end if;

  return jsonb_build_object(
    'ok',true,'checked_at',p_now,
    'registration',to_jsonb(v_registration),
    'credential_id',p_credential_id,
    'device_id',v_registration.device_id,
    'employee_id',v_registration.employee_id,
    'assignment_epoch',v_registration.assignment_epoch
  );
end
$function$

CREATE OR REPLACE FUNCTION public.mz_retention_setting_int(p_key text, p_default integer, p_min integer DEFAULT 1, p_max integer DEFAULT 1000000)
 RETURNS integer
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_value integer;
begin
  v_value := public.get_setting_int(p_key, p_default);
  if v_value is null then
    v_value := p_default;
  end if;
  return greatest(p_min, least(p_max, v_value));
exception when others then
  return p_default;
end;
$function$

CREATE OR REPLACE FUNCTION public.operational_day_start(p_ref timestamp with time zone DEFAULT now())
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 STABLE
AS $function$
declare
  v_start_hour integer := public.get_setting_int('operational_day_start_hour', 4);
  v_local timestamp;
begin
  v_local := timezone('America/Chicago', p_ref);

  return (
    date_trunc('day', v_local - make_interval(hours => v_start_hour))
    + make_interval(hours => v_start_hour)
  ) at time zone 'America/Chicago';
end;
$function$

CREATE OR REPLACE FUNCTION public.ops_manager_consume_enrollment_code(p_code_hash text, p_credential_id uuid, p_device_id text, p_device_label text, p_trust_token_hash text, p_user_agent_hash text DEFAULT NULL::text, p_created_ip_hash text DEFAULT NULL::text, p_platform_summary text DEFAULT NULL::text, p_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_metadata_json jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_code public.ops_manager_enrollment_codes%rowtype;
  v_manager public.ops_manager_managers%rowtype;
  v_device public.ops_manager_trusted_devices%rowtype;
  v_now timestamptz := now();
  v_metadata jsonb := coalesce(p_metadata_json, '{}'::jsonb);
begin
  if p_code_hash is null or p_code_hash !~ '^[a-f0-9]{64}$' then
    return jsonb_build_object('ok', false, 'status', 400, 'reason', 'malformed');
  end if;
  if p_credential_id is null then raise exception 'credential_id is required'; end if;
  if p_device_id is null or length(trim(p_device_id)) < 1 or length(trim(p_device_id)) > 96 then
    raise exception 'valid device_id is required';
  end if;
  if p_device_label is null or length(trim(p_device_label)) < 1 or length(trim(p_device_label)) > 160 then
    raise exception 'valid device_label is required';
  end if;
  if p_trust_token_hash is null or p_trust_token_hash !~ '^[a-f0-9]{64}$' then
    raise exception 'valid trust token hash is required';
  end if;
  if p_expires_at is null or p_expires_at <= v_now then
    raise exception 'future trusted-device expiration is required';
  end if;
  if jsonb_typeof(v_metadata) <> 'object' then
    raise exception 'metadata_json must be an object';
  end if;

  select *
    into v_code
  from public.ops_manager_enrollment_codes
  where code_hash = lower(p_code_hash)
  for update;

  if not found then
    return jsonb_build_object('ok', false, 'status', 401, 'reason', 'invalid');
  end if;

  if v_code.status = 'used' or v_code.consumed_at is not null then
    return jsonb_build_object('ok', false, 'status', 410, 'reason', 'used', 'code_id', v_code.id);
  end if;
  if v_code.status = 'revoked' or v_code.revoked_at is not null then
    return jsonb_build_object('ok', false, 'status', 410, 'reason', 'revoked', 'code_id', v_code.id);
  end if;
  if v_code.status = 'locked' or v_code.attempt_count >= v_code.max_attempts then
    update public.ops_manager_enrollment_codes
       set status = 'locked',
           attempt_count = least(max_attempts, attempt_count + 1),
           metadata_json = metadata_json || jsonb_build_object('last_attempt_at', v_now)
     where id = v_code.id;
    return jsonb_build_object('ok', false, 'status', 429, 'reason', 'locked', 'code_id', v_code.id);
  end if;
  if v_code.expires_at <= v_now then
    update public.ops_manager_enrollment_codes
       set status = 'expired',
           attempt_count = least(max_attempts, attempt_count + 1),
           metadata_json = metadata_json || jsonb_build_object('expired_checked_at', v_now)
     where id = v_code.id;
    return jsonb_build_object('ok', false, 'status', 410, 'reason', 'expired', 'code_id', v_code.id);
  end if;

  select *
    into v_manager
  from public.ops_manager_managers
  where manager_id = v_code.manager_id
  for update;

  if not found or v_manager.active is not true or v_manager.revoked_at is not null then
    update public.ops_manager_enrollment_codes
       set attempt_count = least(max_attempts, attempt_count + 1),
           metadata_json = metadata_json || jsonb_build_object('manager_rejected_at', v_now)
     where id = v_code.id;
    return jsonb_build_object('ok', false, 'status', 403, 'reason', 'manager_inactive', 'code_id', v_code.id);
  end if;

  if not (v_code.role_snapshot = any(v_manager.roles)) then
    update public.ops_manager_enrollment_codes
       set attempt_count = least(max_attempts, attempt_count + 1),
           metadata_json = metadata_json || jsonb_build_object('role_rejected_at', v_now)
     where id = v_code.id;
    return jsonb_build_object('ok', false, 'status', 403, 'reason', 'role_mismatch', 'code_id', v_code.id);
  end if;

  update public.ops_manager_trusted_devices
     set revoked_at = v_now,
         revoked_reason = 'device_re-enrolled_by_manager_code'
   where device_id = trim(p_device_id)
     and revoked_at is null;

  insert into public.ops_manager_trusted_devices (
    credential_id,
    device_id,
    device_label,
    token_hash,
    max_access_level,
    manager_id,
    manager_enrollment_code_id,
    user_agent_hash,
    created_ip_hash,
    platform_summary,
    expires_at,
    metadata_json
  )
  values (
    p_credential_id,
    trim(p_device_id),
    trim(p_device_label),
    lower(p_trust_token_hash),
    'full_access',
    v_manager.manager_id,
    v_code.id,
    p_user_agent_hash,
    p_created_ip_hash,
    nullif(left(coalesce(p_platform_summary, ''), 160), ''),
    p_expires_at,
    v_metadata || jsonb_build_object(
      'manager_enrollment_code_id', v_code.id,
      'enrollment_source', 'one_time_manager_code',
      'role_snapshot', v_code.role_snapshot
    )
  )
  returning * into v_device;

  update public.ops_manager_enrollment_codes
     set consumed_at = v_now,
         consumed_credential_id = p_credential_id,
         consumed_device_id = trim(p_device_id),
         status = 'used',
         metadata_json = metadata_json || jsonb_build_object(
           'used_user_agent_hash', p_user_agent_hash,
           'used_ip_hash', p_created_ip_hash,
           'platform_summary', nullif(left(coalesce(p_platform_summary, ''), 160), '')
         )
   where id = v_code.id;

  update public.ops_manager_managers
     set last_access_at = v_now
   where manager_id = v_manager.manager_id;

  return jsonb_build_object(
    'ok', true,
    'code_id', v_code.id,
    'manager', jsonb_build_object(
      'manager_id', v_manager.manager_id,
      'display_name', v_manager.display_name,
      'contact_label', v_manager.contact_label,
      'roles', v_manager.roles,
      'active', v_manager.active,
      'revoked_at', v_manager.revoked_at,
      'created_at', v_manager.created_at,
      'last_access_at', v_now
    ),
    'trusted_device', jsonb_build_object(
      'credential_id', v_device.credential_id,
      'device_id', v_device.device_id,
      'device_label', v_device.device_label,
      'manager_id', v_device.manager_id,
      'manager_enrollment_code_id', v_code.id,
      'max_access_level', v_device.max_access_level,
      'created_at', v_device.created_at,
      'expires_at', v_device.expires_at
    )
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.ops_manager_consume_manager_invitation(p_token text, p_credential_id uuid, p_device_id text, p_device_label text, p_trust_token_hash text, p_user_agent_hash text DEFAULT NULL::text, p_created_ip_hash text DEFAULT NULL::text, p_platform_summary text DEFAULT NULL::text, p_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_metadata_json jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_hash text;
  v_invite public.ops_manager_pairing_tokens%rowtype;
  v_manager public.ops_manager_managers%rowtype;
  v_device public.ops_manager_trusted_devices%rowtype;
  v_now timestamptz := now();
  v_metadata jsonb := coalesce(p_metadata_json, '{}'::jsonb);
begin
  if p_token is null or p_token !~ '^[a-f0-9]{64}$' then
    return jsonb_build_object('ok', false, 'status', 400, 'reason', 'malformed');
  end if;
  if p_credential_id is null then raise exception 'credential_id is required'; end if;
  if p_device_id is null or length(trim(p_device_id)) < 1 or length(trim(p_device_id)) > 96 then
    raise exception 'valid device_id is required';
  end if;
  if p_device_label is null or length(trim(p_device_label)) < 1 or length(trim(p_device_label)) > 160 then
    raise exception 'valid device_label is required';
  end if;
  if p_trust_token_hash is null or length(p_trust_token_hash) <> 64 then
    raise exception 'valid trust token hash is required';
  end if;
  if p_expires_at is null or p_expires_at <= v_now then
    raise exception 'future trusted-device expiration is required';
  end if;
  if jsonb_typeof(v_metadata) <> 'object' then
    raise exception 'metadata_json must be an object';
  end if;

  v_hash := encode(digest(lower(p_token), 'sha256'), 'hex');

  select *
    into v_invite
  from public.ops_manager_pairing_tokens
  where token_hash = v_hash
  for update;

  if not found then
    return jsonb_build_object('ok', false, 'status', 401, 'reason', 'invalid');
  end if;
  if v_invite.revoked_at is not null then
    return jsonb_build_object('ok', false, 'status', 410, 'reason', 'revoked', 'pairing_id', v_invite.pairing_id);
  end if;
  if v_invite.expires_at <= v_now then
    update public.ops_manager_pairing_tokens
    set metadata_json = metadata_json || jsonb_build_object('expired_checked_at', v_now)
    where pairing_id = v_invite.pairing_id;
    return jsonb_build_object('ok', false, 'status', 410, 'reason', 'expired', 'pairing_id', v_invite.pairing_id);
  end if;
  if v_invite.used_at is not null or v_invite.use_count >= v_invite.max_uses then
    return jsonb_build_object('ok', false, 'status', 410, 'reason', 'used', 'pairing_id', v_invite.pairing_id);
  end if;
  if v_invite.manager_id is null then
    return jsonb_build_object('ok', false, 'status', 409, 'reason', 'manager_required', 'pairing_id', v_invite.pairing_id);
  end if;

  select *
    into v_manager
  from public.ops_manager_managers
  where manager_id = v_invite.manager_id
  for update;

  if not found or not v_manager.active or v_manager.revoked_at is not null then
    return jsonb_build_object('ok', false, 'status', 410, 'reason', 'manager_inactive', 'pairing_id', v_invite.pairing_id);
  end if;
  if v_invite.intended_role is not null and not (v_invite.intended_role = any(v_manager.roles)) then
    return jsonb_build_object('ok', false, 'status', 409, 'reason', 'role_mismatch', 'pairing_id', v_invite.pairing_id);
  end if;

  update public.ops_manager_trusted_devices
  set revoked_at = v_now,
      revoked_reason = 'device_re-enrolled_by_manager_invitation'
  where device_id = trim(p_device_id)
    and revoked_at is null;

  insert into public.ops_manager_trusted_devices (
    credential_id, device_id, device_label, token_hash, max_access_level,
    user_agent_hash, created_ip_hash, expires_at, manager_id, invitation_id,
    platform_summary, metadata_json
  )
  values (
    p_credential_id,
    trim(p_device_id),
    trim(p_device_label),
    p_trust_token_hash,
    'full_access',
    p_user_agent_hash,
    p_created_ip_hash,
    p_expires_at,
    v_manager.manager_id,
    v_invite.pairing_id,
    nullif(left(coalesce(p_platform_summary, ''), 160), ''),
    v_metadata || jsonb_build_object(
      'pairing_id', v_invite.pairing_id,
      'manager_id', v_manager.manager_id,
      'invitation_kind', v_invite.invitation_kind,
      'enrollment_source', 'named_manager_invitation'
    )
  )
  returning * into v_device;

  update public.ops_manager_pairing_tokens
  set use_count = use_count + 1,
      used_at = case when use_count + 1 >= max_uses then v_now else used_at end,
      used_by_credential_id = p_credential_id,
      used_by_device_id = trim(p_device_id),
      metadata_json = metadata_json || jsonb_build_object(
        'used_user_agent_hash', p_user_agent_hash,
        'used_ip_hash', p_created_ip_hash,
        'last_used_at', v_now
      )
  where pairing_id = v_invite.pairing_id;

  update public.ops_manager_managers
  set last_access_at = v_now
  where manager_id = v_manager.manager_id;

  return jsonb_build_object(
    'ok', true,
    'pairing_id', v_invite.pairing_id,
    'manager', jsonb_build_object(
      'manager_id', v_manager.manager_id,
      'display_name', v_manager.display_name,
      'contact_label', v_manager.contact_label,
      'roles', to_jsonb(v_manager.roles)
    ),
    'trusted_device', jsonb_build_object(
      'credential_id', v_device.credential_id,
      'device_id', v_device.device_id,
      'device_label', v_device.device_label,
      'manager_id', v_device.manager_id,
      'created_at', v_device.created_at,
      'expires_at', v_device.expires_at
    )
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.ops_manager_consume_pairing_and_enroll(p_token text, p_credential_id uuid, p_device_id text, p_device_label text, p_trust_token_hash text, p_max_access_level text DEFAULT 'full_access'::text, p_user_agent_hash text DEFAULT NULL::text, p_created_ip_hash text DEFAULT NULL::text, p_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_metadata_json jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_hash text;
  v_pairing public.ops_manager_pairing_tokens%rowtype;
  v_device public.ops_manager_trusted_devices%rowtype;
  v_now timestamptz := now();
  v_metadata jsonb := coalesce(p_metadata_json, '{}'::jsonb);
  v_max_access text;
begin
  if p_token is null or p_token !~ '^[a-f0-9]{64}$' then
    return jsonb_build_object('ok', false, 'status', 400, 'reason', 'malformed');
  end if;
  if p_credential_id is null then
    raise exception 'credential_id is required';
  end if;
  if p_device_id is null or length(trim(p_device_id)) < 1 or length(trim(p_device_id)) > 96 then
    raise exception 'valid device_id is required';
  end if;
  if p_device_label is null or length(trim(p_device_label)) < 1 or length(trim(p_device_label)) > 160 then
    raise exception 'valid device_label is required';
  end if;
  if p_trust_token_hash is null or length(p_trust_token_hash) <> 64 then
    raise exception 'valid trust token hash is required';
  end if;
  if p_expires_at is null or p_expires_at <= v_now then
    raise exception 'future trusted-device expiration is required';
  end if;
  if jsonb_typeof(v_metadata) <> 'object' then
    raise exception 'metadata_json must be an object';
  end if;

  v_hash := encode(digest(lower(p_token), 'sha256'), 'hex');

  select *
    into v_pairing
  from public.ops_manager_pairing_tokens
  where token_hash = v_hash
  for update;

  if not found then
    return jsonb_build_object('ok', false, 'status', 401, 'reason', 'invalid');
  end if;
  if v_pairing.used_at is not null then
    return jsonb_build_object('ok', false, 'status', 410, 'reason', 'used', 'pairing_id', v_pairing.pairing_id);
  end if;
  if v_pairing.revoked_at is not null then
    return jsonb_build_object('ok', false, 'status', 410, 'reason', 'revoked', 'pairing_id', v_pairing.pairing_id);
  end if;
  if v_pairing.expires_at <= v_now then
    return jsonb_build_object('ok', false, 'status', 410, 'reason', 'expired', 'pairing_id', v_pairing.pairing_id);
  end if;

  v_max_access := case
    when v_pairing.max_access_level = 'full_access' and coalesce(p_max_access_level, 'full_access') = 'full_access' then 'full_access'
    else 'read_only'
  end;

  update public.ops_manager_trusted_devices
  set revoked_at = v_now,
      revoked_reason = 'device_re-enrolled_by_pairing'
  where device_id = trim(p_device_id)
    and revoked_at is null;

  insert into public.ops_manager_trusted_devices (
