  values (
    p_credential_id,
    trim(p_device_id),
    trim(p_device_label),
    p_trust_token_hash,
    v_max_access,
    p_user_agent_hash,
    p_created_ip_hash,
    p_expires_at,
    v_metadata || jsonb_build_object(
      'pairing_id', v_pairing.pairing_id,
      'enrollment_source', 'one_time_pairing_link'
