CREATE OR REPLACE FUNCTION public.start_session(p_location_code text, p_employee_name text, p_device_id text, p_client_session_id text DEFAULT NULL::text)
 RETURNS TABLE(session_uuid text, location_name text, employee_name text, device_id text, status text, started_at timestamp with time zone)
 LANGUAGE plpgsql
AS $function$
declare
  v_location_id uuid;
  v_location_name text;
  v_employee_id uuid;
  v_employee_name text;
  v_device_pk uuid;
  v_session_id uuid;
  v_session_uuid text;
  v_started_at timestamptz := now();
  v_resolved_location_code text := public.resolve_scan_location_code(p_location_code);
begin
  if p_client_session_id is not null then
    select
      s.id,
      s.session_uuid,
      l.location_name,
      e.display_name,
      s.started_at
    into
      v_session_id,
      v_session_uuid,
      v_location_name,
      v_employee_name,
      v_started_at
    from public.sessions s
    join public.locations l on l.id = s.location_id
    join public.employees e on e.id = s.employee_id
    where s.client_session_id = p_client_session_id
    limit 1;

    if v_session_id is not null then
      return query
      select
        v_session_uuid,
        v_location_name,
        v_employee_name,
        p_device_id,
        'active'::text,
        v_started_at;
      return;
    end if;

    v_started_at := now();
  end if;

  select l.id, l.location_name
    into v_location_id, v_location_name
  from public.locations l
  where l.location_code = v_resolved_location_code
    and l.active = true
  limit 1;

  if v_location_id is null then
    raise exception 'Active location not found for code: %', p_location_code;
  end if;

  select e.id, e.display_name
    into v_employee_id, v_employee_name
  from public.employees e
  where e.display_name = p_employee_name
    and e.active = true
  limit 1;

  if v_employee_id is null then
    raise exception 'Active employee not found: %', p_employee_name;
  end if;

  select d.id
    into v_device_pk
  from public.devices d
  where d.device_id = p_device_id
    and d.active = true
  limit 1;

  if v_device_pk is null then
    raise exception 'Active device not found: %', p_device_id;
  end if;

  perform public.expire_stale_open_sessions(v_started_at);

  if exists (
    select 1 from public.sessions s
    where s.employee_id = v_employee_id
      and s.status in ('active', 'pending_submit')
  ) then
    raise exception 'Employee already has an open session: %', p_employee_name;
  end if;

  if exists (
    select 1 from public.sessions s
    where s.location_id = v_location_id
      and s.status in ('active', 'pending_submit')
  ) then
    raise exception 'Location already has an open session: %', coalesce(v_resolved_location_code, p_location_code);
  end if;

  if exists (
    select 1 from public.sessions s
    where s.device_id = v_device_pk
      and s.status in ('active', 'pending_submit')
  ) then
    raise exception 'Device already has an open session: %', p_device_id;
  end if;

  v_session_uuid := gen_random_uuid()::text;

  insert into public.sessions (
    session_uuid,
    client_session_id,
    location_id,
    employee_id,
    device_id,
    status,
    started_at,
    completion_source
  )
  values (
    v_session_uuid,
    p_client_session_id,
    v_location_id,
    v_employee_id,
    v_device_pk,
    'active',
    v_started_at,
    null
  )
  returning id into v_session_id;

  insert into public.session_events (
    session_id,
    event_type,
    actor_type,
    actor_ref,
    details_json
  )
  values (
    v_session_id,
    'session_started',
    'device',
    p_device_id,
    jsonb_build_object(
      'location_code', coalesce(v_resolved_location_code, p_location_code),
      'scan_input_code', p_location_code,
      'employee_name', p_employee_name,
      'device_id', p_device_id,
      'client_session_id', p_client_session_id
    )
  );

  insert into public.system_logs (
    level,
    source,
    message,
    session_id,
    location_id,
    device_id
  )
  values (
    'INFO',
    'start_session',
    'Session started',
    v_session_id,
    v_location_id,
    v_device_pk
  );

  return query
  select
    v_session_uuid,
    v_location_name,
    v_employee_name,
    p_device_id,
    'active'::text,
    v_started_at;
end;
$function$

CREATE OR REPLACE FUNCTION public.start_session_v2(p_location_code text, p_device_id text, p_client_session_id text, p_client_started_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_correlation_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_location_id uuid;
  v_location_code text;
  v_location_name text;
  v_location_type text;
  v_form_type text;
  v_device_pk uuid;
  v_device_id text;
  v_device_name text;
  v_employee_id uuid;
  v_employee_name text;
  v_session_id uuid;
  v_session_uuid text;
  v_status text;
  v_started_at timestamptz;
  v_inserted boolean := false;
  v_client_id text := nullif(btrim(coalesce(p_client_session_id, '')), '');
begin
  if v_client_id is null or length(v_client_id) > 200 then
    raise exception 'client_session_id is required and must be at most 200 characters';
  end if;
  if nullif(btrim(coalesce(p_device_id, '')), '') is null then
    raise exception 'device_id is required';
  end if;
  if nullif(btrim(coalesce(p_location_code, '')), '') is null then
    raise exception 'location_code is required';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('scan-start:' || v_client_id, 0));

  select s.id, s.session_uuid, s.status, s.started_at,
         l.location_code, l.location_name, l.location_type, l.form_type,
         d.device_id, d.device_name,
         e.id, e.display_name
    into v_session_id, v_session_uuid, v_status, v_started_at,
         v_location_code, v_location_name, v_location_type, v_form_type,
         v_device_id, v_device_name,
         v_employee_id, v_employee_name
  from public.sessions s
  join public.locations l on l.id = s.location_id
  join public.devices d on d.id = s.device_id
  join public.employees e on e.id = s.employee_id
  where s.client_session_id = v_client_id
  limit 1;

  if v_session_id is not null then
    if upper(btrim(v_device_id)) <> upper(btrim(p_device_id)) then
      raise exception 'client_session_id is already bound to another device';
    end if;
    return jsonb_build_object(
      'session_uuid', v_session_uuid,
      'client_session_id', v_client_id,
      'location_code', v_location_code,
      'location_name', v_location_name,
      'location_type', v_location_type,
      'form_type', v_form_type,
      'employee_name', v_employee_name,
      'device_id', v_device_id,
      'device_name', v_device_name,
      'status', v_status,
      'started_at', v_started_at,
      'replayed', true,
      'correlation_id', nullif(btrim(coalesce(p_correlation_id, '')), '')
    );
  end if;

  select l.id, l.location_code, l.location_name, l.location_type, l.form_type
    into v_location_id, v_location_code, v_location_name, v_location_type, v_form_type
  from public.locations l
  where l.location_code = public.resolve_scan_location_code(p_location_code)
    and l.active = true
  limit 1;
  if v_location_id is null then
    raise exception 'Active location not found for code: %', p_location_code;
  end if;

  select d.id, d.device_id, d.device_name, e.id, e.display_name
    into v_device_pk, v_device_id, v_device_name, v_employee_id, v_employee_name
  from public.devices d
  left join public.employees e on e.id = d.assigned_employee_id and e.active = true
  where upper(btrim(d.device_id)) = upper(btrim(p_device_id))
    and d.active = true
  limit 1;
  if v_device_pk is null then
    raise exception 'Active device not found: %', p_device_id;
  end if;
  if v_employee_id is null then
    raise exception 'Device % is not assigned to an active employee', v_device_id;
  end if;

  perform public.expire_stale_open_sessions(now());

  if exists (
    select 1 from public.sessions s
    where s.device_id = v_device_pk
      and s.status in ('active', 'pending_submit')
  ) then
    raise exception 'Device already has another open session: %', v_device_id;
  end if;
  if exists (
    select 1 from public.sessions s
    where s.employee_id = v_employee_id
      and s.status in ('active', 'pending_submit')
  ) then
    raise exception 'Assigned employee already has another open session: %', v_employee_name;
  end if;
  if exists (
    select 1 from public.sessions s
    where s.location_id = v_location_id
      and s.status in ('active', 'pending_submit')
  ) then
    raise exception 'Location already has another open session: %', v_location_code;
  end if;

  v_started_at := coalesce(p_client_started_at, now());
  if v_started_at > now() + interval '10 minutes' then
    raise exception 'client_started_at is too far in the future';
  end if;
  if v_started_at < now() - interval '7 days' then
    raise exception 'client_started_at is too old';
  end if;

  v_session_uuid := gen_random_uuid()::text;
  insert into public.sessions(
    session_uuid,
    client_session_id,
    location_id,
    employee_id,
    device_id,
    status,
    started_at,
    completion_source
  ) values (
    v_session_uuid,
    v_client_id,
    v_location_id,
    v_employee_id,
    v_device_pk,
    'active',
    v_started_at,
    null
  ) returning id into v_session_id;
  v_inserted := true;

  insert into public.session_events(session_id, event_type, actor_type, actor_ref, details_json)
  values (
    v_session_id,
    'session_started',
    'device',
    v_device_id,
    jsonb_build_object(
      'location_code', v_location_code,
      'device_id', v_device_id,
      'employee_name', v_employee_name,
      'client_session_id', v_client_id,
      'correlation_id', nullif(btrim(coalesce(p_correlation_id, '')), ''),
      'identity_source', 'devices.assigned_employee_id'
    )
  );

  insert into public.system_logs(level, source, message, session_id, location_id, device_id)
  values ('INFO', 'start_session_v2', 'Server-authoritative session started', v_session_id, v_location_id, v_device_pk);

  return jsonb_build_object(
    'session_uuid', v_session_uuid,
    'client_session_id', v_client_id,
    'location_code', v_location_code,
    'location_name', v_location_name,
    'location_type', v_location_type,
    'form_type', v_form_type,
    'employee_name', v_employee_name,
    'device_id', v_device_id,
    'device_name', v_device_name,
    'status', 'active',
    'started_at', v_started_at,
    'replayed', not v_inserted,
    'correlation_id', nullif(btrim(coalesce(p_correlation_id, '')), '')
  );
exception
  when unique_violation then
    select s.id, s.session_uuid, s.status, s.started_at,
           l.location_code, l.location_name, l.location_type, l.form_type,
           d.device_id, d.device_name,
           e.id, e.display_name
      into v_session_id, v_session_uuid, v_status, v_started_at,
           v_location_code, v_location_name, v_location_type, v_form_type,
           v_device_id, v_device_name,
           v_employee_id, v_employee_name
    from public.sessions s
    join public.locations l on l.id = s.location_id
    join public.devices d on d.id = s.device_id
    join public.employees e on e.id = s.employee_id
    where s.client_session_id = v_client_id
    limit 1;
    if v_session_id is null then raise; end if;
    return jsonb_build_object(
      'session_uuid', v_session_uuid,
      'client_session_id', v_client_id,
      'location_code', v_location_code,
      'location_name', v_location_name,
      'location_type', v_location_type,
      'form_type', v_form_type,
      'employee_name', v_employee_name,
      'device_id', v_device_id,
      'device_name', v_device_name,
      'status', v_status,
      'started_at', v_started_at,
      'replayed', true,
      'correlation_id', nullif(btrim(coalesce(p_correlation_id, '')), '')
    );
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_advance_authority(p_expected_revision bigint, p_operation text, p_actor_manager_id uuid, p_actor_manager_name text, p_command_id uuid, p_digest text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_revision bigint;
begin
  update public.static_weekly_schedule_control set current_revision=current_revision+1,updated_at=statement_timestamp(),updated_by_manager_id=p_actor_manager_id,updated_by_manager_name_snapshot=p_actor_manager_name
  where singleton and current_revision=p_expected_revision returning current_revision into v_revision;
  if v_revision is null then raise exception using errcode='40001',message='stale expected revision'; end if;
  insert into public.weekly_schedule_authority_revisions(authority_revision,command_id,operation,actor_manager_id,actor_manager_name_snapshot,content_digest) values(v_revision,p_command_id,p_operation,p_actor_manager_id,p_actor_manager_name,p_digest);
  return v_revision;
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_assert_authority_attestation(p_attestation jsonb, p_scope text, p_payload jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_key public.static_weekly_authority_attestation_keys%rowtype; v_signature text; v_expected text;
begin
  perform public.static_weekly_assert_exact_object(p_attestation,array['schema','key_id','scope','payload_digest','signature'],array['schema','key_id','scope','payload_digest','signature'],'authority attestation');
  if p_attestation->>'schema' is distinct from 'memphis-zoo.static-weekly-authority-attestation.v2' or p_attestation->>'scope' is distinct from p_scope or p_attestation->>'payload_digest' is distinct from public.static_weekly_digest_jsonb(p_payload) or jsonb_typeof(p_attestation->'key_id') is distinct from 'string' or jsonb_typeof(p_attestation->'signature') is distinct from 'string' then raise exception using errcode='23514',message='complete versioned authority attestation is required'; end if;
  v_signature:=p_attestation->>'signature';
  if v_signature !~ '^[0-9a-f]{64}$' then raise exception using errcode='23514',message='authority attestation signature must be canonical lower-case fixed-length hex'; end if;
  select * into v_key from public.static_weekly_authority_attestation_keys where key_id=p_attestation->>'key_id' and key_state in ('active','overlap') and activates_at<=statement_timestamp() and (verify_not_after is null or verify_not_after>statement_timestamp()) for share;
  if not found then raise exception using errcode='23514',message='authority attestation key is unknown, expired, or revoked'; end if;
  v_expected:=public.static_weekly_v3_hmac(v_key.secret_material,p_scope,p_payload);
  if not public.static_weekly_v3_constant_time_equal(decode(v_signature,'hex'),decode(v_expected,'hex')) then raise exception using errcode='23514',message='authority attestation does not bind the canonical semantic payload'; end if;
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_assert_document_attested(p_document jsonb, p_effective_start date, p_require_publishable boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_legacy jsonb; v_payload jsonb; v_snapshot jsonb;
begin
  perform public.static_weekly_assert_exact_object(p_document,
    array['adapter','authority','receipt','slot_availability','assignments','objective_inputs','validation','semantic_snapshot','attestation'],
    array['adapter','authority','receipt','slot_availability','assignments','objective_inputs','validation','semantic_snapshot','attestation'],'attested adapter document');
  v_payload:=public.static_weekly_document_attestation_payload(p_document);
  perform public.static_weekly_assert_authority_attestation(p_document->'attestation','recurring_document',v_payload);
  v_snapshot:=p_document->'semantic_snapshot';
  perform public.static_weekly_assert_exact_object(v_snapshot,
    array['schema','recurring_source','relational_slot_availability','relational_assignments'],
    array['schema','recurring_source','relational_slot_availability','relational_assignments'],'recurring semantic snapshot');
  if v_snapshot->>'schema' is distinct from 'memphis-zoo.static-weekly-recurring-semantic-snapshot.v1'
    or v_snapshot->'recurring_source' is distinct from p_document#>'{authority,compilerInput}'
    or v_snapshot->'relational_slot_availability' is distinct from p_document->'slot_availability'
    or v_snapshot->'relational_assignments' is distinct from p_document->'assignments'
    or p_document#>>'{validation,database_document_identity}' is distinct from public.static_weekly_digest_jsonb(v_payload) then
    raise exception using errcode='23514',message='attested recurring semantic snapshot and relational materialization must be exact';
  end if;
  -- Reuse the original I2 type/optimizer parity validator against its exact
  -- historical envelope shape.  The new snapshot and HMAC are checked before
  -- it, so no omitted semantic fact can be replaced by a recomputable digest.
  v_legacy:=p_document-'semantic_snapshot'-'attestation';
  v_legacy:=jsonb_set(v_legacy,'{validation,database_document_identity}',to_jsonb(public.static_weekly_document_identity(v_legacy)),true);
  perform public.static_weekly_assert_document(v_legacy,p_effective_start,p_require_publishable);
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_assert_exception_payload(p_exception_type text, p_service_date date, p_starts_at time without time zone, p_ends_at time without time zone, p_base_version_id uuid, p_publication_id uuid, p_payload jsonb, p_reverses_exception_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_slot text; v_lock jsonb; v_patch jsonb; v_add jsonb; v_ids text[]; v_effort numeric;
begin
  if jsonb_typeof(p_payload) is distinct from 'object' then raise exception using errcode='23514',message='exception payload must be an exact JSON object'; end if;
  if exists(select 1 from public.weekly_schedule_exception_commands e where e.publication_id=p_publication_id and e.base_version_id=p_base_version_id and e.service_date=p_service_date and e.exception_type=p_exception_type and e.payload_digest=public.static_weekly_digest_jsonb(p_payload) and not exists(select 1 from public.weekly_schedule_exception_commands r where r.reverses_exception_id=e.exception_id)) then
    raise exception using errcode='23514',message='duplicate semantic exception command is already effective';
  end if;
  if p_exception_type in ('pto','daily_absence') then
    perform public.static_weekly_assert_exact_object(p_payload,array['slotId'],array['slotId'],p_exception_type||' payload'); perform public.static_weekly_v3_assert_uuid(p_payload->'slotId',p_exception_type||' slotId'); v_slot:=p_payload->>'slotId';
    if p_starts_at is not null or p_ends_at is not null or not public.static_weekly_exception_slot_exists(p_base_version_id,p_service_date,v_slot,true)
      or exists(select 1 from public.weekly_schedule_exception_commands e where e.publication_id=p_publication_id and e.service_date=p_service_date and e.exception_type in ('pto','daily_absence','partial_absence','lunch') and e.payload_json->>'slotId'=v_slot and not exists(select 1 from public.weekly_schedule_exception_commands r where r.reverses_exception_id=e.exception_id)) then
      raise exception using errcode='23514',message='full-day absence must target one currently working slot without conflict or no-op';
    end if;
  elsif p_exception_type in ('partial_absence','lunch') then
    perform public.static_weekly_assert_exact_object(p_payload,array['slotId'],array['slotId'],p_exception_type||' payload'); perform public.static_weekly_v3_assert_uuid(p_payload->'slotId',p_exception_type||' slotId'); v_slot:=p_payload->>'slotId';
    if p_starts_at is null or p_ends_at is null or not public.static_weekly_exception_slot_exists(p_base_version_id,p_service_date,v_slot,true)
      or exists(select 1 from public.weekly_schedule_exception_commands e where e.publication_id=p_publication_id and e.service_date=p_service_date and e.exception_type in ('pto','daily_absence') and e.payload_json->>'slotId'=v_slot and not exists(select 1 from public.weekly_schedule_exception_commands r where r.reverses_exception_id=e.exception_id))
      or exists(select 1 from public.weekly_schedule_exception_commands e where e.publication_id=p_publication_id and e.service_date=p_service_date and e.exception_type in ('partial_absence','lunch') and e.payload_json->>'slotId'=v_slot and not exists(select 1 from public.weekly_schedule_exception_commands r where r.reverses_exception_id=e.exception_id) and p_starts_at<e.ends_at and e.starts_at<p_ends_at) then
      raise exception using errcode='23514',message='partial absence or lunch must target one working slot with a nonoverlapping effective window';
    end if;
  elsif p_exception_type='shift_override' then
    perform public.static_weekly_assert_exact_object(p_payload,array['slotId','status','shift'],array['slotId','status','shift'],'shift override payload'); perform public.static_weekly_v3_assert_uuid(p_payload->'slotId','shift override slotId'); perform public.static_weekly_v3_assert_window(p_payload->'shift','shift override shift'); v_slot:=p_payload->>'slotId';
    if p_starts_at is not null or p_ends_at is not null or p_payload->>'status' not in ('working','absent','unavailable') or not public.static_weekly_exception_slot_exists(p_base_version_id,p_service_date,v_slot,false)
      or exists(select 1 from public.weekly_schedule_exception_commands e where e.publication_id=p_publication_id and e.service_date=p_service_date and e.exception_type='shift_override' and e.payload_json->>'slotId'=v_slot and not exists(select 1 from public.weekly_schedule_exception_commands r where r.reverses_exception_id=e.exception_id)) then raise exception using errcode='23514',message='shift override requires one extant slot and one nonduplicate exact replacement'; end if;
  elsif p_exception_type='cover_all' then
    perform public.static_weekly_assert_exact_object(p_payload,array['availability'],array['availability'],'coverall payload');
    perform public.static_weekly_assert_exact_object(p_payload->'availability',array['slotId','shift','productiveCapacityProvenance','maxServiceEffortMinutes','maxServiceEffortProvenance','qualifications','qualificationProvenance','restrictions','restrictionProvenance','acceptedRouteAnchorLocationId','acceptedRouteProvenance'],array['slotId','shift','productiveCapacityProvenance','maxServiceEffortMinutes','maxServiceEffortProvenance','qualifications','qualificationProvenance','restrictions','restrictionProvenance','acceptedRouteAnchorLocationId','acceptedRouteProvenance'],'coverall availability');
    perform public.static_weekly_v3_assert_uuid(p_payload#>'{availability,slotId}','coverall slotId'); perform public.static_weekly_v3_assert_window(p_payload#>'{availability,shift}','coverall shift'); perform public.static_weekly_v3_assert_uuid(p_payload#>'{availability,acceptedRouteAnchorLocationId}','coverall route anchor');
    foreach v_slot in array array['productiveCapacityProvenance','maxServiceEffortProvenance','qualificationProvenance','restrictionProvenance','acceptedRouteProvenance'] loop perform public.static_weekly_v3_assert_text(p_payload#>array['availability',v_slot],'coverall '||v_slot); end loop;
    perform public.static_weekly_v3_assert_string_array(p_payload#>'{availability,qualifications}','coverall qualifications'); perform public.static_weekly_v3_assert_string_array(p_payload#>'{availability,restrictions}','coverall restrictions');
    if jsonb_typeof(p_payload#>'{availability,maxServiceEffortMinutes}') is distinct from 'number' then raise exception using errcode='23514',message='coverall maximum effort must be a JSON integer'; end if; v_effort:=(p_payload#>>'{availability,maxServiceEffortMinutes}')::numeric;
    if v_effort<>trunc(v_effort) or v_effort<1 or v_effort>1440 or p_starts_at is not null or p_ends_at is not null or not public.static_weekly_exception_slot_exists(p_base_version_id,p_service_date,p_payload#>>'{availability,slotId}',false)
      or exists(select 1 from public.weekly_schedule_exception_commands e where e.publication_id=p_publication_id and e.service_date=p_service_date and e.exception_type='cover_all' and e.payload_json#>>'{availability,slotId}'=p_payload#>>'{availability,slotId}' and not exists(select 1 from public.weekly_schedule_exception_commands r where r.reverses_exception_id=e.exception_id)) then raise exception using errcode='23514',message='coverall requires one extant slot and one bounded nonduplicate availability replacement'; end if;
  elsif p_exception_type in ('nine_forty_five_rebalance','manager_correction') then
    perform public.static_weekly_assert_exact_object(p_payload,array['locks'],array['locks'],p_exception_type||' payload');
    if jsonb_typeof(p_payload->'locks') is distinct from 'array' or jsonb_array_length(p_payload->'locks')=0 or p_starts_at is not null or p_ends_at is not null then raise exception using errcode='23514',message='rebalance and correction require nonempty lock arrays without a window'; end if;
    for v_lock in select value from jsonb_array_elements(p_payload->'locks') loop
      perform public.static_weekly_assert_exact_object(v_lock,array['workId','slotId'],array['workId','slotId'],'manager correction lock'); perform public.static_weekly_v3_assert_text(v_lock->'workId','manager correction workId',160); perform public.static_weekly_v3_assert_uuid(v_lock->'slotId','manager correction slotId');
      if not public.static_weekly_exception_work_exists(p_base_version_id,p_service_date,v_lock->>'workId') or not public.static_weekly_exception_slot_exists(p_base_version_id,p_service_date,v_lock->>'slotId',true) then raise exception using errcode='23514',message='rebalance and correction locks must target current weekday work and working slots'; end if;
    end loop;
    if (select count(*) from jsonb_array_elements(p_payload->'locks'))<>(select count(distinct value->>'workId') from jsonb_array_elements(p_payload->'locks')) or exists(select 1 from public.weekly_schedule_exception_commands e cross join lateral jsonb_array_elements(coalesce(e.payload_json->'locks','[]'::jsonb)) l(value) where e.publication_id=p_publication_id and e.service_date=p_service_date and e.exception_type in ('nine_forty_five_rebalance','manager_correction') and not exists(select 1 from public.weekly_schedule_exception_commands r where r.reverses_exception_id=e.exception_id) and l.value->>'workId' in (select value->>'workId' from jsonb_array_elements(p_payload->'locks'))) then raise exception using errcode='23514',message='rebalance and correction locks may not duplicate or contradict effective commands'; end if;
  elsif p_exception_type='event_impact' then
    perform public.static_weekly_assert_exact_object(p_payload,array['removeWorkIds','patchWork','addWork'],array['removeWorkIds','patchWork','addWork'],'event impact payload');
    if p_starts_at is not null or p_ends_at is not null or jsonb_typeof(p_payload->'removeWorkIds') is distinct from 'array' or jsonb_typeof(p_payload->'patchWork') is distinct from 'array' or jsonb_typeof(p_payload->'addWork') is distinct from 'array' or jsonb_array_length(p_payload->'removeWorkIds')+jsonb_array_length(p_payload->'patchWork')+jsonb_array_length(p_payload->'addWork')=0 then raise exception using errcode='23514',message='event impact requires nonempty exact command arrays without a window'; end if;
    perform public.static_weekly_v3_assert_string_array(p_payload->'removeWorkIds','event removal targets',true,160);
    if exists(select 1 from jsonb_array_elements(p_payload->'removeWorkIds') x(value) where not public.static_weekly_exception_work_exists(p_base_version_id,p_service_date,x.value#>>'{}')) then raise exception using errcode='23514',message='event removal must target work on the exception service weekday'; end if;
    for v_patch in select value from jsonb_array_elements(p_payload->'patchWork') loop perform public.static_weekly_v3_assert_work_payload(v_patch,false); if not public.static_weekly_exception_work_exists(p_base_version_id,p_service_date,v_patch->>'workId') then raise exception using errcode='23514',message='event patch must target work on the exception service weekday'; end if; end loop;
    for v_add in select value from jsonb_array_elements(p_payload->'addWork') loop perform public.static_weekly_v3_assert_work_payload(v_add,true); if (v_add->>'dayOfWeek')::integer<>extract(dow from p_service_date)::integer or exists(select 1 from public.weekly_schedule_slot_assignments a where a.version_id=p_base_version_id and a.day_of_week=extract(dow from p_service_date)::smallint and a.work_id=v_add->>'workId') or not public.static_weekly_exception_slot_exists(p_base_version_id,p_service_date,v_add->>'originSlotId',false) then raise exception using errcode='23514',message='event addition must be a new work identity for the service weekday and an extant origin slot'; end if; end loop;
    select array_agg(value#>>'{}') into v_ids from jsonb_array_elements(p_payload->'removeWorkIds');
    if exists(select 1 from jsonb_array_elements(p_payload->'patchWork') x(value) where x.value->>'workId'=any(coalesce(v_ids,array[]::text[]))) or exists(select 1 from jsonb_array_elements(p_payload->'addWork') x(value) where x.value->>'workId'=any(coalesce(v_ids,array[]::text[]))) or (select count(*) from jsonb_array_elements(p_payload->'patchWork'))<>(select count(distinct value->>'workId') from jsonb_array_elements(p_payload->'patchWork')) or (select count(*) from jsonb_array_elements(p_payload->'addWork'))<>(select count(distinct value->>'workId') from jsonb_array_elements(p_payload->'addWork')) then raise exception using errcode='23514',message='event targets must be unique and may not remove, patch, and add the same work'; end if;
  elsif p_exception_type='reverse' then
    perform public.static_weekly_assert_exact_object(p_payload,array['reversesExceptionId'],array['reversesExceptionId'],'reverse payload'); perform public.static_weekly_v3_assert_uuid(p_payload->'reversesExceptionId','reverse target');
    if p_starts_at is not null or p_ends_at is not null or p_reverses_exception_id is distinct from (p_payload->>'reversesExceptionId')::uuid then raise exception using errcode='23514',message='reversal requires one coherent UUID target without a window'; end if;
  else raise exception using errcode='23514',message='unsupported exception operation';
  end if;
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_assert_projection_envelope(p_envelope jsonb, p_publication_id uuid, p_week_start date, p_exception_set jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_authority jsonb:=p_envelope->'authority'; v_base jsonb; v_compiler_exceptions jsonb; v_publication public.weekly_schedule_publications%rowtype;
begin
  perform public.static_weekly_assert_exact_object(p_envelope,array['adapter','service_date','week_start','week_end','authority','receipt','authority_digest','replay_digest','compiler_version','objective','metrics','applied_exceptions','assignments','database_projection_identity'],array['adapter','service_date','week_start','week_end','authority','receipt','authority_digest','replay_digest','compiler_version','objective','metrics','applied_exceptions','assignments','database_projection_identity'],'projection envelope');
  perform public.static_weekly_assert_exact_object(p_envelope->'adapter',array['schema','version'],array['schema','version'],'projection envelope adapter');
  if jsonb_typeof(p_exception_set) is distinct from 'array' or jsonb_typeof(p_envelope->'service_date') is distinct from 'string'
    or jsonb_typeof(p_envelope->'week_start') is distinct from 'string' or jsonb_typeof(p_envelope->'week_end') is distinct from 'string'
    or jsonb_typeof(p_envelope->'authority_digest') is distinct from 'string' or jsonb_typeof(p_envelope->'replay_digest') is distinct from 'string'
    or jsonb_typeof(p_envelope->'compiler_version') is distinct from 'string' or jsonb_typeof(p_envelope->'objective') is distinct from 'object'
    or jsonb_typeof(p_envelope->'metrics') is distinct from 'object' or jsonb_typeof(p_envelope->'applied_exceptions') is distinct from 'array'
    or jsonb_typeof(p_envelope->'assignments') is distinct from 'array' or jsonb_typeof(p_envelope->'database_projection_identity') is distinct from 'string' then
    raise exception using errcode='23514',message='projection envelope requires complete typed authority, receipt, identity, and assignment fields';
  end if;
  if jsonb_array_length(p_envelope->'assignments')=0 then raise exception using errcode='23514',message='projection assignments may not be empty'; end if;
  if exists(select 1 from jsonb_array_elements(p_envelope->'assignments') as a(x) where jsonb_typeof(a.x) is distinct from 'object') then raise exception using errcode='23514',message='projection assignment rows must be JSON objects'; end if;
  if exists(select 1 from jsonb_array_elements(p_envelope->'assignments') as a(x) where not (a.x ?& array['plan_work_id','work_id','day_of_week','service_date','status','work_snapshot','explanation'])) then raise exception using errcode='23514',message='projection assignments require every identity, status, snapshot, and explanation key'; end if;
  if exists(select 1 from jsonb_array_elements(p_envelope->'assignments') as a(x)
      where jsonb_typeof(a.x->'plan_work_id') is distinct from 'string' or nullif(btrim(a.x->>'plan_work_id'),'') is null
        or jsonb_typeof(a.x->'work_id') is distinct from 'string' or nullif(btrim(a.x->>'work_id'),'') is null) then
    raise exception using errcode='23514',message='projection assignments require nonblank string plan_work_id and work_id values';
  end if;
  if exists(select 1 from jsonb_array_elements(p_envelope->'assignments') as a(x)
      where jsonb_typeof(a.x->'day_of_week') is distinct from 'number' or (a.x->>'day_of_week') !~ '^[0-6]$') then
    raise exception using errcode='23514',message='projection assignments require integer day_of_week values from 0 through 6';
  end if;
  -- Keep the input probe and cast in one CASE branch: malformed JSON strings
  -- never reach a date cast.  The explicit [0-9] form avoids the prior
  -- doubly-escaped \\d regex, which rejected valid canonical dates.
  if exists(select 1 from jsonb_array_elements(p_envelope->'assignments') as a(x)
      where jsonb_typeof(a.x->'service_date') is distinct from 'string' or nullif(btrim(a.x->>'service_date'),'') is null
        or (a.x->>'service_date') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
        or not pg_input_is_valid(a.x->>'service_date','date')
        or case when jsonb_typeof(a.x->'service_date')='string'
                       and (a.x->>'service_date') ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
                       and pg_input_is_valid(a.x->>'service_date','date')
                then (a.x->>'service_date')::date::text is distinct from a.x->>'service_date'
                  or (a.x->>'service_date')::date<p_week_start
                  or (a.x->>'service_date')::date>p_week_start+6
                else false end) then
    raise exception using errcode='23514',message='projection assignments require canonical valid seven-day service_date values';
  end if;
  if exists(select 1 from jsonb_array_elements(p_envelope->'assignments') as a(x) where jsonb_typeof(a.x->'explanation') is distinct from 'object') then
    raise exception using errcode='23514',message='projection assignments require object explanation facts';
  end if;
  if exists(select 1 from jsonb_array_elements(p_envelope->'assignments') as a(x)
      where jsonb_typeof(a.x->'status') is distinct from 'string' or upper(a.x->>'status') not in ('ASSIGNED','OPEN','REVIEW')) then
    raise exception using errcode='23514',message='projection assignments require an explicit ASSIGNED, OPEN, or REVIEW status';
  end if;
  if (select count(*) from jsonb_array_elements(p_envelope->'assignments'))<>(select count(distinct x->>'plan_work_id') from jsonb_array_elements(p_envelope->'assignments') as a(x)) then
    raise exception using errcode='23514',message='projection assignments may not contain duplicate work identities';
  end if;
  select * into v_publication from public.weekly_schedule_publications where publication_id=p_publication_id;
  if not found then raise exception using errcode='23514',message='projection publication is unknown'; end if;
  select draft_document->'authority' into v_base from public.weekly_schedule_versions where version_id=v_publication.version_id;
  v_compiler_exceptions:=public.static_weekly_compiler_exception_set(p_publication_id,p_week_start);
  perform public.static_weekly_assert_compiler_authority(v_authority,p_envelope->'receipt',p_week_start,false);
  if p_envelope #>> '{adapter,schema}' is distinct from 'memphis-zoo.static-weekly-database-adapter.v1' or p_envelope #>> '{adapter,version}' is distinct from 'static-weekly-database-adapter-v1' or p_envelope->>'service_date' is distinct from p_week_start::text or p_envelope->>'week_start' is distinct from p_week_start::text or p_envelope->>'week_end' is distinct from (p_week_start+6)::text
    or p_envelope->>'authority_digest' is distinct from public.static_weekly_digest_jsonb(v_authority) or p_envelope->>'replay_digest' is distinct from p_envelope #>>'{receipt,compiler,replayDigest}'
    or p_envelope->>'compiler_version' is distinct from v_authority #>>'{optimizerResult,compilerVersion}' or p_envelope->'objective' is distinct from v_authority #> '{optimizerResult,objective}' or p_envelope->'metrics' is distinct from v_authority #> '{optimizerResult,metrics}'
    or p_envelope->>'database_projection_identity' is distinct from public.static_weekly_digest_jsonb(p_envelope-'database_projection_identity')
    or v_authority->'compilerInput' is distinct from v_base->'compilerInput' or v_authority->>'baselineInputDigest' is distinct from v_base->>'baselineInputDigest' or v_authority->>'weeklyVersionDigest' is distinct from v_base->>'weeklyVersionDigest' then
    raise exception using errcode='23514',message='projection must bind the stored baseline, complete receipt, objective, metrics, replay, and full weekly envelope';
  end if;
  if v_authority->'appliedExceptions' is distinct from p_exception_set
    or p_envelope->'applied_exceptions' is distinct from p_exception_set then raise exception using errcode='23514',message='overlay compiler input and applied exceptions must bind the complete accepted seven-day exception set'; end if;
  if v_authority #> '{overlayCompilerInput,exceptions}' is distinct from v_compiler_exceptions then raise exception using errcode='23514',message='overlay compiler input must carry every semantic accepted exception fact for the same seven-day horizon'; end if;
  if exists(
    with optimizer as(select value x from jsonb_array_elements(v_authority #> '{optimizerResult,assignments}')),
    projected as(select value x from jsonb_array_elements(p_envelope->'assignments'))
    select 1 from optimizer o full join projected p on p.x->>'plan_work_id'=o.x->>'planWorkId'
    where o.x is null or p.x is null or p.x->>'service_date' is distinct from o.x->>'serviceDate' or p.x->>'work_id' is distinct from o.x->>'workId' or p.x->>'day_of_week' is distinct from o.x->>'dayOfWeek' or upper(p.x->>'status') is distinct from upper(o.x->>'status')
      or (o.x->>'status'='ASSIGNED' and (p.x->>'owner_slot_id' is distinct from o.x->>'slotId' or p.x->>'owner_person_id' is distinct from o.x->>'personId'))
      or (o.x->>'status' in ('OPEN','REVIEW') and (p.x->>'owner_slot_id' is not null or p.x->>'owner_person_id' is not null))
  ) then raise exception using errcode='23514',message='complete weekly projection assignments must exactly bind the canonical optimizer'; end if;
  if exists(
    with optimizer as(select value x from jsonb_array_elements(v_authority #> '{optimizerResult,assignments}')),
    projected as(select value x from jsonb_array_elements(p_envelope->'assignments'))
    select 1 from optimizer o join projected p on p.x->>'plan_work_id'=o.x->>'planWorkId'
    where jsonb_typeof(p.x->'work_snapshot') is distinct from 'object'
      or not (p.x->'work_snapshot' ?& array['workId','dayOfWeek','originSlotId','locationId','locationCodeSnapshot','locationNameSnapshot','window','serviceEffortMinutes','serviceEffortProvenance','priority','priorityProvenance','required','coveragePolicy','bestEffortCoverage','coveragePolicyOrder','coveragePolicyProvenance','requiredQualifications','qualificationProvenance','restrictions','restrictionProvenance','restrictedSlotIds','manualLock','manualLockSlotId','overlayWork'])
      or exists(select 1 from jsonb_object_keys(p.x->'work_snapshot') as k(key) where not (k.key=any(array['workId','dayOfWeek','originSlotId','locationId','locationCodeSnapshot','locationNameSnapshot','window','serviceEffortMinutes','serviceEffortProvenance','priority','priorityProvenance','required','coveragePolicy','bestEffortCoverage','coveragePolicyOrder','coveragePolicyProvenance','requiredQualifications','qualificationProvenance','restrictions','restrictionProvenance','restrictedSlotIds','manualLock','manualLockSlotId','overlayWork'])))
      or jsonb_typeof(p.x#>'{work_snapshot,workId}') is distinct from 'string'
      or jsonb_typeof(p.x#>'{work_snapshot,dayOfWeek}') is distinct from 'number'
      or jsonb_typeof(p.x#>'{work_snapshot,originSlotId}') not in ('string','null')
      or p.x#>>'{work_snapshot,workId}' is distinct from o.x->>'workId'
      or p.x#>>'{work_snapshot,dayOfWeek}' is distinct from o.x->>'dayOfWeek'
      or p.x#>>'{work_snapshot,window,start}' is distinct from o.x#>>'{window,start}'
      or p.x#>>'{work_snapshot,window,end}' is distinct from o.x#>>'{window,end}'
      or p.x#>>'{work_snapshot,serviceEffortMinutes}' is distinct from o.x->>'serviceEffortMinutes'
      or jsonb_typeof(p.x#>'{work_snapshot,locationId}') is distinct from 'string'
      or p.x#>>'{work_snapshot,locationId}' !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
      or jsonb_typeof(p.x#>'{work_snapshot,locationCodeSnapshot}') is distinct from 'string' or nullif(btrim(p.x#>>'{work_snapshot,locationCodeSnapshot}'),'') is null
      or jsonb_typeof(p.x#>'{work_snapshot,locationNameSnapshot}') is distinct from 'string' or nullif(btrim(p.x#>>'{work_snapshot,locationNameSnapshot}'),'') is null
      or jsonb_typeof(p.x#>'{work_snapshot,window}') is distinct from 'object'
      or jsonb_typeof(p.x#>'{work_snapshot,window,start}') is distinct from 'string' or nullif(btrim(p.x#>>'{work_snapshot,window,start}'),'') is null
      or jsonb_typeof(p.x#>'{work_snapshot,window,end}') is distinct from 'string' or nullif(btrim(p.x#>>'{work_snapshot,window,end}'),'') is null
      or jsonb_typeof(p.x#>'{work_snapshot,serviceEffortMinutes}') is distinct from 'number'
      or jsonb_typeof(p.x#>'{work_snapshot,serviceEffortProvenance}') is distinct from 'string' or nullif(btrim(p.x#>>'{work_snapshot,serviceEffortProvenance}'),'') is null
      or jsonb_typeof(p.x#>'{work_snapshot,priority}') is distinct from 'number'
      or jsonb_typeof(p.x#>'{work_snapshot,priorityProvenance}') not in ('string','null')
      or (jsonb_typeof(p.x#>'{work_snapshot,priorityProvenance}')='string' and nullif(btrim(p.x#>>'{work_snapshot,priorityProvenance}'),'') is null)
      or jsonb_typeof(p.x#>'{work_snapshot,required}') is distinct from 'boolean'
      or jsonb_typeof(p.x#>'{work_snapshot,coveragePolicy}') not in ('string','null')
      or jsonb_typeof(p.x#>'{work_snapshot,bestEffortCoverage}') is distinct from 'boolean'
      or jsonb_typeof(p.x#>'{work_snapshot,coveragePolicyOrder}') not in ('number','null')
      or jsonb_typeof(p.x#>'{work_snapshot,coveragePolicyProvenance}') not in ('string','null')
      or jsonb_typeof(p.x#>'{work_snapshot,requiredQualifications}') is distinct from 'array'
      or jsonb_typeof(p.x#>'{work_snapshot,qualificationProvenance}') is distinct from 'string' or nullif(btrim(p.x#>>'{work_snapshot,qualificationProvenance}'),'') is null
      or jsonb_typeof(p.x#>'{work_snapshot,restrictions}') is distinct from 'array'
      or jsonb_typeof(p.x#>'{work_snapshot,restrictionProvenance}') is distinct from 'string' or nullif(btrim(p.x#>>'{work_snapshot,restrictionProvenance}'),'') is null
      or jsonb_typeof(p.x#>'{work_snapshot,restrictedSlotIds}') is distinct from 'array'
      or jsonb_typeof(p.x#>'{work_snapshot,manualLock}') is distinct from 'boolean'
      or jsonb_typeof(p.x#>'{work_snapshot,manualLockSlotId}') not in ('string','null')
      or jsonb_typeof(p.x#>'{work_snapshot,overlayWork}') is distinct from 'boolean'
      or exists(select 1 from jsonb_array_elements(p.x#>'{work_snapshot,requiredQualifications}') as q(value) where jsonb_typeof(q.value) is distinct from 'string' or nullif(btrim(q.value#>>'{}'),'') is null)
      or exists(select 1 from jsonb_array_elements(p.x#>'{work_snapshot,restrictions}') as r(value) where jsonb_typeof(r.value) is distinct from 'string' or nullif(btrim(r.value#>>'{}'),'') is null)
      or exists(select 1 from jsonb_array_elements(p.x#>'{work_snapshot,restrictedSlotIds}') as r(value) where jsonb_typeof(r.value) is distinct from 'string' or nullif(btrim(r.value#>>'{}'),'') is null)
      or (select count(*) from jsonb_array_elements(p.x#>'{work_snapshot,requiredQualifications}'))<>(select count(distinct value#>>'{}') from jsonb_array_elements(p.x#>'{work_snapshot,requiredQualifications}'))
      or (select count(*) from jsonb_array_elements(p.x#>'{work_snapshot,restrictions}'))<>(select count(distinct value#>>'{}') from jsonb_array_elements(p.x#>'{work_snapshot,restrictions}'))
      or (select count(*) from jsonb_array_elements(p.x#>'{work_snapshot,restrictedSlotIds}'))<>(select count(distinct value#>>'{}') from jsonb_array_elements(p.x#>'{work_snapshot,restrictedSlotIds}'))
  ) then raise exception using errcode='23514',message='projection work snapshots must be complete semantic authority facts bound to the canonical optimizer'; end if;
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_assert_projection_envelope_attested(p_envelope jsonb, p_publication_id uuid, p_week_start date, p_exception_set jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_legacy jsonb; v_snapshot jsonb; v_document jsonb;
begin
  perform public.static_weekly_assert_exact_object(p_envelope,array['adapter','service_date','week_start','week_end','authority','receipt','authority_digest','replay_digest','compiler_version','objective','metrics','applied_exceptions','assignments','database_projection_identity','semantic_snapshot','attestation'],array['adapter','service_date','week_start','week_end','authority','receipt','authority_digest','replay_digest','compiler_version','objective','metrics','applied_exceptions','assignments','database_projection_identity','semantic_snapshot','attestation'],'attested projection envelope');
  perform public.static_weekly_assert_authority_attestation(p_envelope->'attestation','dated_projection',public.static_weekly_projection_attestation_payload(p_envelope));
  if p_envelope->>'database_projection_identity' is distinct from public.static_weekly_digest_jsonb((p_envelope-'attestation')-'database_projection_identity') then raise exception using errcode='23514',message='projection semantic identity must bind the complete attested envelope'; end if;
  v_snapshot:=p_envelope->'semantic_snapshot'; perform public.static_weekly_assert_exact_object(v_snapshot,array['schema','recurring_source','overlay_source','applied_exceptions','active_assignments'],array['schema','recurring_source','overlay_source','applied_exceptions','active_assignments'],'projection semantic snapshot');
  select draft_document into v_document from public.weekly_schedule_versions v join public.weekly_schedule_publications p on p.version_id=v.version_id where p.publication_id=p_publication_id;
  if v_snapshot->>'schema' is distinct from 'memphis-zoo.static-weekly-projection-semantic-snapshot.v1'
    or v_snapshot->'recurring_source' is distinct from public.static_weekly_v5_projection_source_identity(p_envelope#>'{authority,compilerInput}')
    or v_snapshot->'recurring_source' is distinct from public.static_weekly_v5_projection_source_identity(v_document#>'{semantic_snapshot,recurring_source}')
    or v_snapshot->'overlay_source' is distinct from public.static_weekly_v5_projection_source_identity(p_envelope#>'{authority,overlayCompilerInput}')
    or v_snapshot->'applied_exceptions' is distinct from p_envelope->'applied_exceptions' or v_snapshot->'active_assignments' is distinct from p_envelope->'assignments' then
    raise exception using errcode='23514',message='projection must bind stable recurring source, dated staffing and exceptions, and active assignments';
  end if;
  v_legacy:=p_envelope-'semantic_snapshot'-'attestation'; v_legacy:=jsonb_set(v_legacy,'{database_projection_identity}',to_jsonb(public.static_weekly_digest_jsonb(v_legacy-'database_projection_identity')),true);
  perform public.static_weekly_v4_assert_projection_envelope(v_legacy,p_publication_id,p_week_start,p_exception_set);
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_authority_hmac(p_scope text, p_payload jsonb)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_secret text; v_enabled boolean; v_schema text; v_hmac text;
begin
  select hmac_secret,enabled into v_secret,v_enabled from public.static_weekly_authority_attestation_config where singleton=true;
  if v_enabled is not true or length(coalesce(v_secret,''))<32 then
    raise exception using errcode='42501',message='static weekly authority attestation boundary is not configured';
  end if;
  select n.nspname into v_schema from pg_extension e join pg_namespace n on n.oid=e.extnamespace where e.extname='pgcrypto';
  if v_schema not in ('extensions','public') then raise exception using errcode='55000',message='pgcrypto must be installed in extensions or public'; end if;
  execute format('select encode(%I.hmac(convert_to($1,''UTF8''),convert_to($2,''UTF8''),''sha256''),''hex'')',v_schema)
    into v_hmac using p_scope||E'\n'||p_payload::text,v_secret;
  return v_hmac;
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_component_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_state text;
begin
  select lifecycle_state into v_state from public.weekly_schedule_versions where version_id=coalesce(new.version_id,old.version_id);
  if current_setting('app.static_weekly_draft_write',true)='on' and v_state='draft' then
    if tg_op='DELETE' then return old; end if; return new;
  end if;
  if current_setting('app.static_weekly_publish_write',true)='on' and v_state='published' and tg_op='INSERT' then return new; end if;
  raise exception using errcode='23514',message='scheduler components may change only through a revision-checked v2 command';
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_digest_text(p_value text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE STRICT SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_schema text; v_digest text;
begin
  select n.nspname into v_schema
  from pg_extension e join pg_namespace n on n.oid=e.extnamespace
  where e.extname='pgcrypto';
  if v_schema not in ('extensions','public') then
    raise exception using errcode='55000', message='pgcrypto must be installed in extensions or public';
  end if;
  execute format('select encode(%I.digest(convert_to($1,''UTF8''),''sha256''),''hex'')',v_schema) into v_digest using p_value;
  return v_digest;
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_materialize_document(p_version_id uuid, p_document jsonb, p_content_digest text, p_actor_manager_id uuid, p_actor_manager_name text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
  perform set_config('app.static_weekly_draft_write','on',true);
  delete from public.weekly_schedule_slot_assignments where version_id=p_version_id;
  delete from public.weekly_schedule_slot_availability where version_id=p_version_id;
  delete from public.weekly_schedule_objective_inputs where version_id=p_version_id;
  insert into public.weekly_schedule_slot_availability(version_id,slot_id,day_of_week,availability_state,shift_start,shift_end,lunch_start,lunch_end,capacity_units,max_load_points,qualification_snapshot,qualification_provenance,restriction_snapshot,restriction_provenance,slot_label_snapshot,incumbent_person_id_snapshot,incumbent_name_snapshot,content_digest)
  select p_version_id,x.slot_id,x.day_of_week,x.availability_state,x.shift_start,x.shift_end,x.lunch_start,x.lunch_end,x.capacity_units,x.max_load_points,x.qualification_snapshot,x.qualification_provenance,x.restriction_snapshot,x.restriction_provenance,x.slot_label_snapshot,x.incumbent_person_id_snapshot,x.incumbent_name_snapshot,p_content_digest
  from jsonb_to_recordset(p_document->'slot_availability') x(slot_id uuid,day_of_week smallint,availability_state text,shift_start time,shift_end time,lunch_start time,lunch_end time,capacity_units numeric,max_load_points numeric,qualification_snapshot jsonb,qualification_provenance jsonb,restriction_snapshot jsonb,restriction_provenance jsonb,slot_label_snapshot text,incumbent_person_id_snapshot uuid,incumbent_name_snapshot text);
  insert into public.weekly_schedule_slot_assignments(version_id,work_id,day_of_week,status,location_id,location_code_snapshot,location_name_snapshot,coverage_start,coverage_end,owner_slot_id,owner_slot_label_snapshot,owner_person_id_snapshot,owner_name_snapshot,required_qualifications_snapshot,restriction_snapshot,workload_points,workload_provenance,manual_lock,payload_json,authority_facts_json,content_digest)
  select p_version_id,x.work_id,x.day_of_week,lower(x.status),x.location_id,x.location_code_snapshot,x.location_name_snapshot,x.coverage_start,x.coverage_end,x.owner_slot_id,x.owner_slot_label_snapshot,x.owner_person_id_snapshot,x.owner_name_snapshot,x.required_qualifications_snapshot,x.restriction_snapshot,x.workload_points,x.workload_provenance,x.manual_lock,x.payload_json,x.payload_json->'authority_facts',p_content_digest
  from jsonb_to_recordset(p_document->'assignments') x(work_id text,day_of_week smallint,status text,location_id uuid,location_code_snapshot text,location_name_snapshot text,coverage_start time,coverage_end time,owner_slot_id uuid,owner_slot_label_snapshot text,owner_person_id_snapshot uuid,owner_name_snapshot text,required_qualifications_snapshot jsonb,restriction_snapshot jsonb,workload_points numeric,workload_provenance jsonb,manual_lock boolean,payload_json jsonb);
  insert into public.weekly_schedule_objective_inputs(version_id,input_key,input_value,provenance,content_digest,captured_by_manager_id,captured_by_manager_name_snapshot)
  select p_version_id,x.input_key,x.input_value,x.provenance,p_content_digest,p_actor_manager_id,p_actor_manager_name
  from jsonb_to_recordset(p_document->'objective_inputs') x(input_key text,input_value jsonb,provenance jsonb);
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v2_apply_exception(p_exception_type text, p_service_date date, p_starts_at time without time zone, p_ends_at time without time zone, p_base_version_id uuid, p_publication_id uuid, p_reason text, p_payload jsonb, p_expected_revision bigint, p_actor_manager_id uuid, p_actor_manager_name text, p_idempotency_key text, p_reverses_exception_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_request jsonb; v_request_digest text; v_prior public.weekly_schedule_command_receipts%rowtype; v_command uuid:=gen_random_uuid(); v_exception uuid:=gen_random_uuid(); v_payload jsonb:=coalesce(p_payload,'{}'::jsonb); v_payload_digest text; v_revision bigint; v_response jsonb; v_target public.weekly_schedule_exception_commands%rowtype; v_operation text;
begin
  perform public.static_weekly_assert_command_identity(p_expected_revision,p_actor_manager_id,p_actor_manager_name,p_idempotency_key,'apply_exception');
  v_request:=jsonb_build_object('operation','apply_exception','exception_type',p_exception_type,'service_date',p_service_date,'starts_at',p_starts_at,'ends_at',p_ends_at,'base_version_id',p_base_version_id,'publication_id',p_publication_id,'reason',p_reason,'payload',v_payload,'expected_revision',p_expected_revision,'actor_manager_id',p_actor_manager_id,'actor_manager_name',p_actor_manager_name,'reverses_exception_id',p_reverses_exception_id); v_request_digest:=public.static_weekly_digest_jsonb(v_request); perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
  select * into v_prior from public.weekly_schedule_command_receipts where actor_manager_id=p_actor_manager_id and idempotency_key=p_idempotency_key; if found then if v_prior.request_digest<>v_request_digest then raise exception using errcode='23505',message='idempotency key was already used for different semantic inputs'; end if; return v_prior.response_json; end if;
  if p_exception_type is null or p_exception_type not in ('pto','daily_absence','partial_absence','shift_override','cover_all','lunch','nine_forty_five_rebalance','event_impact','manager_correction','reverse') or p_service_date is null or p_base_version_id is null or p_publication_id is null or btrim(coalesce(p_reason,''))='' or jsonb_typeof(p_payload) is distinct from 'object' or ((p_starts_at is null)<>(p_ends_at is null)) or (p_starts_at is not null and p_starts_at>=p_ends_at) then raise exception using errcode='23514',message='complete exception semantic inputs are required'; end if;
  if not exists(select 1 from public.weekly_schedule_publications where publication_id=p_publication_id and version_id=p_base_version_id) or public.static_weekly_effective_version(p_service_date) is distinct from p_base_version_id then raise exception using errcode='23514',message='exception must bind its effective publication and version'; end if;
  if (p_exception_type='reverse') is distinct from (p_reverses_exception_id is not null) then raise exception using errcode='23514',message='reversal target coherence is required'; end if;
  perform public.static_weekly_assert_exception_payload(p_exception_type,p_service_date,p_starts_at,p_ends_at,p_base_version_id,p_publication_id,v_payload,p_reverses_exception_id);
  if p_exception_type='reverse' then select * into v_target from public.weekly_schedule_exception_commands where exception_id=p_reverses_exception_id; if not found or v_target.exception_type='reverse' or v_target.service_date is distinct from p_service_date or v_target.base_version_id is distinct from p_base_version_id or v_target.publication_id is distinct from p_publication_id or exists(select 1 from public.weekly_schedule_exception_commands where reverses_exception_id=p_reverses_exception_id) then raise exception using errcode='23514',message='reversal must target one compatible unreversed exception'; end if; end if;
  v_payload_digest:=public.static_weekly_digest_jsonb(v_payload); v_operation:=case when p_exception_type='reverse' then 'reverse_exception' else 'apply_exception' end; v_revision:=public.static_weekly_advance_authority(p_expected_revision,v_operation,p_actor_manager_id,p_actor_manager_name,v_command,v_payload_digest);
  insert into public.weekly_schedule_exception_commands(exception_id,authority_revision,exception_type,service_date,starts_at,ends_at,base_version_id,publication_id,reverses_exception_id,expected_revision,idempotency_key,actor_manager_id,actor_manager_name_snapshot,reason,payload_json,payload_digest) values(v_exception,v_revision,p_exception_type,p_service_date,p_starts_at,p_ends_at,p_base_version_id,p_publication_id,p_reverses_exception_id,p_expected_revision,p_idempotency_key,p_actor_manager_id,p_actor_manager_name,p_reason,v_payload,v_payload_digest);
  v_response:=public.static_weekly_response_json(v_operation,v_revision,v_payload_digest,v_request_digest,jsonb_build_object('exception_id',v_exception,'exception_type',p_exception_type,'service_date',p_service_date,'payload_digest',v_payload_digest,'sequence',v_revision)); insert into public.weekly_schedule_command_receipts(command_id,actor_manager_id,actor_manager_name_snapshot,command_type,idempotency_key,expected_revision,request_digest,request_canonical_json,response_json,response_digest,content_digest) values(v_command,p_actor_manager_id,p_actor_manager_name,v_operation,p_idempotency_key,p_expected_revision,v_request_digest,v_request,v_response,v_response->>'output_digest',v_payload_digest); return v_response;
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v2_create_draft(p_effective_start date, p_objective_version text, p_objective jsonb, p_input_provenance jsonb, p_document jsonb, p_expected_revision bigint, p_actor_manager_id uuid, p_actor_manager_name text, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_request jsonb; v_request_digest text; v_prior public.weekly_schedule_command_receipts%rowtype; v_command uuid:=gen_random_uuid(); v_version uuid; v_content_digest text; v_revision bigint; v_response jsonb;
begin
  perform public.static_weekly_assert_command_identity(p_expected_revision,p_actor_manager_id,p_actor_manager_name,p_idempotency_key,'create_draft');
  v_request:=jsonb_build_object('operation','create_draft','effective_start',p_effective_start,'objective_version',p_objective_version,'objective',p_objective,'input_provenance',p_input_provenance,'document',p_document,'expected_revision',p_expected_revision,'actor_manager_id',p_actor_manager_id,'actor_manager_name',p_actor_manager_name);
  v_request_digest:=public.static_weekly_digest_jsonb(v_request); perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
  select * into v_prior from public.weekly_schedule_command_receipts where actor_manager_id=p_actor_manager_id and idempotency_key=p_idempotency_key;
  if found then if v_prior.request_digest<>v_request_digest then raise exception using errcode='23505',message='idempotency key was already used for different semantic inputs'; end if; return v_prior.response_json; end if;
  if p_effective_start is null or btrim(coalesce(p_objective_version,''))='' then raise exception using errcode='23514',message='complete draft command identity is required'; end if;
  perform public.static_weekly_assert_document_attested(p_document,p_effective_start,true);
  perform public.static_weekly_assert_exact_object(p_input_provenance,array['adapter_schema','compiler_version','input_digest','baseline_input_digest','authority_digest','replay_digest'],array['adapter_schema','compiler_version','input_digest','baseline_input_digest','authority_digest','replay_digest'],'draft input provenance');
  if jsonb_typeof(p_objective) is distinct from 'object' or exists(select 1 from jsonb_object_keys(p_input_provenance) k(key) where jsonb_typeof(p_input_provenance->k.key) is distinct from 'string') or p_objective is distinct from p_document#>'{authority,optimizerResult,objective}' or p_objective_version is distinct from p_document#>>'{validation,compiler_version}' or p_input_provenance->>'adapter_schema' is distinct from 'memphis-zoo.static-weekly-database-adapter.v1' or p_input_provenance->>'compiler_version' is distinct from p_document#>>'{validation,compiler_version}' or p_input_provenance->>'input_digest' is distinct from p_document#>>'{validation,input_digest}' or p_input_provenance->>'baseline_input_digest' is distinct from p_document#>>'{authority,baselineInputDigest}' or p_input_provenance->>'authority_digest' is distinct from p_document#>>'{validation,authority_digest}' or p_input_provenance->>'replay_digest' is distinct from p_document#>>'{validation,replay_digest}' then raise exception using errcode='23514',message='draft command may use only attested adapter-derived objective and provenance'; end if;
