  select * into v_prior from public.weekly_schedule_command_receipts where actor_manager_id=p_actor_manager_id and idempotency_key=p_idempotency_key; if found then if v_prior.request_digest<>v_request_digest then raise exception using errcode='23505',message='idempotency key was already used for different semantic inputs'; end if; return v_prior.response_json; end if;
  if p_version_id is null or p_expected_draft_revision is null or p_expected_draft_revision<1 then raise exception using errcode='23514',message='complete update draft identity is required'; end if;
  select * into v_version from public.weekly_schedule_versions where version_id=p_version_id and lifecycle_state='draft' and revision=p_expected_draft_revision for update; if not found then raise exception using errcode='40001',message='stale draft revision'; end if;
  perform public.static_weekly_assert_document_attested(p_document,v_version.effective_start,true); perform public.static_weekly_assert_exact_object(p_input_provenance,array['adapter_schema','compiler_version','input_digest','baseline_input_digest','authority_digest','replay_digest'],array['adapter_schema','compiler_version','input_digest','baseline_input_digest','authority_digest','replay_digest'],'update input provenance');
  begin v_document_version_id:=(p_document#>>'{authority,compilerInput,version,id}')::uuid; exception when others then raise exception using errcode='23514',message='compiler weekly version identity must be a canonical UUID'; end;
  if v_document_version_id is distinct from p_version_id then raise exception using errcode='23514',message='update document compiler version identity must exactly match p_version_id'; end if;
  if jsonb_typeof(p_objective) is distinct from 'object' or exists(select 1 from jsonb_object_keys(p_input_provenance) k(key) where jsonb_typeof(p_input_provenance->k.key) is distinct from 'string') or p_objective is distinct from p_document#>'{authority,optimizerResult,objective}' or v_version.objective_version is distinct from p_document#>>'{validation,compiler_version}' or p_input_provenance->>'adapter_schema' is distinct from 'memphis-zoo.static-weekly-database-adapter.v1' or p_input_provenance->>'compiler_version' is distinct from p_document#>>'{validation,compiler_version}' or p_input_provenance->>'input_digest' is distinct from p_document#>>'{validation,input_digest}' or p_input_provenance->>'baseline_input_digest' is distinct from p_document#>>'{authority,baselineInputDigest}' or p_input_provenance->>'authority_digest' is distinct from p_document#>>'{validation,authority_digest}' or p_input_provenance->>'replay_digest' is distinct from p_document#>>'{validation,replay_digest}' then raise exception using errcode='23514',message='update may use only attested adapter-derived objective and provenance'; end if;
  v_content_digest:=public.static_weekly_digest_jsonb(jsonb_build_object('version_id',p_version_id,'document',p_document,'objective',p_objective,'input_provenance',p_input_provenance)); v_revision:=public.static_weekly_advance_authority(p_expected_revision,'update_draft',p_actor_manager_id,p_actor_manager_name,v_command,v_content_digest); perform set_config('app.static_weekly_draft_write','on',true); update public.weekly_schedule_versions set draft_document=p_document,objective_json=p_objective,input_provenance_json=p_input_provenance,content_digest=v_content_digest,revision=revision+1 where version_id=p_version_id; perform public.static_weekly_materialize_document(p_version_id,p_document,v_content_digest,p_actor_manager_id,p_actor_manager_name);
  v_response:=public.static_weekly_response_json('update_draft',v_revision,v_content_digest,v_request_digest,jsonb_build_object('version_id',p_version_id,'draft_revision',p_expected_draft_revision+1)); insert into public.weekly_schedule_command_receipts(command_id,actor_manager_id,actor_manager_name_snapshot,command_type,idempotency_key,expected_revision,request_digest,request_canonical_json,response_json,response_digest,content_digest) values(v_command,p_actor_manager_id,p_actor_manager_name,'update_draft',p_idempotency_key,p_expected_revision,v_request_digest,v_request,v_response,v_response->>'output_digest',v_content_digest); return v_response;
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v3_apply_exception(p_exception_type text, p_service_date date, p_starts_at time without time zone, p_ends_at time without time zone, p_base_version_id uuid, p_publication_id uuid, p_reason text, p_payload jsonb, p_expected_revision bigint, p_manager_id uuid, p_idempotency_key text, p_reverses_exception_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_actor jsonb;
begin
  perform public.static_weekly_v3_assert_control_plane();
  if nullif(btrim(coalesce(p_reason,'')),'') is null or char_length(p_reason)>500 or p_reason ~ '[\x00-\x1f\x7f]' then
    raise exception using errcode='23514',message='exception reason must be a nonblank control-free string of at most 500 characters';
  end if;
  v_actor:=public.static_weekly_v3_manager_actor(p_manager_id);
  return public.static_weekly_v2_apply_exception(p_exception_type,p_service_date,p_starts_at,p_ends_at,p_base_version_id,p_publication_id,p_reason,p_payload,p_expected_revision,p_manager_id,v_actor->>'manager_name',p_idempotency_key,p_reverses_exception_id);
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v3_assert_draft_incumbency(p_version_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_start date; v_row record; v_person uuid; v_name text; v_date date; v_matches integer;
begin
  select effective_start into v_start from public.weekly_schedule_versions where version_id=p_version_id for share;
  if v_start is null then raise exception using errcode='23514',message='draft version does not exist'; end if;
  for v_row in select * from public.weekly_schedule_slot_availability where version_id=p_version_id order by day_of_week,slot_id loop
    v_date:=v_start+mod(v_row.day_of_week-extract(dow from v_start)::integer+7,7);
    select count(*) into v_matches from public.v_weekly_roster_slot_incumbency_ranges where slot_id=v_row.slot_id and effective_start<=v_date and (effective_end is null or v_date<effective_end);
    if v_matches<>1 then raise exception using errcode='23514',message='draft roster slot must resolve exactly one closure-aware incumbent at each service date'; end if;
    select person_id,person_name_snapshot into v_person,v_name from public.v_weekly_roster_slot_incumbency_ranges where slot_id=v_row.slot_id and effective_start<=v_date and (effective_end is null or v_date<effective_end);
    if v_row.incumbent_person_id_snapshot is distinct from v_person or v_row.incumbent_name_snapshot is distinct from v_name then raise exception using errcode='23514',message='draft roster incumbency snapshot is stale or incomplete at publication service date'; end if;
  end loop;
  for v_row in select * from public.weekly_schedule_slot_assignments where version_id=p_version_id and owner_slot_id is not null order by day_of_week,assignment_id loop
    v_date:=v_start+mod(v_row.day_of_week-extract(dow from v_start)::integer+7,7);
    select count(*) into v_matches from public.v_weekly_roster_slot_incumbency_ranges where slot_id=v_row.owner_slot_id and effective_start<=v_date and (effective_end is null or v_date<effective_end);
    if v_matches<>1 then raise exception using errcode='23514',message='draft assignment owner must resolve exactly one closure-aware incumbent at each service date'; end if;
    select person_id,person_name_snapshot into v_person,v_name from public.v_weekly_roster_slot_incumbency_ranges where slot_id=v_row.owner_slot_id and effective_start<=v_date and (effective_end is null or v_date<effective_end);
    if v_row.owner_person_id_snapshot is distinct from v_person or v_row.owner_name_snapshot is distinct from v_name then raise exception using errcode='23514',message='draft recurring owner snapshot is stale or incomplete at publication service date'; end if;
  end loop;
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v3_assert_rollback_lineage(p_draft_version_id uuid, p_rollback_of_version_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_effective date; v_current uuid; v_target_kind text; v_is_ancestor boolean;
begin
  select effective_start into v_effective from public.weekly_schedule_versions where version_id=p_draft_version_id for share; select public.static_weekly_effective_version(v_effective) into v_current;
  if v_current is null or p_rollback_of_version_id is null or p_rollback_of_version_id=v_current then raise exception using errcode='23514',message='rollback must name one distinct current-lineage superseded ancestor'; end if;
  select publication_kind into v_target_kind from public.weekly_schedule_versions where version_id=p_rollback_of_version_id and lifecycle_state='published' for share;
  if v_target_kind is null or v_target_kind='rollback_compensation' then raise exception using errcode='23514',message='rollback targets must be published non-rollback ancestors'; end if;
  with recursive lineage(version_id,prior_version_id) as (
    select p.version_id,p.prior_version_id from public.weekly_schedule_publications p where p.version_id=v_current
    union all select p.version_id,p.prior_version_id from public.weekly_schedule_publications p join lineage l on p.version_id=l.prior_version_id
  ) select exists(select 1 from lineage where version_id=p_rollback_of_version_id) into v_is_ancestor;
  if not v_is_ancestor then raise exception using errcode='23514',message='rollback target is not an eligible superseded ancestor in the current immutable lineage'; end if;
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v3_assert_window(p_value jsonb, p_label text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_start time; v_end time;
begin
  perform public.static_weekly_assert_exact_object(p_value,array['start','end'],array['start','end'],p_label);
  perform public.static_weekly_v3_assert_text(p_value->'start',p_label||' start',5);
  perform public.static_weekly_v3_assert_text(p_value->'end',p_label||' end',5);
  if p_value->>'start' !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$' or p_value->>'end' !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$' then
    raise exception using errcode='23514',message=format('%s endpoints must be HH:MM local time',p_label);
  end if;
  v_start:=(p_value->>'start')::time; v_end:=(p_value->>'end')::time;
  if v_start>=v_end then raise exception using errcode='23514',message=format('%s must be an ordered nonempty local window',p_label); end if;
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v3_assert_work_payload(p_work jsonb, p_added boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_effort numeric; v_priority numeric;
begin
  perform public.static_weekly_assert_exact_object(p_work,
    case when p_added then array['workId','dayOfWeek','originSlotId','locationId','locationCodeSnapshot','locationNameSnapshot','window','serviceEffortMinutes','serviceEffortProvenance','priority','priorityProvenance','requiredQualifications','qualificationProvenance','restrictions','restrictionProvenance'] else array['workId','locationId','locationCodeSnapshot','locationNameSnapshot','window','serviceEffortMinutes','serviceEffortProvenance','priority','priorityProvenance','requiredQualifications','qualificationProvenance','restrictions','restrictionProvenance'] end,
    case when p_added then array['workId','dayOfWeek','originSlotId','locationId','locationCodeSnapshot','locationNameSnapshot','window','serviceEffortMinutes','serviceEffortProvenance','priority','priorityProvenance','requiredQualifications','qualificationProvenance','restrictions','restrictionProvenance'] else array['workId','locationId','locationCodeSnapshot','locationNameSnapshot','window','serviceEffortMinutes','serviceEffortProvenance','priority','priorityProvenance','requiredQualifications','qualificationProvenance','restrictions','restrictionProvenance'] end,
    case when p_added then 'event added work' else 'event patch work' end);
  perform public.static_weekly_v3_assert_text(p_work->'workId','event workId',160);
  perform public.static_weekly_v3_assert_uuid(p_work->'locationId','event locationId');
  perform public.static_weekly_v3_assert_text(p_work->'locationCodeSnapshot','event location code');
  perform public.static_weekly_v3_assert_text(p_work->'locationNameSnapshot','event location name');
  perform public.static_weekly_v3_assert_window(p_work->'window','event work window');
  if jsonb_typeof(p_work->'serviceEffortMinutes') is distinct from 'number' or jsonb_typeof(p_work->'priority') is distinct from 'number' then
    raise exception using errcode='23514',message='event work effort and priority must be JSON numbers';
  end if;
  v_effort:=(p_work->>'serviceEffortMinutes')::numeric; v_priority:=(p_work->>'priority')::numeric;
  if v_effort<>trunc(v_effort) or v_effort<1 or v_effort>1440 or v_priority<>trunc(v_priority) or v_priority<0 or v_priority>100 then
    raise exception using errcode='23514',message='event work effort or priority is outside the accepted integer range';
  end if;
  perform public.static_weekly_v3_assert_text(p_work->'serviceEffortProvenance','event service provenance');
  perform public.static_weekly_v3_assert_text(p_work->'priorityProvenance','event priority provenance');
  perform public.static_weekly_v3_assert_text(p_work->'qualificationProvenance','event qualification provenance');
  perform public.static_weekly_v3_assert_text(p_work->'restrictionProvenance','event restriction provenance');
  perform public.static_weekly_v3_assert_string_array(p_work->'requiredQualifications','event qualifications');
  perform public.static_weekly_v3_assert_string_array(p_work->'restrictions','event restrictions');
  if p_added then
    if jsonb_typeof(p_work->'dayOfWeek') is distinct from 'number' or (p_work->>'dayOfWeek') !~ '^[0-6]$' then raise exception using errcode='23514',message='event added work weekday must be a JSON integer from zero through six'; end if;
    perform public.static_weekly_v3_assert_uuid(p_work->'originSlotId','event origin slotId');
  end if;
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v3_authority_health()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_active integer; v_overlap_bad integer; v_cp boolean; v_v3 integer; v_key public.static_weekly_authority_attestation_keys%rowtype; v_probe jsonb; v_signature text; v_canary boolean:=false;
begin
  select count(*) into v_active from public.static_weekly_authority_attestation_keys where key_state='active' and activates_at<=statement_timestamp() and (verify_not_after is null or verify_not_after>statement_timestamp());
  select count(*) into v_overlap_bad from public.static_weekly_authority_attestation_keys where key_state='overlap' and (verify_not_after is null or verify_not_after<=statement_timestamp());
  select exists(select 1 from pg_roles where rolname='static_weekly_control_plane') into v_cp;
  select count(*) into v_v3 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname like 'static_weekly_v3_%';
  if v_active=1 then
    select * into v_key from public.static_weekly_authority_attestation_keys where key_state='active' and activates_at<=statement_timestamp() and (verify_not_after is null or verify_not_after>statement_timestamp()) for share;
    v_probe:=jsonb_build_object('schema','memphis-zoo.static-weekly-authority-health-canary.v1','key_id',v_key.key_id,'purpose','operational_sign_verify');
    v_signature:=public.static_weekly_v3_hmac(v_key.secret_material,'authority_health_canary',v_probe);
    v_canary:=v_signature ~ '^[0-9a-f]{64}$' and public.static_weekly_v3_constant_time_equal(decode(v_signature,'hex'),decode(public.static_weekly_v3_hmac(v_key.secret_material,'authority_health_canary',v_probe),'hex'));
  end if;
  return jsonb_build_object('ready',v_active=1 and v_overlap_bad=0 and v_cp and v_v3>=8 and v_canary,'active_key_count',v_active,'expired_overlap_count',v_overlap_bad,'control_plane_role_present',v_cp,'v3_function_count',v_v3,'operational_sign_verify_canary',v_canary,'key_ids',(select coalesce(jsonb_agg(jsonb_build_object('key_id',key_id,'state',key_state,'activates_at',activates_at,'verify_not_after',verify_not_after,'recovery_of_key_id',recovery_of_key_id) order by key_id),'[]'::jsonb) from public.static_weekly_authority_attestation_keys));
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v3_configure_initial_authority_key(p_key_id text, p_secret text, p_configured_by text DEFAULT 'release-owner'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
  perform public.static_weekly_v3_assert_release_operator();
  if p_key_id !~ '^static-weekly-authority-hmac-v[0-9]+$' or length(coalesce(p_secret,''))<32 then raise exception using errcode='22023',message='versioned scheduler key identity and minimum secret length are required'; end if;
  if exists(select 1 from public.static_weekly_authority_attestation_keys where key_state in ('active','overlap','pending')) then raise exception using errcode='23505',message='use the explicit key-rotation procedure after initial scheduler key provisioning'; end if;
  insert into public.static_weekly_authority_attestation_keys(key_id,secret_material,key_state,activates_at,verify_not_after,configured_by) values(p_key_id,p_secret,'active',statement_timestamp(),null,left(coalesce(nullif(btrim(p_configured_by),''),'release-owner'),200));
  return public.static_weekly_v3_authority_health();
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v3_create_draft(p_effective_start date, p_objective_version text, p_objective jsonb, p_input_provenance jsonb, p_document jsonb, p_expected_revision bigint, p_manager_id uuid, p_idempotency_key text, p_source_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_actor jsonb; v_document jsonb; v_response jsonb; v_version uuid; v_source uuid;
begin
  perform public.static_weekly_v3_assert_control_plane(); v_actor:=public.static_weekly_v3_manager_actor(p_manager_id); perform public.static_weekly_v3_assert_registered_source(p_source_id,p_document#>'{semantic_snapshot,recurring_source}');
  v_document:=jsonb_set(p_document,'{attestation}',public.static_weekly_v3_issue_attestation('recurring_document',public.static_weekly_document_attestation_payload(p_document)),true);
  v_response:=public.static_weekly_v2_create_draft(p_effective_start,p_objective_version,p_objective,p_input_provenance,v_document,p_expected_revision,p_manager_id,v_actor->>'manager_name',p_idempotency_key);
  v_version:=(v_response#>>'{data,version_id}')::uuid; perform set_config('app.static_weekly_source_bind','on',true); update public.weekly_schedule_versions set authority_source_id=p_source_id where version_id=v_version and authority_source_id is null;
  select authority_source_id into v_source from public.weekly_schedule_versions where version_id=v_version for share;
  if v_source is distinct from p_source_id then raise exception using errcode='23514',message='draft did not retain one immutable authority source identity'; end if;
  return v_response;
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v3_hmac(p_secret text, p_scope text, p_payload jsonb)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_schema text; v_hmac text;
begin
  select n.nspname into v_schema from pg_extension e join pg_namespace n on n.oid=e.extnamespace where e.extname='pgcrypto';
  if v_schema not in ('extensions','public') then raise exception using errcode='55000',message='pgcrypto must be installed in extensions or public'; end if;
  execute format('select encode(%I.hmac(convert_to($1,''UTF8''),convert_to($2,''UTF8''),''sha256''),''hex'')',v_schema) into v_hmac using p_scope||E'\n'||p_payload::text,p_secret;
  return v_hmac;
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v3_issue_attestation(p_scope text, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_key public.static_weekly_authority_attestation_keys%rowtype;
begin
  select * into v_key from public.static_weekly_authority_attestation_keys where key_state='active' and activates_at<=statement_timestamp() and (verify_not_after is null or verify_not_after>statement_timestamp()) for share;
  if not found then raise exception using errcode='42501',message='static weekly authority has no active signing key'; end if;
  return jsonb_build_object('schema','memphis-zoo.static-weekly-authority-attestation.v2','key_id',v_key.key_id,'scope',p_scope,'payload_digest',public.static_weekly_digest_jsonb(p_payload),'signature',public.static_weekly_v3_hmac(v_key.secret_material,p_scope,p_payload));
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v3_manager_actor(p_manager_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_name text;
begin
  select display_name into v_name from public.ops_manager_managers where manager_id=p_manager_id and active=true and revoked_at is null and is_system_principal=false and roles && array['OPS_MANAGER','CUSTODIAL_MANAGER','DIRECTOR','SECURITY_ADMIN']::text[] for share;
  if nullif(btrim(v_name),'') is null then raise exception using errcode='42501',message='an authorized active named manager principal is required'; end if;
  return jsonb_build_object('manager_id',p_manager_id::text,'manager_name',v_name);
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v3_read_authority_source(p_source_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_source jsonb;
begin
  perform public.static_weekly_v3_assert_control_plane();
  select canonical_source into v_source from public.static_weekly_authority_source_documents where source_id=p_source_id and active=true and retired_at is null for share;
  if not found then raise exception using errcode='23514',message='scheduler source is not an active release-registered source of record'; end if;
  return jsonb_build_object('source_id',p_source_id::text,'compiler_input',v_source,'exceptions','[]'::jsonb);
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v3_read_manager_snapshot(p_week_start date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_snapshot jsonb; v_availability jsonb:='[]'::jsonb; v_roster jsonb:='[]'::jsonb; v_item jsonb; v_date date; v_state text; v_person uuid; v_name text; v_active boolean; v_devices jsonb; v_week_staffing jsonb; v_projection_revision bigint; v_staffing_revision bigint; v_projection_status text:='missing';
begin
  perform public.static_weekly_v3_assert_control_plane();
  v_snapshot:=public.static_weekly_v3_read_manager_snapshot_base(p_week_start);
  for v_item in select value from jsonb_array_elements(coalesce(v_snapshot->'availability','[]'::jsonb)) loop
    v_date:=p_week_start+mod((v_item->>'day_of_week')::integer-extract(dow from p_week_start)::integer+7,7);
    select s.staffing_state into v_state from public.weekly_roster_slot_staffing_states s
    where s.slot_id=(v_item->>'slot_id')::uuid and s.effective_start<=v_date
    order by s.effective_start desc,s.authority_revision desc limit 1;
    select r.person_id,r.person_name_snapshot into v_person,v_name from public.v_weekly_roster_slot_incumbency_ranges r
    where r.slot_id=(v_item->>'slot_id')::uuid and r.effective_start<=v_date and (r.effective_end is null or v_date<r.effective_end)
    order by r.effective_start desc,r.incumbency_id desc limit 1;
    select e.active into v_active from public.employees e where e.id=v_person;
    select coalesce(jsonb_agg(d.device_id order by d.device_id),'[]'::jsonb) into v_devices from public.devices d where d.active=true and d.assigned_employee_id=v_person;
    v_item:=v_item||jsonb_build_object(
      'service_date',v_date::text,
      'availability_state',coalesce(v_state,v_item->>'availability_state'),
      'person_id',v_person::text,
      'person_name',v_name,
      'employee_active',v_active,
      'device_ids',coalesce(v_devices,'[]'::jsonb)
    );
    v_availability:=v_availability||jsonb_build_array(v_item);
  end loop;
  for v_item in select value from jsonb_array_elements(coalesce(v_snapshot->'roster','[]'::jsonb)) loop
    select coalesce(jsonb_agg(a order by a->>'service_date'),'[]'::jsonb) into v_week_staffing
    from jsonb_array_elements(v_availability) a where a->>'slot_id'=v_item->>'slot_id';
    v_roster:=v_roster||jsonb_build_array(v_item||jsonb_build_object('week_staffing',v_week_staffing));
  end loop;
  if jsonb_typeof(v_snapshot->'latest_projection')='object' then
    select (r.response_json->>'revision')::bigint into v_projection_revision
    from public.weekly_schedule_command_receipts r
    where r.command_type='materialize_projection'
      and r.response_json#>>'{data,projection_id}'=v_snapshot#>>'{latest_projection,projection_id}'
    order by r.accepted_at desc,r.command_id desc limit 1;
  end if;
  select max(s.authority_revision) into v_staffing_revision
  from public.weekly_roster_slot_staffing_states s
  where s.effective_start<=p_week_start+6;
  if v_projection_revision is not null and (v_staffing_revision is null or v_projection_revision>v_staffing_revision) then
    v_projection_status:='current';
  elsif v_projection_revision is not null or v_staffing_revision is not null then
    v_projection_status:='stale_staffing_change';
    v_snapshot:=jsonb_set(v_snapshot,'{latest_projection}','null'::jsonb,true);
  end if;
  return jsonb_set(jsonb_set(v_snapshot,'{availability}',v_availability,true),'{roster}',v_roster,true)
    ||jsonb_build_object('projection_status',v_projection_status,'projection_authority_revision',v_projection_revision,'staffing_authority_revision',v_staffing_revision);
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v3_read_publication_source(p_publication_id uuid, p_service_date date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_document jsonb; v_version uuid; v_source uuid;
begin
  perform public.static_weekly_v3_assert_control_plane();
  select v.draft_document,p.version_id,v.authority_source_id into v_document,v_version,v_source
  from public.weekly_schedule_publications p
  join public.weekly_schedule_versions v on v.version_id=p.version_id
  where p.publication_id=p_publication_id;
  if not found or v_source is null or public.static_weekly_effective_version(p_service_date) is distinct from v_version then
    raise exception using errcode='23514',message='control plane source must name the effective immutable publication and registered source';
  end if;
  return jsonb_build_object(
    'source_id',v_source::text,
    'compiler_input',public.static_weekly_v4_hydrate_compiler_source(v_document#>'{semantic_snapshot,recurring_source}',p_service_date),
    'exceptions',public.static_weekly_compiler_exception_set(p_publication_id,p_service_date),
    'publication_id',p_publication_id::text,
    'version_id',v_version::text,
    'authority_revision',(select current_revision from public.static_weekly_schedule_control where singleton)
  );
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v3_recover_authority_key(p_key_id text, p_secret text, p_recovery_of text, p_configured_by text DEFAULT 'release-owner'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_now timestamptz:=statement_timestamp(); v_active text; v_active_count integer;
begin
  perform public.static_weekly_v3_assert_release_operator();
  if p_key_id !~ '^static-weekly-authority-hmac-v[0-9]+$' or p_key_id is distinct from nullif(btrim(p_key_id),'') or length(coalesce(p_secret,''))<32 or nullif(btrim(p_configured_by),'') is null or nullif(btrim(p_recovery_of),'') is null then
    raise exception using errcode='22023',message='recovery requires a distinct new versioned key, valid secret, exact failed active predecessor, and release operator identity';
  end if;
  perform 1 from public.static_weekly_authority_attestation_keys where key_state='active' and activates_at<=v_now and (verify_not_after is null or verify_not_after>v_now) for update;
  select count(*),min(key_id) into v_active_count,v_active from public.static_weekly_authority_attestation_keys where key_state='active' and activates_at<=v_now and (verify_not_after is null or verify_not_after>v_now);
  if v_active_count<>1 or p_recovery_of is distinct from v_active or p_key_id=p_recovery_of then
    raise exception using errcode='23514',message='recovery predecessor must be the one current active failed key';
  end if;
  if exists(select 1 from public.static_weekly_authority_attestation_keys where key_id=p_key_id) then
    raise exception using errcode='23505',message='recovery key identity must be new and may not be reused';
  end if;
  if exists(select 1 from public.static_weekly_authority_attestation_keys where recovery_of_key_id=p_recovery_of) then
    raise exception using errcode='23505',message='failed active key already has one immutable recovery successor';
  end if;
  update public.static_weekly_authority_attestation_keys
  set key_state='revoked',revoked_at=v_now,revoked_by='failed-active-recovery',verify_not_after=v_now
  where key_id=v_active and key_state='active';
  if not found then raise exception using errcode='40001',message='failed active key changed before atomic recovery could complete'; end if;
  insert into public.static_weekly_authority_attestation_keys(key_id,secret_material,key_state,activates_at,verify_not_after,configured_by,recovery_of_key_id)
  values(p_key_id,p_secret,'active',v_now,null,left(p_configured_by,200),p_recovery_of);
  return public.static_weekly_v3_authority_health();
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v3_register_authority_source(p_source_id uuid, p_canonical_source jsonb, p_configured_by text DEFAULT 'release-owner'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_digest text;
begin
  perform public.static_weekly_v3_assert_release_operator();
  if p_source_id is null or nullif(btrim(p_configured_by),'') is null then raise exception using errcode='22023',message='registered scheduler source needs an immutable UUID and release owner'; end if;
  perform public.static_weekly_v3_source_identity(p_canonical_source); v_digest:=public.static_weekly_digest_jsonb(p_canonical_source);
  insert into public.static_weekly_authority_source_documents(source_id,canonical_source,source_digest,configured_by)
  values(p_source_id,p_canonical_source,v_digest,left(p_configured_by,200));
  return jsonb_build_object('source_id',p_source_id::text,'source_digest',v_digest,'active',true);
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v3_revoke_authority_key(p_key_id text, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
  perform public.static_weekly_v3_assert_release_operator();
  if nullif(btrim(p_reason),'') is null then raise exception using errcode='22023',message='key revocation reason is required'; end if;
  update public.static_weekly_authority_attestation_keys set key_state='revoked',revoked_at=statement_timestamp(),revoked_by=left(p_reason,200),verify_not_after=least(coalesce(verify_not_after,statement_timestamp()),statement_timestamp()) where key_id=p_key_id and key_state<>'active';
  if not found then raise exception using errcode='23514',message='only a non-active overlap or pending key may be revoked'; end if;
  return public.static_weekly_v3_authority_health();
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v3_rotate_authority_key(p_key_id text, p_secret text, p_overlap_until timestamp with time zone, p_configured_by text DEFAULT 'release-owner'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_now timestamptz:=statement_timestamp();
begin
  perform public.static_weekly_v3_assert_release_operator();
  if p_key_id !~ '^static-weekly-authority-hmac-v[0-9]+$' or length(coalesce(p_secret,''))<32 or p_overlap_until<=v_now or p_overlap_until>v_now+interval '24 hours' then raise exception using errcode='22023',message='rotation requires a new versioned key, 32-character secret, and bounded 24-hour overlap'; end if;
  update public.static_weekly_authority_attestation_keys set key_state='overlap',verify_not_after=p_overlap_until where key_state='active';
  insert into public.static_weekly_authority_attestation_keys(key_id,secret_material,key_state,activates_at,verify_not_after,configured_by) values(p_key_id,p_secret,'active',v_now,null,left(coalesce(nullif(btrim(p_configured_by),''),'release-owner'),200));
  return public.static_weekly_v3_authority_health();
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v3_update_draft(p_version_id uuid, p_document jsonb, p_objective jsonb, p_input_provenance jsonb, p_expected_draft_revision bigint, p_expected_revision bigint, p_manager_id uuid, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_actor jsonb; v_document jsonb; v_source uuid;
begin
  perform public.static_weekly_v3_assert_control_plane(); v_actor:=public.static_weekly_v3_manager_actor(p_manager_id); select authority_source_id into v_source from public.weekly_schedule_versions where version_id=p_version_id and lifecycle_state='draft' for share; perform public.static_weekly_v3_assert_registered_source(v_source,p_document#>'{semantic_snapshot,recurring_source}');
  v_document:=jsonb_set(p_document,'{attestation}',public.static_weekly_v3_issue_attestation('recurring_document',public.static_weekly_document_attestation_payload(p_document)),true);
  return public.static_weekly_v2_update_draft(p_version_id,v_document,p_objective,p_input_provenance,p_expected_draft_revision,p_expected_revision,p_manager_id,v_actor->>'manager_name',p_idempotency_key);
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v4_assert_projection_envelope(p_envelope jsonb, p_publication_id uuid, p_week_start date, p_exception_set jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_authority jsonb:=p_envelope->'authority'; v_base jsonb; v_compiler_exceptions jsonb; v_publication public.weekly_schedule_publications%rowtype;
begin
  perform public.static_weekly_assert_exact_object(p_envelope,array['adapter','service_date','week_start','week_end','authority','receipt','authority_digest','replay_digest','compiler_version','objective','metrics','applied_exceptions','assignments','database_projection_identity'],array['adapter','service_date','week_start','week_end','authority','receipt','authority_digest','replay_digest','compiler_version','objective','metrics','applied_exceptions','assignments','database_projection_identity'],'projection envelope');
  perform public.static_weekly_assert_exact_object(p_envelope->'adapter',array['schema','version'],array['schema','version'],'projection envelope adapter');
  if jsonb_typeof(p_exception_set) is distinct from 'array' or jsonb_typeof(p_envelope->'service_date') is distinct from 'string'
    or jsonb_typeof(p_envelope->'week_start') is distinct from 'string' or jsonb_typeof(p_envelope->'week_end') is distinct from 'string'
    or jsonb_typeof(p_envelope->'authority_digest') is distinct from 'string' or jsonb_typeof(p_envelope->'replay_digest') is distinct from 'string'
    or jsonb_typeof(p_envelope->'compiler_version') is distinct from 'string' or jsonb_typeof(p_envelope->'objective') is distinct from 'object'
    or jsonb_typeof(p_envelope->'metrics') is distinct from 'object' or jsonb_typeof(p_envelope->'applied_exceptions') is distinct from 'array'
    or jsonb_typeof(p_envelope->'assignments') is distinct from 'array' or jsonb_typeof(p_envelope->'database_projection_identity') is distinct from 'string' then
    raise exception using errcode='23514',message='projection envelope requires complete typed authority, receipt, identity, and assignment fields';
  end if;
  if jsonb_array_length(p_envelope->'assignments')=0 then raise exception using errcode='23514',message='projection assignments may not be empty'; end if;
  if exists(select 1 from jsonb_array_elements(p_envelope->'assignments') as a(x) where jsonb_typeof(a.x) is distinct from 'object' or not (a.x ?& array['plan_work_id','work_id','day_of_week','service_date','status','work_snapshot','explanation'])) then
    raise exception using errcode='23514',message='projection assignments require every identity, status, snapshot, and explanation key';
  end if;
  if exists(select 1 from jsonb_array_elements(p_envelope->'assignments') as a(x)
      where jsonb_typeof(a.x->'plan_work_id') is distinct from 'string' or nullif(btrim(a.x->>'plan_work_id'),'') is null
        or jsonb_typeof(a.x->'work_id') is distinct from 'string' or nullif(btrim(a.x->>'work_id'),'') is null
        or jsonb_typeof(a.x->'day_of_week') is distinct from 'number' or (a.x->>'day_of_week') !~ '^[0-6]$'
        or jsonb_typeof(a.x->'service_date') is distinct from 'string' or nullif(btrim(a.x->>'service_date'),'') is null
        or (a.x->>'service_date') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' or not pg_input_is_valid(a.x->>'service_date','date')
        or case when jsonb_typeof(a.x->'service_date')='string' and (a.x->>'service_date') ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' and pg_input_is_valid(a.x->>'service_date','date') then (a.x->>'service_date')::date::text is distinct from a.x->>'service_date' or (a.x->>'service_date')::date<p_week_start or (a.x->>'service_date')::date>p_week_start+6 else false end
        or jsonb_typeof(a.x->'explanation') is distinct from 'object'
        or jsonb_typeof(a.x->'status') is distinct from 'string' or upper(a.x->>'status') not in ('ASSIGNED','OPEN','REVIEW')) then
    raise exception using errcode='23514',message='projection assignments require complete canonical seven-day identity, status, and explanation facts';
  end if;
  if (select count(*) from jsonb_array_elements(p_envelope->'assignments'))<>(select count(distinct x->>'plan_work_id') from jsonb_array_elements(p_envelope->'assignments') as a(x)) then
    raise exception using errcode='23514',message='projection assignments may not contain duplicate work identities';
  end if;
  select * into v_publication from public.weekly_schedule_publications where publication_id=p_publication_id;
  if not found then raise exception using errcode='23514',message='projection publication is unknown'; end if;
  select draft_document#>'{semantic_snapshot,recurring_source}' into v_base from public.weekly_schedule_versions where version_id=v_publication.version_id;
  v_compiler_exceptions:=public.static_weekly_compiler_exception_set(p_publication_id,p_week_start);
  perform public.static_weekly_assert_compiler_authority(v_authority,p_envelope->'receipt',p_week_start,false);
  if p_envelope #>> '{adapter,schema}' is distinct from 'memphis-zoo.static-weekly-database-adapter.v1' or p_envelope #>> '{adapter,version}' is distinct from 'static-weekly-database-adapter-v1' or p_envelope->>'service_date' is distinct from p_week_start::text or p_envelope->>'week_start' is distinct from p_week_start::text or p_envelope->>'week_end' is distinct from (p_week_start+6)::text
    or p_envelope->>'authority_digest' is distinct from public.static_weekly_digest_jsonb(v_authority) or p_envelope->>'replay_digest' is distinct from p_envelope #>>'{receipt,compiler,replayDigest}'
    or p_envelope->>'compiler_version' is distinct from v_authority #>>'{optimizerResult,compilerVersion}' or p_envelope->'objective' is distinct from v_authority #> '{optimizerResult,objective}' or p_envelope->'metrics' is distinct from v_authority #> '{optimizerResult,metrics}'
    or p_envelope->>'database_projection_identity' is distinct from public.static_weekly_digest_jsonb(p_envelope-'database_projection_identity')
    or public.static_weekly_v4_recurring_source_identity(v_authority->'compilerInput') is distinct from public.static_weekly_v4_recurring_source_identity(v_base) then
    raise exception using errcode='23514',message='projection must bind the stable registered source, complete dated receipt, objective, metrics, replay, and full weekly envelope';
  end if;
  if v_authority->'appliedExceptions' is distinct from p_exception_set or p_envelope->'applied_exceptions' is distinct from p_exception_set then
    raise exception using errcode='23514',message='overlay compiler input and applied exceptions must bind the complete accepted seven-day exception set';
  end if;
  if v_authority #> '{overlayCompilerInput,exceptions}' is distinct from v_compiler_exceptions then
    raise exception using errcode='23514',message='overlay compiler input must carry every semantic accepted exception fact for the same seven-day horizon';
  end if;
  if exists(with optimizer as(select value x from jsonb_array_elements(v_authority #> '{optimizerResult,assignments}')), projected as(select value x from jsonb_array_elements(p_envelope->'assignments'))
    select 1 from optimizer o full join projected p on p.x->>'plan_work_id'=o.x->>'planWorkId'
    where o.x is null or p.x is null or p.x->>'service_date' is distinct from o.x->>'serviceDate' or p.x->>'work_id' is distinct from o.x->>'workId' or p.x->>'day_of_week' is distinct from o.x->>'dayOfWeek' or upper(p.x->>'status') is distinct from upper(o.x->>'status')
      or (o.x->>'status'='ASSIGNED' and (p.x->>'owner_slot_id' is distinct from o.x->>'slotId' or p.x->>'owner_person_id' is distinct from o.x->>'personId'))
      or (o.x->>'status' in ('OPEN','REVIEW') and (p.x->>'owner_slot_id' is not null or p.x->>'owner_person_id' is not null))) then
    raise exception using errcode='23514',message='complete weekly projection assignments must exactly bind the canonical optimizer';
  end if;
  if exists(with optimizer as(select value x from jsonb_array_elements(v_authority #> '{optimizerResult,assignments}')), projected as(select value x from jsonb_array_elements(p_envelope->'assignments'))
    select 1 from optimizer o join projected p on p.x->>'plan_work_id'=o.x->>'planWorkId'
    where jsonb_typeof(p.x->'work_snapshot') is distinct from 'object'
      or not (p.x->'work_snapshot' ?& array['workId','dayOfWeek','originSlotId','locationId','locationCodeSnapshot','locationNameSnapshot','window','serviceEffortMinutes','serviceEffortProvenance','priority','priorityProvenance','required','coveragePolicy','bestEffortCoverage','coveragePolicyOrder','coveragePolicyProvenance','requiredQualifications','qualificationProvenance','restrictions','restrictionProvenance','restrictedSlotIds','manualLock','manualLockSlotId','overlayWork'])
      or exists(select 1 from jsonb_object_keys(p.x->'work_snapshot') as k(key) where not (k.key=any(array['workId','dayOfWeek','originSlotId','locationId','locationCodeSnapshot','locationNameSnapshot','window','serviceEffortMinutes','serviceEffortProvenance','priority','priorityProvenance','required','coveragePolicy','bestEffortCoverage','coveragePolicyOrder','coveragePolicyProvenance','requiredQualifications','qualificationProvenance','restrictions','restrictionProvenance','restrictedSlotIds','manualLock','manualLockSlotId','overlayWork'])))
      or jsonb_typeof(p.x#>'{work_snapshot,workId}') is distinct from 'string' or jsonb_typeof(p.x#>'{work_snapshot,dayOfWeek}') is distinct from 'number' or jsonb_typeof(p.x#>'{work_snapshot,originSlotId}') not in ('string','null')
      or p.x#>>'{work_snapshot,workId}' is distinct from o.x->>'workId' or p.x#>>'{work_snapshot,dayOfWeek}' is distinct from o.x->>'dayOfWeek' or p.x#>>'{work_snapshot,window,start}' is distinct from o.x#>>'{window,start}' or p.x#>>'{work_snapshot,window,end}' is distinct from o.x#>>'{window,end}' or p.x#>>'{work_snapshot,serviceEffortMinutes}' is distinct from o.x->>'serviceEffortMinutes'
      or jsonb_typeof(p.x#>'{work_snapshot,locationId}') is distinct from 'string' or p.x#>>'{work_snapshot,locationId}' !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
      or jsonb_typeof(p.x#>'{work_snapshot,locationCodeSnapshot}') is distinct from 'string' or nullif(btrim(p.x#>>'{work_snapshot,locationCodeSnapshot}'),'') is null or jsonb_typeof(p.x#>'{work_snapshot,locationNameSnapshot}') is distinct from 'string' or nullif(btrim(p.x#>>'{work_snapshot,locationNameSnapshot}'),'') is null
      or jsonb_typeof(p.x#>'{work_snapshot,window}') is distinct from 'object' or jsonb_typeof(p.x#>'{work_snapshot,window,start}') is distinct from 'string' or nullif(btrim(p.x#>>'{work_snapshot,window,start}'),'') is null or jsonb_typeof(p.x#>'{work_snapshot,window,end}') is distinct from 'string' or nullif(btrim(p.x#>>'{work_snapshot,window,end}'),'') is null
      or jsonb_typeof(p.x#>'{work_snapshot,serviceEffortMinutes}') is distinct from 'number' or jsonb_typeof(p.x#>'{work_snapshot,serviceEffortProvenance}') is distinct from 'string' or nullif(btrim(p.x#>>'{work_snapshot,serviceEffortProvenance}'),'') is null or jsonb_typeof(p.x#>'{work_snapshot,priority}') is distinct from 'number'
      or jsonb_typeof(p.x#>'{work_snapshot,priorityProvenance}') not in ('string','null') or (jsonb_typeof(p.x#>'{work_snapshot,priorityProvenance}')='string' and nullif(btrim(p.x#>>'{work_snapshot,priorityProvenance}'),'') is null)
      or jsonb_typeof(p.x#>'{work_snapshot,required}') is distinct from 'boolean' or jsonb_typeof(p.x#>'{work_snapshot,coveragePolicy}') not in ('string','null') or jsonb_typeof(p.x#>'{work_snapshot,bestEffortCoverage}') is distinct from 'boolean' or jsonb_typeof(p.x#>'{work_snapshot,coveragePolicyOrder}') not in ('number','null') or jsonb_typeof(p.x#>'{work_snapshot,coveragePolicyProvenance}') not in ('string','null')
      or jsonb_typeof(p.x#>'{work_snapshot,requiredQualifications}') is distinct from 'array' or jsonb_typeof(p.x#>'{work_snapshot,qualificationProvenance}') is distinct from 'string' or nullif(btrim(p.x#>>'{work_snapshot,qualificationProvenance}'),'') is null or jsonb_typeof(p.x#>'{work_snapshot,restrictions}') is distinct from 'array' or jsonb_typeof(p.x#>'{work_snapshot,restrictionProvenance}') is distinct from 'string' or nullif(btrim(p.x#>>'{work_snapshot,restrictionProvenance}'),'') is null or jsonb_typeof(p.x#>'{work_snapshot,restrictedSlotIds}') is distinct from 'array' or jsonb_typeof(p.x#>'{work_snapshot,manualLock}') is distinct from 'boolean' or jsonb_typeof(p.x#>'{work_snapshot,manualLockSlotId}') not in ('string','null') or jsonb_typeof(p.x#>'{work_snapshot,overlayWork}') is distinct from 'boolean'
      or exists(select 1 from jsonb_array_elements(p.x#>'{work_snapshot,requiredQualifications}') as q(value) where jsonb_typeof(q.value) is distinct from 'string' or nullif(btrim(q.value#>>'{}'),'') is null)
      or exists(select 1 from jsonb_array_elements(p.x#>'{work_snapshot,restrictions}') as r(value) where jsonb_typeof(r.value) is distinct from 'string' or nullif(btrim(r.value#>>'{}'),'') is null)
      or exists(select 1 from jsonb_array_elements(p.x#>'{work_snapshot,restrictedSlotIds}') as r(value) where jsonb_typeof(r.value) is distinct from 'string' or nullif(btrim(r.value#>>'{}'),'') is null)
      or (select count(*) from jsonb_array_elements(p.x#>'{work_snapshot,requiredQualifications}'))<>(select count(distinct value#>>'{}') from jsonb_array_elements(p.x#>'{work_snapshot,requiredQualifications}'))
      or (select count(*) from jsonb_array_elements(p.x#>'{work_snapshot,restrictions}'))<>(select count(distinct value#>>'{}') from jsonb_array_elements(p.x#>'{work_snapshot,restrictions}'))
      or (select count(*) from jsonb_array_elements(p.x#>'{work_snapshot,restrictedSlotIds}'))<>(select count(distinct value#>>'{}') from jsonb_array_elements(p.x#>'{work_snapshot,restrictedSlotIds}'))
  ) then raise exception using errcode='23514',message='projection work snapshots must be complete semantic authority facts bound to the canonical optimizer'; end if;
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v4_begin_day_changes(p_service_date date, p_week_start date, p_base_version_id uuid, p_publication_id uuid, p_operations jsonb, p_expected_revision bigint, p_manager_id uuid, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_actor jsonb; v_child public.weekly_schedule_command_receipts%rowtype;
  v_projection public.weekly_schedule_command_receipts%rowtype; v_projection_row public.weekly_schedule_compiled_projections%rowtype;
  v_operation jsonb; v_expected jsonb; v_mutations jsonb:='[]'::jsonb; v_snapshot jsonb;
  v_child_count integer:=0; v_requested_count integer; v_index integer; v_key text; v_expected_command text;
begin
  perform public.static_weekly_v3_assert_control_plane();
  v_actor:=public.static_weekly_v3_manager_actor(p_manager_id);
  if p_service_date is null or p_week_start is null or extract(isodow from p_week_start)<>1
     or p_service_date<p_week_start or p_service_date>p_week_start+6
     or p_base_version_id is null or p_publication_id is null or p_expected_revision is null or p_expected_revision<0
     or nullif(btrim(coalesce(p_idempotency_key,'')),'') is null or length(btrim(p_idempotency_key))>200
     or p_operations is null or jsonb_typeof(p_operations)<>'array' or jsonb_array_length(p_operations) not between 1 and 25 then
    raise exception using errcode='22023',message='complete bounded day-change batch identity is required';
  end if;
  p_idempotency_key:=btrim(p_idempotency_key);
  v_requested_count:=jsonb_array_length(p_operations);

  -- The same transaction lock used by every child and projection writer makes
  -- recognition, continuation, and independent-session races one serial order.
  perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));

  select * into v_projection from public.weekly_schedule_command_receipts r
  where r.actor_manager_id=p_manager_id
    and r.idempotency_key=public.static_weekly_v4_day_change_projection_key(p_idempotency_key);

  -- Index 25 is inspected as a sentinel beyond the maximum accepted batch so
  -- a previously longer chain can never be mistaken for a 25-item replay.
  for v_index in 0..25 loop
    v_key:=public.static_weekly_v4_day_change_child_key(p_idempotency_key,v_index);
    select * into v_child from public.weekly_schedule_command_receipts r
    where r.actor_manager_id=p_manager_id and r.idempotency_key=v_key;
    if found then
      if v_index<>v_child_count then
        raise exception using errcode='23505',message='idempotency key is bound to an incomplete day-change receipt chain';
      end if;
      v_child_count:=v_child_count+1;
    end if;
  end loop;

  if v_child_count=0 and v_projection.command_id is null then
    return jsonb_build_object('replayed',false);
  end if;
  if v_child_count<>v_requested_count or v_projection.command_id is null then
    raise exception using errcode='23505',message='idempotency key is bound to a different complete day-change batch';
  end if;

  for v_index in 0..v_requested_count-1 loop
    v_operation:=p_operations->v_index;
    select * into strict v_child from public.weekly_schedule_command_receipts r
    where r.actor_manager_id=p_manager_id
      and r.idempotency_key=public.static_weekly_v4_day_change_child_key(p_idempotency_key,v_index);
    if jsonb_typeof(v_operation)<>'object' or v_operation->>'operation' not in ('exception','cover_all') then
      raise exception using errcode='22023',message='day-change operations must use the normalized control-plane contract';
    end if;
    v_expected_command:=case when v_operation->>'operation'='exception' and v_operation->>'exceptionType'='reverse' then 'reverse_exception' else 'apply_exception' end;
    if v_operation->>'operation'='exception' then
      v_expected:=jsonb_build_object(
        'operation','apply_exception','exception_type',v_operation->>'exceptionType','service_date',p_service_date,
        'starts_at',case when v_operation->>'startsAt' is null then null else (v_operation->>'startsAt')::time end,
        'ends_at',case when v_operation->>'endsAt' is null then null else (v_operation->>'endsAt')::time end,
        'base_version_id',p_base_version_id,'publication_id',p_publication_id,'reason',v_operation->>'reason',
        'payload',v_operation->'payload','expected_revision',p_expected_revision+v_index,
        'actor_manager_id',p_manager_id,
        'reverses_exception_id',case when v_operation->>'reversesExceptionId' is null then null else (v_operation->>'reversesExceptionId')::uuid end
      );
      if (v_child.request_canonical_json-'actor_manager_name') is distinct from v_expected then
        raise exception using errcode='23505',message='idempotency key was already used for different ordered day-change inputs';
      end if;
    else
      v_expected:=jsonb_build_object(
        'operation','apply_exception','exception_type','cover_all','service_date',p_service_date,
        'starts_at',null,'ends_at',null,'base_version_id',p_base_version_id,'publication_id',p_publication_id,
        'reason',v_operation->>'reason','expected_revision',p_expected_revision+v_index,
        'actor_manager_id',p_manager_id,'reverses_exception_id',null
      );
      if (v_child.request_canonical_json-'actor_manager_name'-'payload') is distinct from v_expected
         or jsonb_typeof(v_child.request_canonical_json->'payload')<>'object'
         or (select count(*) from jsonb_object_keys(v_child.request_canonical_json->'payload'))<>1
         or jsonb_typeof(v_child.request_canonical_json#>'{payload,availability}')<>'object'
         or v_child.request_canonical_json#>>'{payload,availability,slotId}' is distinct from v_operation->>'slotId'
         or (v_operation->'shift'<>'null'::jsonb and v_child.request_canonical_json#>'{payload,availability,shift}' is distinct from v_operation->'shift') then
        raise exception using errcode='23505',message='idempotency key was already used for different ordered day-change inputs';
      end if;
    end if;
    if v_child.command_type<>v_expected_command or v_child.expected_revision<>p_expected_revision+v_index
       or v_child.request_digest<>public.static_weekly_digest_jsonb(v_child.request_canonical_json)
       or v_child.response_json->>'request_digest'<>v_child.request_digest
       or v_child.response_json->>'content_digest'<>v_child.content_digest
       or v_child.response_json->>'operation'<>v_expected_command
       or (v_child.response_json->>'revision')::bigint<>p_expected_revision+v_index+1
       or v_child.response_json#>>'{data,sequence}'<>(p_expected_revision+v_index+1)::text
       or v_child.response_json#>>'{data,service_date}'<>p_service_date::text
       or v_child.response_json->>'output_digest'<>public.static_weekly_digest_jsonb(v_child.response_json-'output_digest')
       or v_child.response_digest<>v_child.response_json->>'output_digest'
       or not exists(
         select 1 from public.weekly_schedule_authority_revisions a
         where a.command_id=v_child.command_id and a.authority_revision=p_expected_revision+v_index+1
           and a.operation=v_expected_command and a.actor_manager_id=p_manager_id and a.content_digest=v_child.content_digest
       ) then
      raise exception using errcode='23505',message='idempotency key is bound to an invalid day-change receipt chain';
    end if;
    v_mutations:=v_mutations||jsonb_build_array(v_child.response_json->'data');
  end loop;

  if v_projection.command_type<>'materialize_projection'
     or v_projection.expected_revision<>p_expected_revision+v_requested_count
     or v_projection.request_canonical_json->>'operation'<>'materialize_projection'
     or v_projection.request_canonical_json->>'publication_id'<>p_publication_id::text
     or v_projection.request_canonical_json->>'service_date'<>p_week_start::text
     or v_projection.request_canonical_json->>'actor_manager_id'<>p_manager_id::text
     or (v_projection.request_canonical_json->>'expected_revision')::bigint<>p_expected_revision+v_requested_count
     or v_projection.request_digest<>public.static_weekly_digest_jsonb(v_projection.request_canonical_json)
     or v_projection.response_json->>'request_digest'<>v_projection.request_digest
     or v_projection.response_json->>'content_digest'<>v_projection.content_digest
     or v_projection.response_json->>'operation'<>'materialize_projection'
     or (v_projection.response_json->>'revision')::bigint<>p_expected_revision+v_requested_count+1
     or v_projection.response_json->>'output_digest'<>public.static_weekly_digest_jsonb(v_projection.response_json-'output_digest')
     or v_projection.response_digest<>v_projection.response_json->>'output_digest'
     or not exists(
       select 1 from public.weekly_schedule_authority_revisions a
       where a.command_id=v_projection.command_id and a.authority_revision=p_expected_revision+v_requested_count+1
         and a.operation='materialize_projection' and a.actor_manager_id=p_manager_id and a.content_digest=v_projection.content_digest
     ) then
    raise exception using errcode='23505',message='idempotency key is bound to an invalid final projection receipt';
  end if;

  begin
    select * into strict v_projection_row from public.weekly_schedule_compiled_projections p
    where p.projection_id=(v_projection.response_json#>>'{data,projection_id}')::uuid;
  exception when no_data_found or too_many_rows then
    raise exception using errcode='23505',message='idempotency key is bound to a missing immutable projection';
  end;
  if v_projection_row.publication_id<>p_publication_id or v_projection_row.version_id<>p_base_version_id
     or v_projection_row.week_start<>p_week_start or v_projection_row.compiled_by_manager_id<>p_manager_id
     or v_projection_row.replay_digest<>v_projection.response_json#>>'{data,replay_digest}' then
    raise exception using errcode='23505',message='idempotency key is bound to a different immutable projection';
  end if;
  v_snapshot:=public.static_weekly_v4_projection_snapshot(v_projection_row.projection_id);
  if v_snapshot is null then
    raise exception using errcode='23505',message='idempotency key is bound to a missing immutable projection';
  end if;
  return jsonb_build_object(
    'replayed',true,
    'response',v_projection.response_json||jsonb_build_object(
      'operation','apply_day_changes',
      'data',(v_projection.response_json->'data')||jsonb_build_object('current_projection',v_snapshot,'mutations',v_mutations)
    )
  );
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v4_hydrate_compiler_source(p_source jsonb, p_service_date date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_slots jsonb; v_slot jsonb; v_ranges jsonb; v_hydrated jsonb; v_version jsonb; v_availability jsonb; v_item jsonb; v_date date; v_state text;
begin
  if p_service_date is null or jsonb_typeof(p_source) is distinct from 'object' or jsonb_typeof(p_source->'slots') is distinct from 'array' then
    raise exception using errcode='23514',message='dated scheduler source requires one canonical service date and stable slot array';
  end if;
  for v_slot in select value from jsonb_array_elements(p_source->'slots') loop
    if jsonb_typeof(v_slot->'id') is distinct from 'string' or v_slot->>'id' !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then
      raise exception using errcode='23514',message='registered scheduler source contains a non-UUID stable roster slot identity';
    end if;
    select coalesce(jsonb_agg(jsonb_build_object(
      'personId',r.person_id::text,'displayName',r.person_name_snapshot,
      'effectiveStart',r.effective_start::text,
      'effectiveEnd',case when r.effective_end is null then null else r.effective_end::text end
    ) order by r.effective_start,r.incumbency_id),'[]'::jsonb) into v_ranges
    from public.v_weekly_roster_slot_incumbency_ranges r
    where r.slot_id=(v_slot->>'id')::uuid and r.effective_start<=p_service_date+6
      and (r.effective_end is null or r.effective_end>p_service_date);
    if jsonb_array_length(v_ranges)=0 then
      raise exception using errcode='23514',message='every projected stable roster slot requires closure-aware incumbent history for the requested horizon';
    end if;
    v_slot:=jsonb_set(v_slot,'{incumbencies}',v_ranges,true);
    v_slots:=coalesce(v_slots,'[]'::jsonb)||jsonb_build_array(v_slot);
  end loop;
  v_hydrated:=jsonb_set(p_source,'{slots}',coalesce(v_slots,'[]'::jsonb),true);
  if jsonb_typeof(v_hydrated->'version')='object' then v_version:=v_hydrated->'version';
  elsif jsonb_typeof(v_hydrated->'versions')='array' and jsonb_array_length(v_hydrated->'versions')=1 then v_version:=(v_hydrated->'versions')->0;
  else raise exception using errcode='23514',message='dated scheduler source must carry exactly one recurring version';
  end if;
  for v_item in select value from jsonb_array_elements(coalesce(v_version->'slotAvailability','[]'::jsonb)) loop
    v_date:=p_service_date+mod((v_item->>'dayOfWeek')::integer-extract(dow from p_service_date)::integer+7,7);
    select s.staffing_state into v_state from public.weekly_roster_slot_staffing_states s
    where s.slot_id=(v_item->>'slotId')::uuid and s.effective_start<=v_date
    order by s.effective_start desc,s.authority_revision desc limit 1;
    if v_state is not null then v_item:=jsonb_set(v_item,'{status}',to_jsonb(v_state),true); end if;
    v_availability:=coalesce(v_availability,'[]'::jsonb)||jsonb_build_array(v_item);
  end loop;
  v_version:=jsonb_set(v_version,'{slotAvailability}',coalesce(v_availability,'[]'::jsonb),true);
  if jsonb_typeof(v_hydrated->'version')='object' then v_hydrated:=jsonb_set(v_hydrated,'{version}',v_version,true);
  else v_hydrated:=jsonb_set(v_hydrated,'{versions}',jsonb_build_array(v_version),true); end if;
  return jsonb_set(v_hydrated,'{serviceDate}',to_jsonb(p_service_date::text),true);
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v4_mark_employee_departed(p_slot_id uuid, p_reason text, p_expected_revision bigint, p_manager_id uuid, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_actor jsonb; v_manager public.ops_manager_managers%rowtype; v_prior public.weekly_schedule_command_receipts%rowtype; v_incumbent public.v_weekly_roster_slot_incumbency_ranges%rowtype; v_employee public.employees%rowtype; v_request jsonb; v_request_digest text; v_content_digest text; v_command uuid:=gen_random_uuid(); v_revision bigint; v_response jsonb; v_status jsonb; v_effective_start date:=public.sch_service_date(statement_timestamp());
begin
  perform public.static_weekly_v3_assert_control_plane(); v_manager:=public.custodial_assert_manager(p_manager_id); v_actor:=public.static_weekly_v3_manager_actor(p_manager_id);
  perform public.static_weekly_assert_command_identity(p_expected_revision,p_manager_id,v_actor->>'manager_name',p_idempotency_key,'mark_employee_departed');
  if p_slot_id is null or nullif(btrim(coalesce(p_reason,'')),'') is null or char_length(p_reason)>500 or p_reason~'[\x00-\x1f\x7f]' then
    raise exception using errcode='23514',message='departure requires a stable slot and control-free reason of at most 500 characters';
  end if;
  v_request:=jsonb_build_object('operation','mark_employee_departed','slot_id',p_slot_id,'effective_start',v_effective_start,'reason',p_reason,'expected_revision',p_expected_revision,'actor_manager_id',p_manager_id);
  v_request_digest:=public.static_weekly_digest_jsonb(v_request); perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
  select * into v_prior from public.weekly_schedule_command_receipts where actor_manager_id=p_manager_id and idempotency_key=p_idempotency_key;
  if found then if v_prior.request_digest<>v_request_digest then raise exception using errcode='23505',message='idempotency key was already used for different semantic inputs'; end if; return v_prior.response_json; end if;
  perform public.static_weekly_v5_source_availability_template(p_slot_id);
  select * into v_incumbent from public.v_weekly_roster_slot_incumbency_ranges where slot_id=p_slot_id and effective_start<=v_effective_start and (effective_end is null or v_effective_start<effective_end) order by effective_start desc limit 1;
  if not found then raise exception using errcode='23514',message='departure requires one effective stable-slot incumbent'; end if;
  select * into v_employee from public.employees where id=v_incumbent.person_id for update;
  if not found or v_employee.active is not true then raise exception using errcode='23514',message='departure requires one active custodial employee matching the stable-slot incumbent'; end if;
  perform public.static_weekly_v4_assert_employee_turnover_ready(v_employee.id);
  if exists(select 1 from public.weekly_roster_slot_staffing_states where slot_id=p_slot_id and effective_start=v_effective_start and staffing_state='departed_named_absent') then raise exception using errcode='23505',message='stable slot is already marked departed today'; end if;
  v_content_digest:=public.static_weekly_digest_jsonb(v_request-'expected_revision'-'actor_manager_id'-'operation');
  v_revision:=public.static_weekly_advance_authority(p_expected_revision,'mark_employee_departed',p_manager_id,v_actor->>'manager_name',v_command,v_content_digest);
  insert into public.weekly_roster_slot_staffing_states(slot_id,employee_id,staffing_state,effective_start,authority_revision,actor_manager_id,actor_manager_name_snapshot,reason,content_digest)
  values(p_slot_id,v_employee.id,'departed_named_absent',v_effective_start,v_revision,p_manager_id,v_actor->>'manager_name',p_reason,v_content_digest);
  v_status:=public.custodial_set_employee_active(v_employee.id,false,p_manager_id,p_reason,true);
  v_response:=public.static_weekly_response_json('mark_employee_departed',v_revision,v_content_digest,v_request_digest,jsonb_build_object('slot_id',p_slot_id,'former_employee_id',v_employee.id,'former_employee_name',v_employee.display_name,'effective_start',v_effective_start,'employee_status',v_status));
  insert into public.weekly_schedule_command_receipts(command_id,actor_manager_id,actor_manager_name_snapshot,command_type,idempotency_key,expected_revision,request_digest,request_canonical_json,response_json,response_digest,content_digest)
  values(v_command,p_manager_id,v_actor->>'manager_name','mark_employee_departed',p_idempotency_key,p_expected_revision,v_request_digest,v_request,v_response,v_response->>'output_digest',v_content_digest);
  return v_response;
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v4_projection_source_identity(p_source jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare v_identity jsonb; v_version jsonb; v_slots jsonb;
begin
  if jsonb_typeof(p_source) is distinct from 'object' then
    raise exception using errcode='23514',message='projection source must be one compiler input object';
  end if;
  if jsonb_typeof(p_source->'version')='object' then
    v_version:=p_source->'version';
  elsif jsonb_typeof(p_source->'versions')='array' and jsonb_array_length(p_source->'versions')=1 then
    v_version:=(p_source->'versions')->0;
  else
    raise exception using errcode='23514',message='projection source must carry exactly one recurring version';
  end if;
  v_version:=v_version-'id'-'publicationId'-'status'-'effectiveStart'-'effectiveEnd';
  v_identity:=p_source-'serviceDate'-'version'-'versions';
  if jsonb_typeof(v_identity->'slots') is distinct from 'array' then
    raise exception using errcode='23514',message='projection source must carry stable roster slots';
  end if;
  select coalesce(jsonb_agg(slot-'incumbencies' order by ordinal),'[]'::jsonb) into v_slots
  from jsonb_array_elements(v_identity->'slots') with ordinality as s(slot,ordinal);
  v_identity:=jsonb_set(v_identity,'{slots}',v_slots,true);
  return jsonb_set(v_identity,'{version}',v_version,true);
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v4_replace_employee(p_slot_id uuid, p_new_employee_name text, p_reason text, p_expected_revision bigint, p_manager_id uuid, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_actor jsonb; v_manager public.ops_manager_managers%rowtype; v_prior public.weekly_schedule_command_receipts%rowtype; v_incumbent public.v_weekly_roster_slot_incumbency_ranges%rowtype; v_old public.employees%rowtype; v_request jsonb; v_request_digest text; v_content_digest text; v_command uuid:=gen_random_uuid(); v_new_incumbency uuid:=gen_random_uuid(); v_revision bigint; v_response jsonb; v_created jsonb; v_status jsonb; v_assignment jsonb; v_new_employee_id uuid; v_new_name text:=regexp_replace(btrim(coalesce(p_new_employee_name,'')),'\s+',' ','g'); v_device text; v_device_count integer; v_effective_start date:=public.sch_service_date(statement_timestamp());
begin
  perform public.static_weekly_v3_assert_control_plane(); v_manager:=public.custodial_assert_manager(p_manager_id); v_actor:=public.static_weekly_v3_manager_actor(p_manager_id);
  perform public.static_weekly_assert_command_identity(p_expected_revision,p_manager_id,v_actor->>'manager_name',p_idempotency_key,'replace_employee');
  if p_slot_id is null or length(v_new_name) not between 2 and 160 or nullif(btrim(coalesce(p_reason,'')),'') is null or char_length(p_reason)>500 or p_reason~'[\x00-\x1f\x7f]' then
    raise exception using errcode='23514',message='replacement requires a stable slot, new employee name, and control-free reason of at most 500 characters';
  end if;
  v_request:=jsonb_build_object('operation','replace_employee','slot_id',p_slot_id,'new_employee_name',v_new_name,'effective_start',v_effective_start,'reason',p_reason,'expected_revision',p_expected_revision,'actor_manager_id',p_manager_id);
  v_request_digest:=public.static_weekly_digest_jsonb(v_request); perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
  select * into v_prior from public.weekly_schedule_command_receipts where actor_manager_id=p_manager_id and idempotency_key=p_idempotency_key;
  if found then if v_prior.request_digest<>v_request_digest then raise exception using errcode='23505',message='idempotency key was already used for different semantic inputs'; end if; return v_prior.response_json; end if;
  perform public.static_weekly_v5_source_availability_template(p_slot_id);
  select * into v_incumbent from public.v_weekly_roster_slot_incumbency_ranges where slot_id=p_slot_id and effective_start<v_effective_start and (effective_end is null or v_effective_start<effective_end) order by effective_start desc limit 1;
  if not found then raise exception using errcode='23514',message='replacement requires one predecessor stable-slot incumbent'; end if;
  select * into v_old from public.employees where id=v_incumbent.person_id for update;
  if not found then raise exception using errcode='23514',message='replacement predecessor must resolve to a custodial employee'; end if;
  perform public.static_weekly_v4_assert_employee_turnover_ready(v_old.id);
  if exists(select 1 from public.weekly_roster_slot_staffing_states where slot_id=p_slot_id and effective_start=v_effective_start and staffing_state='working') then raise exception using errcode='23505',message='stable slot already has a replacement today'; end if;
  select count(*),min(device_id) into v_device_count,v_device from public.devices where active=true and assigned_employee_id=v_old.id;
  if v_device_count=0 then
    select count(*),min(d.device_id) into v_device_count,v_device
    from public.devices d where d.active=true and d.assigned_employee_id is null and exists(
      select 1 from public.custodial_employee_device_assignment_history h where h.device_id=d.id and h.previous_employee_id=v_old.id and h.new_employee_id is null
        and not exists(select 1 from public.custodial_employee_device_assignment_history newer where newer.device_id=h.device_id and (newer.changed_at,newer.assignment_change_id)>(h.changed_at,h.assignment_change_id))
    );
  end if;
  if v_device_count>1 then raise exception using errcode='23514',message='replacement phone is ambiguous; assign one phone to the stable slot before retrying'; end if;
  if v_old.active then v_status:=public.custodial_set_employee_active(v_old.id,false,p_manager_id,p_reason,true);
  else update public.msg_users set is_active=false,updated_at=statement_timestamp() where employee_id=v_old.id and is_active is true; v_status:=jsonb_build_object('changed',false,'employee',to_jsonb(v_old),'released_devices','[]'::jsonb); end if;
  v_created:=public.static_weekly_v5_create_replacement_employee(v_new_name,p_manager_id);
  v_new_employee_id:=(v_created#>>'{employee,id}')::uuid;
  if v_device is not null then v_assignment:=public.custodial_assign_employee_device(v_device,v_new_employee_id,p_manager_id,p_reason,false); end if;
  v_content_digest:=public.static_weekly_digest_jsonb(v_request-'expected_revision'-'actor_manager_id'-'operation');
  v_revision:=public.static_weekly_advance_authority(p_expected_revision,'replace_employee',p_manager_id,v_actor->>'manager_name',v_command,v_content_digest);
  insert into public.weekly_roster_slot_incumbencies(incumbency_id,slot_id,person_id,person_name_snapshot,effective_start,created_by_manager_id,created_by_manager_name_snapshot,content_digest)
  values(v_new_incumbency,p_slot_id,v_new_employee_id,v_new_name,v_effective_start,p_manager_id,v_actor->>'manager_name',v_content_digest);
  insert into public.weekly_roster_slot_incumbency_closures(closed_incumbency_id,replacement_incumbency_id,closed_at_effective_date,authority_revision,actor_manager_id,actor_manager_name_snapshot,content_digest)
  values(v_incumbent.incumbency_id,v_new_incumbency,v_effective_start,v_revision,p_manager_id,v_actor->>'manager_name',v_content_digest);
  insert into public.weekly_roster_slot_staffing_states(slot_id,employee_id,staffing_state,effective_start,authority_revision,actor_manager_id,actor_manager_name_snapshot,reason,content_digest)
  values(p_slot_id,v_new_employee_id,'working',v_effective_start,v_revision,p_manager_id,v_actor->>'manager_name',p_reason,v_content_digest);
  v_response:=public.static_weekly_response_json('replace_employee',v_revision,v_content_digest,v_request_digest,jsonb_build_object('slot_id',p_slot_id,'former_employee_id',v_old.id,'former_employee_name',v_old.display_name,'new_employee_id',v_new_employee_id,'new_employee_name',v_new_name,'new_employee_code',v_created#>>'{employee,employee_code}','effective_start',v_effective_start,'device_id',v_device,'phone_assignment',v_assignment,'former_employee_status',v_status));
  insert into public.weekly_schedule_command_receipts(command_id,actor_manager_id,actor_manager_name_snapshot,command_type,idempotency_key,expected_revision,request_digest,request_canonical_json,response_json,response_digest,content_digest)
  values(v_command,p_manager_id,v_actor->>'manager_name','replace_employee',p_idempotency_key,p_expected_revision,v_request_digest,v_request,v_response,v_response->>'output_digest',v_content_digest);
  return v_response;
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v5_create_replacement_employee(p_display_name text, p_manager_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_manager public.ops_manager_managers%rowtype; v_name text:=regexp_replace(btrim(coalesce(p_display_name,'')),'\s+',' ','g'); v_code text; v_employee public.employees%rowtype; v_user public.msg_users%rowtype;
begin
  v_manager:=public.custodial_assert_manager(p_manager_id);
  if length(v_name) not between 2 and 160 then raise exception using errcode='22023',message='Employee name must be between 2 and 160 characters.'; end if;
  if exists(select 1 from public.employees where active is true and lower(btrim(display_name))=lower(v_name)) then
    raise exception using errcode='23505',message='An active employee record with that name already exists.';
  end if;
  v_code:=public.custodial_next_employee_code();
  if v_code is null then raise exception using errcode='23514',message='No employee code is available for the replacement.'; end if;
  insert into public.employees(employee_code,display_name,active,role,notes)
  values(v_code,v_name,true,'staff','Fresh employee created by atomic stable-slot replacement') returning * into v_employee;
  insert into public.msg_users(employee_id,display_name,role,is_active)
  values(v_employee.id,v_employee.display_name,'employee',true) returning * into v_user;
  insert into public.custodial_employee_status_history(employee_id,employee_name,previous_active,new_active,changed_by_manager_id,change_reason,source,metadata_json)
  values(v_employee.id,v_employee.display_name,null,true,v_manager.manager_id,'employee_created','static_weekly_turnover',jsonb_build_object('employee_code',v_employee.employee_code,'msg_user_id',v_user.id));
  return jsonb_build_object('created',true,'employee',to_jsonb(v_employee),'messenger_user_id',v_user.id);
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v5_projection_source_identity(p_source jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare v_identity jsonb; v_version jsonb; v_slots jsonb; v_availability jsonb;
begin
  if jsonb_typeof(p_source) is distinct from 'object' then
    raise exception using errcode='23514',message='projection source must be one compiler input object';
  end if;
  if jsonb_typeof(p_source->'version')='object' then
    v_version:=p_source->'version';
  elsif jsonb_typeof(p_source->'versions')='array' and jsonb_array_length(p_source->'versions')=1 then
    v_version:=(p_source->'versions')->0;
  else
    raise exception using errcode='23514',message='projection source must carry exactly one recurring version';
  end if;
  v_version:=v_version-'id'-'publicationId'-'status'-'effectiveStart'-'effectiveEnd'-'namedAbsentSlotIds';
  if jsonb_typeof(v_version->'slotAvailability') is distinct from 'array' then
    raise exception using errcode='23514',message='projection source must retain recurring slot availability templates';
  end if;
  select coalesce(jsonb_agg(item-'status' order by ordinal),'[]'::jsonb) into v_availability
  from jsonb_array_elements(v_version->'slotAvailability') with ordinality as a(item,ordinal);
  v_version:=jsonb_set(v_version,'{slotAvailability}',v_availability,true);
  v_identity:=p_source-'serviceDate'-'version'-'versions';
  if jsonb_typeof(v_identity->'slots') is distinct from 'array' then
    raise exception using errcode='23514',message='projection source must carry stable roster slots';
  end if;
  select coalesce(jsonb_agg(slot-'incumbencies' order by ordinal),'[]'::jsonb) into v_slots
  from jsonb_array_elements(v_identity->'slots') with ordinality as s(slot,ordinal);
  v_identity:=jsonb_set(v_identity,'{slots}',v_slots,true);
  return jsonb_set(v_identity,'{version}',v_version,true);
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v5_read_employee_day(p_service_date date, p_employee_id uuid, p_now timestamp with time zone DEFAULT now())
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_version uuid; v_publication uuid; v_week_start date; v_projection uuid; v_projection_revision bigint; v_staffing_revision bigint; v_status text:='missing_projection'; v_employee public.employees%rowtype; v_slot uuid; v_slot_count integer; v_shift_start time; v_shift_end time; v_staffing_state text; v_items jsonb:='[]'::jsonb; v_current jsonb:='[]'::jsonb; v_local_date date; v_local_time time; v_phase text; v_notice text;
begin
  if p_service_date is null or p_employee_id is null or p_now is null then raise exception using errcode='22023',message='employee day requires service_date, employee_id, and current time'; end if;
  v_version:=public.static_weekly_effective_version(p_service_date);
  if v_version is null then return jsonb_build_object('governed',false,'service_date',p_service_date::text,'source','legacy_daily_schedule'); end if;
  select p.publication_id into v_publication from public.weekly_schedule_publications p where p.version_id=v_version;
  v_week_start:=p_service_date-(extract(isodow from p_service_date)::integer-1);
  select p.projection_id,(r.response_json->>'revision')::bigint into v_projection,v_projection_revision from public.weekly_schedule_compiled_projections p
  join public.weekly_schedule_command_receipts r on r.command_type='materialize_projection' and r.response_json#>>'{data,projection_id}'=p.projection_id::text
  where p.publication_id=v_publication and p.week_start=v_week_start
    and p.exception_set_digest=public.static_weekly_digest_jsonb(public.static_weekly_accepted_exception_set(v_publication,v_week_start))
  order by (r.response_json->>'revision')::bigint desc,r.command_id desc limit 1;
  select max(s.authority_revision) into v_staffing_revision from public.weekly_roster_slot_staffing_states s where s.effective_start<=v_week_start+6;
  if v_projection_revision is not null and (v_staffing_revision is null or v_projection_revision>v_staffing_revision) then v_status:='current';
  elsif v_projection is not null then v_status:='stale_staffing_change'; end if;
  select * into v_employee from public.employees e where e.id=p_employee_id;
  if not found then raise exception using errcode='P0002',message='employee not found'; end if;
  if v_status<>'current' then return jsonb_build_object('governed',true,'source','static_weekly_projection','service_date',p_service_date::text,'week_start',v_week_start::text,'publication_id',v_publication::text,'projection_id',case when v_projection is null then null else v_projection::text end,'projection_status',v_status,'projection_authority_revision',v_projection_revision,'staffing_authority_revision',v_staffing_revision,'employee_id',v_employee.id::text,'employee_name',v_employee.display_name,'items','[]'::jsonb,'all_items','[]'::jsonb,'current_items','[]'::jsonb); end if;
  select count(*),(array_agg(r.slot_id order by r.slot_id))[1] into v_slot_count,v_slot from public.v_weekly_roster_slot_incumbency_ranges r
  where r.person_id=p_employee_id and r.effective_start<=p_service_date and (r.effective_end is null or p_service_date<r.effective_end);
  if v_slot_count>1 then raise exception using errcode='23514',message='employee resolves to more than one effective weekly roster slot'; end if;
  if v_slot is not null then
    select a.shift_start,a.shift_end into v_shift_start,v_shift_end from public.weekly_schedule_slot_availability a
    where a.version_id=v_version and a.slot_id=v_slot and a.day_of_week=extract(dow from p_service_date)::integer;
    select s.staffing_state into v_staffing_state from public.weekly_roster_slot_staffing_states s where s.slot_id=v_slot and s.effective_start<=p_service_date order by s.effective_start desc,s.authority_revision desc limit 1;
  end if;
  select coalesce(jsonb_agg(jsonb_build_object(
    'id',o.occurrence_id::text,'occurrence_id',o.occurrence_id::text,'projection_id',o.projection_id::text,'service_date',o.service_date::text,
    'segment_number',row_number_value,'location_id',case when o.location_id is null then null else o.location_id::text end,
    'group_code',o.location_code_snapshot,'group_name',o.location_name_snapshot,'location_group_code',o.location_code_snapshot,'location_group_name',o.location_name_snapshot,
    'location_name',o.location_name_snapshot,'included_locations',jsonb_build_array(o.location_name_snapshot),
    'coverage_start',to_char(o.coverage_start,'HH24:MI'),'coverage_end',to_char(o.coverage_end,'HH24:MI'),'start_time',to_char(o.coverage_start,'HH24:MI'),'end_time',to_char(o.coverage_end,'HH24:MI'),
    'coverage_purpose',coalesce(nullif(o.authority_facts_json#>>'{work_snapshot,coveragePurpose}',''),nullif(o.authority_facts_json#>>'{work_snapshot,purpose}',''),'area_owner'),'purpose',coalesce(nullif(o.authority_facts_json#>>'{work_snapshot,coveragePurpose}',''),nullif(o.authority_facts_json#>>'{work_snapshot,purpose}',''),'area_owner'),
    'section_title',case coalesce(nullif(o.authority_facts_json#>>'{work_snapshot,coveragePurpose}',''),nullif(o.authority_facts_json#>>'{work_snapshot,purpose}',''),'area_owner') when 'area_owner' then 'Primary area coverage' when 'restroom_upkeep' then 'Restroom upkeep' when 'deep_clean' then 'Deep cleaning' when 'late_coverage' then 'Late coverage' when 'lunch_coverage' then 'Lunch coverage' else initcap(replace(coalesce(nullif(o.authority_facts_json#>>'{work_snapshot,coveragePurpose}',''),nullif(o.authority_facts_json#>>'{work_snapshot,purpose}',''),'assigned coverage'),'_',' ')) end,
    'source_type','static_weekly_projection','owner_type','EMPLOYEE','status','ASSIGNED','load_points',coalesce((o.authority_facts_json#>>'{work_snapshot,serviceEffortMinutes}')::numeric,1),'notes',null,
    'is_public_restroom',(lower(o.location_name_snapshot) like '%restroom%' or lower(o.location_name_snapshot) like '%bathroom%')
  ) order by o.coverage_start,o.coverage_end,o.location_name_snapshot,o.work_id),'[]'::jsonb) into v_items
  from (select occurrence.*,row_number() over(order by coverage_start,coverage_end,location_name_snapshot,work_id) as row_number_value from public.weekly_schedule_occurrences occurrence where occurrence.projection_id=v_projection and occurrence.service_date=p_service_date and occurrence.owner_person_id_snapshot=p_employee_id and occurrence.state='created') o;
  v_local_date:=(p_now at time zone 'America/Chicago')::date; v_local_time:=(p_now at time zone 'America/Chicago')::time;
  if v_local_date=p_service_date then select coalesce(jsonb_agg(item order by ordinal),'[]'::jsonb) into v_current from jsonb_array_elements(v_items) with ordinality current_item(item,ordinal) where (item->>'coverage_start')::time<=v_local_time and v_local_time<(item->>'coverage_end')::time; end if;
  if v_employee.active is not true or coalesce(v_staffing_state,'working')<>'working' or v_shift_start is null or v_shift_end is null then v_phase:='off_day'; v_notice:='You are not scheduled to work today.';
  elsif jsonb_array_length(v_items)=0 then v_phase:='schedule_missing'; v_notice:='Your shift is active, but no assignments were published. Contact a Custodial Manager.';
  elsif v_local_date<p_service_date or (v_local_date=p_service_date and v_local_time<v_shift_start) then v_phase:='before_shift'; v_notice:=format('Your assigned areas are below. Your shift begins at %s.',to_char(v_shift_start,'FMHH12:MI AM'));
  elsif v_local_date>p_service_date or (v_local_date=p_service_date and v_local_time>=v_shift_end) then v_phase:='after_shift'; v_notice:='Your shift is complete. Today''s assigned areas remain below.';
  elsif jsonb_array_length(v_current)=0 then v_phase:='between_assignments'; v_notice:='No coverage window is active at this moment. Your assigned areas remain below.';
  else v_phase:='assigned_areas'; v_notice:='Your assigned areas are shown below. Choose the practical cleaning order.'; end if;
  return jsonb_build_object('ok',true,'governed',true,'source','static_weekly_projection','contract_version','static-weekly-employee-day.v1','service_date',p_service_date::text,'week_start',v_week_start::text,'publication_id',v_publication::text,'projection_id',v_projection::text,'projection_status',v_status,'projection_authority_revision',v_projection_revision,'staffing_authority_revision',v_staffing_revision,'employee_id',v_employee.id::text,'employee_name',v_employee.display_name,'employee_code',v_employee.employee_code,'employee',jsonb_build_object('id',v_employee.id::text,'display_name',v_employee.display_name,'employee_code',v_employee.employee_code),'shift',case when v_shift_start is null or v_shift_end is null then null else jsonb_build_object('start',to_char(v_shift_start,'HH12:MI AM'),'end',to_char(v_shift_end,'HH12:MI AM'),'shift_start',to_char(v_shift_start,'HH24:MI'),'shift_end',to_char(v_shift_end,'HH24:MI'),'active',v_employee.active and coalesce(v_staffing_state,'working')='working') end,'phase',v_phase,'notice',v_notice,'items',v_current,'all_items',v_items,'current_items',v_current,'assignment_count',jsonb_array_length(v_items),'schedule_status',case when v_phase='off_day' then 'off' when v_phase='schedule_missing' then 'missing_assignments' when v_phase='after_shift' then 'completed' when v_phase='between_assignments' then 'between_assignments' else 'scheduled' end);
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v5_registered_source_identity(p_source jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare v_identity jsonb; v_version jsonb; v_slots jsonb;
begin
  if jsonb_typeof(p_source) is distinct from 'object' or coalesce(p_source->'exceptions','[]'::jsonb)<>'[]'::jsonb then
    raise exception using errcode='23514',message='registered scheduler source must be one exception-free recurring compiler input';
  end if;
  if jsonb_typeof(p_source->'version')='object' then v_version:=p_source->'version';
  elsif jsonb_typeof(p_source->'versions')='array' and jsonb_array_length(p_source->'versions')=1 then v_version:=(p_source->'versions')->0;
  else raise exception using errcode='23514',message='registered scheduler source must carry exactly one recurring version'; end if;
  v_version:=v_version-'id'-'publicationId'-'status'-'effectiveStart'-'effectiveEnd';
  v_identity:=p_source-'serviceDate'-'exceptions'-'version'-'versions';
  if jsonb_typeof(v_identity->'slots') is distinct from 'array' then raise exception using errcode='23514',message='registered scheduler source must carry stable roster slots'; end if;
  select coalesce(jsonb_agg(slot-'incumbencies' order by ordinal),'[]'::jsonb) into v_slots
  from jsonb_array_elements(v_identity->'slots') with ordinality as s(slot,ordinal);
  v_identity:=jsonb_set(v_identity,'{slots}',v_slots,true);
  return jsonb_set(v_identity,'{version}',v_version,true);
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v5_source_availability_template(p_slot_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_source jsonb; v_version jsonb; v_rows jsonb;
begin
  select d.canonical_source into v_source
  from public.static_weekly_authority_source_documents d
  join public.weekly_schedule_versions v on v.authority_source_id=d.source_id
  where v.lifecycle_state='published' and d.active=true and d.retired_at is null
    and exists(select 1 from jsonb_array_elements(d.canonical_source->'slots') slot where slot->>'id'=p_slot_id::text)
  order by v.published_at desc,v.version_id desc limit 1;
  if jsonb_typeof(v_source->'version')='object' then v_version:=v_source->'version';
  elsif jsonb_typeof(v_source->'versions')='array' and jsonb_array_length(v_source->'versions')=1 then v_version:=(v_source->'versions')->0;
  end if;
  select coalesce(jsonb_agg(item order by ordinal),'[]'::jsonb) into v_rows
  from jsonb_array_elements(coalesce(v_version->'slotAvailability','[]'::jsonb)) with ordinality as a(item,ordinal)
  where item->>'slotId'=p_slot_id::text;
  if jsonb_array_length(coalesce(v_rows,'[]'::jsonb))=0 then
    raise exception using errcode='23514',message='employee turnover requires a verified recurring availability template for the stable slot';
  end if;
  return v_rows;
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_version_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
  if tg_op='DELETE' then raise exception using errcode='23514',message='weekly versions are immutable'; end if;
  if tg_op='INSERT' then
    if new.lifecycle_state='published' and current_setting('app.static_weekly_publish_write',true) is distinct from 'on' then raise exception using errcode='23514',message='published versions require v2 publication'; end if;
    return new;
  end if;
  if old.lifecycle_state='draft' and current_setting('app.static_weekly_publish_write',true)='on' and new.lifecycle_state='published' and new.revision=old.revision then return new; end if;
  -- v3 binds a just-created v2 draft to a registered immutable source inside
  -- the same SECURITY DEFINER transaction. No other field/revision may move.
  if old.lifecycle_state='draft' and current_setting('app.static_weekly_source_bind',true)='on' and old.authority_source_id is null and new.authority_source_id is not null and (to_jsonb(new)-'authority_source_id')=(to_jsonb(old)-'authority_source_id') then return new; end if;
  if old.lifecycle_state<>'draft' or current_setting('app.static_weekly_draft_write',true) is distinct from 'on' or new.lifecycle_state<>'draft' or new.revision<>old.revision+1 then raise exception using errcode='23514',message='draft versions require a revision-checked v2 command'; end if;
  return new;
end
$function$

CREATE OR REPLACE FUNCTION public.tool_commit_cleaning_workflow_authoritative(p_client_session_id text, p_client_completion_id text, p_device_id text, p_location_code text, p_client_started_at text, p_client_ended_at text, p_response_json jsonb, p_scan_evidence jsonb, p_correlation_id text, p_context_id text, p_submission_proof text, p_authenticated_credential_id text, p_native_finish_scan_entry_id text, p_native_completion_attestation_version text, p_native_completion_attestation text, p_native_route_proof_secret text, p_backend_execution_secret text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_completion_id uuid; v_context_id uuid; v_finish_scan_entry_id uuid; v_result jsonb; v_started_at timestamptz; v_completed_at timestamptz;
  v_native_completed_at timestamptz; v_attestation_sha256 text;
begin
  begin
    v_completion_id:=lower(btrim(coalesce(p_client_completion_id,'')))::uuid;
  exception when others then
    raise exception using errcode='22023',message='p_client_completion_id must be a UUID';
  end;
  perform public.custodial_require_native_route_proof_secret(p_native_route_proof_secret);
  if btrim(coalesce(p_native_completion_attestation_version,''))<>'custodial-native-completion.v2'
     or lower(btrim(coalesce(p_native_completion_attestation,''))) !~ '^[0-9a-f]{64}$' then
    raise exception using errcode='42501',message='a verified native completion attestation is required';
  end if;
  begin
    v_context_id:=lower(btrim(p_context_id))::uuid;
    v_finish_scan_entry_id:=lower(btrim(p_native_finish_scan_entry_id))::uuid;
    v_native_completed_at:=btrim(p_client_ended_at)::timestamptz;
  exception when others then
    raise exception using errcode='22023',message='native completion evidence is malformed';
  end;
  if not isfinite(v_native_completed_at) then
    raise exception using errcode='22023',message='native completion evidence is malformed';
  end if;
  if jsonb_typeof(p_scan_evidence)<>'array'
     or (select count(*) from jsonb_array_elements(p_scan_evidence) e where e->>'event_type'='scan_finish')<>1
     or not exists(
       select 1 from jsonb_array_elements(p_scan_evidence) e
       where e->>'event_type'='scan_finish'
         and lower(e->>'client_event_id')=v_finish_scan_entry_id::text
         and e->>'result'='ok'
         and e->>'scanned_at'=public.custodial_canonical_utc_millis(v_native_completed_at)
         and e->'payload_json'->>'entry_source'='native-nfc'
     ) then
    raise exception using errcode='42501',message='the signed physical NFC finish scan is required';
  end if;
  v_attestation_sha256:=encode(extensions.digest(convert_to(lower(btrim(p_native_completion_attestation)),'UTF8'),'sha256'),'hex');
  if exists(
    select 1 from public.custodial_offline_actor_contexts c where c.context_id=v_context_id
      and (c.native_start_attestation_version is distinct from 'custodial-native-start.v1'
        or c.native_scan_entry_id is null
        or (c.native_completion_attestation_version is not null and
          (c.native_completion_attestation_version<>p_native_completion_attestation_version
            or c.native_completion_attestation_sha256<>v_attestation_sha256
            or c.native_completed_at<>v_native_completed_at
            or c.native_finish_scan_entry_id<>v_finish_scan_entry_id)))
  ) then
    raise exception using errcode='23505',message='native completion attestation does not match the frozen occurrence';
  end if;
  v_result:=public.custodial_commit_offline_occurrence(
    p_client_session_id,v_completion_id::text,p_device_id,p_location_code,p_client_started_at,p_client_ended_at,
    p_response_json,p_scan_evidence,p_correlation_id,p_context_id,p_submission_proof,p_authenticated_credential_id,p_backend_execution_secret
  );
  if v_result->>'status'='closed' then
    update public.custodial_offline_actor_contexts
       set native_completion_attestation_version=p_native_completion_attestation_version,
           native_completion_attestation_sha256=v_attestation_sha256,
           native_completed_at=v_native_completed_at,
           native_finish_scan_entry_id=v_finish_scan_entry_id
     where context_id=v_context_id and native_completion_attestation_version is null;
    if not found and not exists(
      select 1 from public.custodial_offline_actor_contexts c
      where c.context_id=v_context_id
        and c.native_completion_attestation_version=p_native_completion_attestation_version
        and c.native_completion_attestation_sha256=v_attestation_sha256
        and c.native_completed_at=v_native_completed_at
        and c.native_finish_scan_entry_id=v_finish_scan_entry_id
    ) then
      raise exception using errcode='23505',message='native completion attestation does not match the frozen occurrence';
    end if;
  end if;
  begin
    v_started_at:=nullif(v_result->>'started_at','')::timestamptz;
    v_completed_at:=nullif(coalesce(v_result->>'completed_at',v_result->>'ended_at'),'')::timestamptz;
  exception when others then
    return v_result||jsonb_build_object('native_completion_attested',v_result->>'status'='closed');
  end;
  return v_result || jsonb_strip_nulls(jsonb_build_object(
    'started_at',public.custodial_canonical_utc_millis(v_started_at),
    'ended_at',public.custodial_canonical_utc_millis(v_completed_at),
    'completed_at',public.custodial_canonical_utc_millis(v_completed_at),
    'native_completion_attested',v_result->>'status'='closed',
    'native_finish_scan_entry_id',case when v_result->>'status'='closed' then v_finish_scan_entry_id end
  ));
end
$function$

CREATE OR REPLACE FUNCTION public.tool_complete_session_authoritative(p_session_uuid text, p_response_json jsonb, p_device_id text, p_client_completion_id text, p_authenticated_credential_id text, p_backend_execution_secret text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_session record;
  v_context public.custodial_offline_actor_contexts%rowtype;
  v_existing public.custodial_offline_reconciliation_records%rowtype;
  v_proof text := encode(extensions.gen_random_bytes(32), 'hex');
  v_occurrence_fingerprint text;
  v_assignment_change_id uuid;
begin
  perform public.custodial_require_backend_execution_secret(p_backend_execution_secret);
  select s.*, d.device_id as canonical_device_id, l.location_code, c.credential_id
    into v_session from public.sessions s join public.devices d on d.id=s.device_id join public.locations l on l.id=s.location_id
    join public.device_auth_credentials c on c.credential_id=nullif(lower(btrim(p_authenticated_credential_id)),'')::uuid and c.device_id=s.device_id
   where s.session_uuid=p_session_uuid or s.client_session_id=p_session_uuid
   order by case when s.session_uuid=p_session_uuid then 0 else 1 end limit 1 for update of s;
  if v_session.id is null or upper(btrim(coalesce(p_device_id,'')))<>upper(v_session.canonical_device_id) then
    raise exception using errcode='42501', message='legacy completion is not bound to an authenticated server session';
  end if;
  -- A legacy caller never receives the one-time proof.  Its exact retry is
  -- therefore resolved from the immutable reconciliation record, while any
  -- altered completion id or response is fenced as an identity conflict.
  select * into v_existing from public.custodial_offline_reconciliation_records
    where client_session_id=v_session.client_session_id or client_completion_id=btrim(p_client_completion_id)
    order by case when client_completion_id=btrim(p_client_completion_id) then 0 else 1 end
    limit 1 for update;
  if v_existing.reconciliation_id is not null then
    if v_existing.client_session_id=v_session.client_session_id
       and v_existing.client_completion_id=btrim(p_client_completion_id)
       and v_existing.payload_json=jsonb_build_object('response_json',coalesce(p_response_json,'{}'::jsonb),'scan_evidence','[]'::jsonb) then
      insert into public.custodial_offline_reconciliation_audits(reconciliation_id,event_type,evidence_json)
      values(v_existing.reconciliation_id,'replayed',jsonb_build_object('exact_legacy_adapter_replay',true));
      return v_existing.result_json || jsonb_build_object('reconciliation_id',v_existing.reconciliation_id,'replayed',true);
    end if;
    return public.custodial_quarantine_offline_submission(
      v_session.client_session_id,p_client_completion_id,v_existing.context_id,
      encode(extensions.digest(convert_to(v_session.client_session_id||':'||coalesce(p_client_completion_id,'')||':legacy-conflict','UTF8'),'sha256'),'hex'),
      jsonb_build_object('response_json',coalesce(p_response_json,'{}'::jsonb),'scan_evidence','[]'::jsonb),
      'legacy_adapter_payload_fingerprint_conflict','{}'::jsonb,p_backend_execution_secret);
  end if;
  select * into v_context from public.custodial_offline_actor_contexts where client_session_id=v_session.client_session_id for update;
  if v_context.context_id is null then
    select assignment_change_id into v_assignment_change_id from public.custodial_employee_device_assignment_history
      where device_id=v_session.device_id and new_employee_id=v_session.employee_id order by changed_at desc limit 1;
    if v_assignment_change_id is null then raise exception using errcode='42501', message='legacy completion has no authoritative assignment epoch'; end if;
    v_occurrence_fingerprint := encode(extensions.digest(convert_to(jsonb_build_object('legacy_server_session_id',v_session.id::text,'employee_id',v_session.employee_id::text,'device_id',v_session.device_id::text,'location_id',v_session.location_id::text,'started_at',v_session.started_at,'client_session_id',v_session.client_session_id)::text,'UTF8'),'sha256'),'hex');
    insert into public.custodial_offline_actor_contexts(client_session_id,device_id,employee_id,credential_id,assignment_epoch,assignment_change_id,location_id,canonical_location_code,location_aliases,started_at,occurrence_fingerprint,expires_at)
    select v_session.client_session_id,v_session.device_id,v_session.employee_id,v_session.credential_id,d.assignment_epoch,v_assignment_change_id,v_session.location_id,v_session.location_code,jsonb_build_array(v_session.location_code),v_session.started_at,v_occurrence_fingerprint,now()+interval '7 days'
      from public.devices d where d.id=v_session.device_id
    returning * into v_context;
    insert into public.custodial_offline_submission_proofs(context_id,proof_digest) values(v_context.context_id,encode(extensions.digest(convert_to(v_proof,'UTF8'),'sha256'),'hex'));
  else
    raise exception using errcode='0A000', message='legacy completion must use the existing canonical occurrence adapter';
  end if;
  return public.custodial_commit_offline_occurrence(v_context.client_session_id,p_client_completion_id,v_session.canonical_device_id,v_session.location_code,
    v_context.started_at::text,coalesce(v_session.ended_at,now())::text,coalesce(p_response_json,'{}'::jsonb),'[]'::jsonb,
    'legacy-completion:'||p_client_completion_id,v_context.context_id::text,v_proof,v_context.credential_id::text,p_backend_execution_secret);
end
$function$

CREATE OR REPLACE FUNCTION public.tool_finish_session_exact(p_session_identifier text, p_device_id text, p_finish_operation_id uuid, p_client_ended_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_identifier text := nullif(btrim(coalesce(p_session_identifier, '')), '');
  v_device_pk uuid;
  v_canonical_device_id text;
  v_session public.sessions%rowtype;
  v_location public.locations%rowtype;
  v_employee public.employees%rowtype;
  v_ended_at timestamptz;
  v_duration_minutes integer;
  v_replayed boolean := false;
begin
  if v_identifier is null then
    raise exception using errcode = '22023', message = 'p_session_identifier is required';
  end if;
  if p_finish_operation_id is null then
    raise exception using errcode = '22023', message = 'p_finish_operation_id is required';
  end if;

  select d.id, d.device_id
    into v_device_pk, v_canonical_device_id
  from public.device_aliases da
  join public.devices d on d.id = da.canonical_device_id and d.active is true
  where da.active is true
    and upper(btrim(da.alias_identifier)) = upper(btrim(p_device_id))
  union all
  select d.id, d.device_id
  from public.devices d
  where d.active is true
    and upper(btrim(d.device_id)) = upper(btrim(p_device_id))
  limit 1;

  if v_device_pk is null then
    raise exception 'Active device not found: %', p_device_id;
  end if;

  if exists (
    select 1 from public.sessions s
    where s.finish_operation_id = p_finish_operation_id
      and s.session_uuid <> v_identifier
      and coalesce(s.client_session_id, '') <> v_identifier
  ) then
    raise exception using errcode = '23505', message = 'Finish operation id is already bound to another session';
  end if;

  select s.* into v_session
  from public.sessions s
  where (s.session_uuid = v_identifier or s.client_session_id = v_identifier)
    and s.device_id = v_device_pk
  order by case when s.session_uuid = v_identifier then 0 else 1 end
  for update
  limit 1;

  if v_session.id is null then
    raise exception 'Session not found for exact server/client identifier and device: %', v_identifier;
  end if;

  select * into v_location from public.locations where id = v_session.location_id;
  select * into v_employee from public.employees where id = v_session.employee_id;

  if v_session.status = 'cancelled' then
    return jsonb_build_object(
      'session_uuid', v_session.session_uuid,
      'client_session_id', v_session.client_session_id,
      'status', 'cancelled',
      'terminal', true,
      'discard_local_workflow', true,
      'replayed', true
    );
  end if;

  if v_session.status not in ('active', 'pending_submit', 'closed') then
    raise exception 'Session % cannot transition from status %', v_session.session_uuid, v_session.status;
  end if;

  if v_session.finish_operation_id is not null
     and v_session.finish_operation_id <> p_finish_operation_id then
    raise exception using errcode = '23505', message = 'Session was already finished by another operation id';
  end if;

  if v_session.status = 'active' then
    -- Server time is authoritative. The client timestamp is intentionally not
    -- used to calculate operational duration.
    v_ended_at := now();
    v_duration_minutes := greatest(0, round(extract(epoch from (v_ended_at - v_session.started_at)) / 60.0));
    update public.sessions s
    set status = 'pending_submit',
        ended_at = v_ended_at,
        duration_minutes = v_duration_minutes,
        duration_display = v_duration_minutes::text || ' min',
        finish_operation_id = p_finish_operation_id,
        updated_at = now()
    where s.id = v_session.id
    returning * into v_session;
  else
    v_replayed := v_session.finish_operation_id = p_finish_operation_id;
    if v_session.finish_operation_id is null then
      update public.sessions s
      set finish_operation_id = p_finish_operation_id,
          updated_at = now()
      where s.id = v_session.id
      returning * into v_session;
    end if;
  end if;

  return jsonb_build_object(
    'session_uuid', v_session.session_uuid,
    'client_session_id', v_session.client_session_id,
    'location_name', v_location.location_name,
    'employee_name', v_employee.display_name,
    'device_id', v_canonical_device_id,
    'status', v_session.status,
    'started_at', v_session.started_at,
    'ended_at', v_session.ended_at,
    'duration_minutes', v_session.duration_minutes,
    'duration_display', v_session.duration_display,
    'location_type', v_location.location_type,
    'form_type', v_location.form_type,
    'finish_operation_id', coalesce(v_session.finish_operation_id, p_finish_operation_id),
    'client_ended_at_received', p_client_ended_at is not null,
    'replayed', v_replayed
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.tool_get_offline_scan_authority_snapshot(p_device_id text, p_authenticated_credential_id text, p_backend_execution_secret text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_device record; v_credential public.device_auth_credentials%rowtype;
  v_generated_at timestamptz := date_trunc('milliseconds',clock_timestamp()); v_expires_at timestamptz;
  v_locations jsonb; v_snapshot_id text;
begin
  perform public.custodial_require_backend_execution_secret(p_backend_execution_secret);
  select d.id,d.device_id,d.assigned_employee_id,d.assignment_epoch,e.display_name employee_name,e.active employee_active
    into v_device from public.devices d join public.employees e on e.id=d.assigned_employee_id
   where upper(btrim(d.device_id))=upper(btrim(coalesce(p_device_id,''))) and d.active=true;
  begin
    select * into v_credential from public.device_auth_credentials
     where credential_id=nullif(lower(btrim(coalesce(p_authenticated_credential_id,''))),'')::uuid for share;
  exception when others then
    raise exception using errcode='42501',message='an active authenticated employee-device credential is required';
  end;
  if v_device.id is null or v_device.assigned_employee_id is null or v_device.employee_active is not true
     or v_credential.credential_id is null or v_credential.device_id<>v_device.id or v_credential.confirmed_at is null
     or v_credential.revoked_at is not null or v_credential.expires_at<=v_generated_at then
    raise exception using errcode='42501',message='an active authenticated employee-device assignment is required';
  end if;
  select coalesce(jsonb_agg(jsonb_build_object('location_code',l.location_code,'location_name',l.location_name,
    'location_type',l.location_type,'form_type',coalesce(l.form_type,l.location_type)) order by l.location_code),'[]'::jsonb)
    into v_locations from public.locations l where l.active=true;
  v_expires_at:=date_trunc('milliseconds',least(v_generated_at+interval '24 hours',v_credential.expires_at));
  v_snapshot_id:=encode(extensions.digest(convert_to(jsonb_build_object('contract_version','scan.v4.snapshot-bound-authority',
    'device_id',v_device.device_id,'employee_id',v_device.assigned_employee_id::text,'assignment_epoch',v_device.assignment_epoch,
    'credential_id',v_credential.credential_id::text,'generated_at',public.custodial_canonical_utc_millis(v_generated_at),'expires_at',public.custodial_canonical_utc_millis(v_expires_at),'locations',v_locations)::text,'UTF8'),'sha256'),'hex');
  insert into public.custodial_offline_scan_authority_snapshots(snapshot_id,device_id,employee_id,assignment_epoch,credential_id,generated_at,expires_at,locations_json)
  values(v_snapshot_id,v_device.id,v_device.assigned_employee_id,v_device.assignment_epoch,v_credential.credential_id,v_generated_at,v_expires_at,v_locations)
  on conflict(snapshot_id) do nothing;
  return jsonb_build_object('schema_version','offline-scan-snapshot.v2','contract_version','scan.v4.snapshot-bound-authority',
    'snapshot_id',v_snapshot_id,'canonical_device_id',v_device.device_id,'employee_id',v_device.assigned_employee_id,
    'employee_name',v_device.employee_name,'assignment_epoch',v_device.assignment_epoch,'credential_id',v_credential.credential_id,
    'generated_at',public.custodial_canonical_utc_millis(v_generated_at),'expires_at',public.custodial_canonical_utc_millis(v_expires_at),'locations',v_locations);
end $function$
